window.ATLAS_RAMSAR_NOTES = {"checked":"2026-10-29","document":"world-map/notes/India_103_Ramsar_Sites_Notes.md","sites":{"1209":{"name":"Kolleru Lake","state":"Andhra Pradesh","sections":[{"heading":"Location And Designation","facts":["**Location:** Between the Krishna and Godavari deltas · **Designation:** 19 August 2002 · **Registered Area:** 90,100 ha"]},{"heading":"Type","facts":["Broad, shallow **freshwater lake** that stores and balances floodwater between two delta systems; it is not a brackish lagoon merely because it lies near the coast."]},{"heading":"Water Connections","facts":["Receives seasonal streams including **Budameru and Tammileru** and numerous drains; excess water reaches the sea through the **Upputeru** drainage channel. Tidal intrusion can influence the southeastern transition/outlet area, especially in low-flow periods."]},{"heading":"Wildlife","facts":["Important feeding and breeding landscape for waterbirds, including **spot-billed pelican [NT]**; also supports capture fisheries and agricultural livelihoods."]},{"heading":"Pressures","facts":["Conversion to aquaculture ponds and agriculture, embankments, obstructed drains and pollution reduce natural water spread and flood-storage capacity."]},{"heading":"Distinction","facts":["The Ramsar boundary and the Kolleru Wildlife Sanctuary’s notified area need not be identical; water-level contours and seasonal inundation matter in interpreting area claims."]}],"markdown":"# Kolleru Lake\n\n**Location:** Between the Krishna and Godavari deltas · **Designation:** 19 August 2002 · **Registered Area:** 90,100 ha\n\n- **Type:** Broad, shallow **freshwater lake** that stores and balances floodwater between two delta systems; it is not a brackish lagoon merely because it lies near the coast.\n- **Water Connections:** Receives seasonal streams including **Budameru and Tammileru** and numerous drains; excess water reaches the sea through the **Upputeru** drainage channel. Tidal intrusion can influence the southeastern transition/outlet area, especially in low-flow periods.\n- **Wildlife:** Important feeding and breeding landscape for waterbirds, including **spot-billed pelican [NT]**; also supports capture fisheries and agricultural livelihoods.\n- **Pressures:** Conversion to aquaculture ponds and agriculture, embankments, obstructed drains and pollution reduce natural water spread and flood-storage capacity.\n- **Distinction:** The Ramsar boundary and the Kolleru Wildlife Sanctuary’s notified area need not be identical; water-level contours and seasonal inundation matter in interpreting area claims.\n","species":["spot-billed pelican"]},"2597":{"name":"Glaw Lake","state":"Arunachal Pradesh","sections":[{"heading":"Location And Designation","facts":["**Location:** Lohit district, Kamlang protected landscape · **Designation:** 21 January 2026 · **Registered Area:** 129 ha"]},{"heading":"Type","facts":["**Freshwater mountain lake** supplied by perennial streams within **Kamlang Tiger Reserve and Wildlife Sanctuary** in the Eastern Himalayas."]},{"heading":"Catchment","facts":["Forested slopes with diverse trees and orchids regulate runoff and protect lake water quality; Ramsar extent includes the lake–catchment relationship."]},{"heading":"Wildlife","facts":["**White-bellied heron [CR]** is a particularly important wetland bird association. The broader Kamlang landscape supports **tiger [EN]**, **leopard [VU]**, **clouded leopard [VU]** and **snow leopard [VU]**."]},{"heading":"Scope","facts":["Landscape-level species records do not establish that all four cats occupy the immediate lake shore or the same elevational habitat."]},{"heading":"Culture And Distinction","facts":["Sacred to local **Mishmi** communities; tourism and trekking need catchment-sensitive management. Announced as the 101st addition in 2026; official designation is **21 January 2026**."]}],"markdown":"# Glaw Lake\n\n**Location:** Lohit district, Kamlang protected landscape · **Designation:** 21 January 2026 · **Registered Area:** 129 ha\n\n- **Type:** **Freshwater mountain lake** supplied by perennial streams within **Kamlang Tiger Reserve and Wildlife Sanctuary** in the Eastern Himalayas.\n- **Catchment:** Forested slopes with diverse trees and orchids regulate runoff and protect lake water quality; Ramsar extent includes the lake–catchment relationship.\n- **Wildlife:** **White-bellied heron [CR]** is a particularly important wetland bird association. The broader Kamlang landscape supports **tiger [EN]**, **leopard [VU]**, **clouded leopard [VU]** and **snow leopard [VU]**.\n- **Scope:** Landscape-level species records do not establish that all four cats occupy the immediate lake shore or the same elevational habitat.\n- **Culture And Distinction:** Sacred to local **Mishmi** communities; tourism and trekking need catchment-sensitive management. Announced as the 101st addition in 2026; official designation is **21 January 2026**.\n","species":["white-bellied heron","tiger","leopard","clouded leopard","snow leopard"]},"1207":{"name":"Deepor Beel","state":"Assam","sections":[{"heading":"Location And Designation","facts":["**Location:** South-west of Guwahati, Brahmaputra floodplain · **Designation:** 19 August 2002 · **Registered Area:** 4,000 ha"]},{"heading":"Type","facts":["Permanent **freshwater beel** formed in an abandoned channel of the **Brahmaputra**. “Beel” denotes a wetland/depression, not necessarily an active river channel."]},{"heading":"Urban Function","facts":["Important storage for Guwahati’s stormwater; draining or filling the wetland reduces flood-buffering capacity."]},{"heading":"Ecology","facts":["Fish, aquatic vegetation and shallow feeding areas support migratory birds and scavenging waterbirds, notably **greater adjutant [NT]** and **lesser adjutant [NT]**."]},{"heading":"Connections","facts":["The lake is part of a larger floodplain and catchment system; maintaining incoming and outgoing drainage is essential alongside protecting open water."]},{"heading":"Pressures","facts":["Solid-waste disposal, sewage, railway and urban fragmentation, encroachment, invasive plants and unsustainable extraction impair habitat and water quality."]}],"markdown":"# Deepor Beel\n\n**Location:** South-west of Guwahati, Brahmaputra floodplain · **Designation:** 19 August 2002 · **Registered Area:** 4,000 ha\n\n- **Type:** Permanent **freshwater beel** formed in an abandoned channel of the **Brahmaputra**. “Beel” denotes a wetland/depression, not necessarily an active river channel.\n- **Urban Function:** Important storage for Guwahati’s stormwater; draining or filling the wetland reduces flood-buffering capacity.\n- **Ecology:** Fish, aquatic vegetation and shallow feeding areas support migratory birds and scavenging waterbirds, notably **greater adjutant [NT]** and **lesser adjutant [NT]**.\n- **Connections:** The lake is part of a larger floodplain and catchment system; maintaining incoming and outgoing drainage is essential alongside protecting open water.\n- **Pressures:** Solid-waste disposal, sewage, railway and urban fragmentation, encroachment, invasive plants and unsustainable extraction impair habitat and water quality.\n","species":["greater adjutant","lesser adjutant"]},"2579":{"name":"Gogabil Lake","state":"Bihar","sections":[{"heading":"Location And Designation","facts":["**Location:** Katihar district, Amdabad block · **Designation:** 13 May 2025 · **Registered Area:** 86.6 ha"]},{"heading":"Type And Rivers","facts":["**Freshwater oxbow wetland between the Ganga and Mahananda**; floodwater can reconnect it with the river systems."]},{"heading":"Community Protection","facts":["Recognized as **Bihar’s first Community Reserve**, managed with local participation; this legal/community arrangement is distinct from the Ramsar designation."]},{"heading":"Wildlife","facts":["Central Asian Flyway wintering habitat with **common pochard [VU]**; **Wallago attu [VU]** uses the wetland for breeding."]},{"heading":"Uses","facts":["Fisheries, irrigation and cattle access occur; maintaining seasonal water connections supports both aquatic organisms and livelihoods."]},{"heading":"Pressures And Contrast","facts":["Fertilizer and pesticide runoff can affect the productive food web. **Gogabil—Katihar, Ganga–Mahananda**; **Kabartal—Begusarai**."]}],"markdown":"# Gogabil Lake\n\n**Location:** Katihar district, Amdabad block · **Designation:** 13 May 2025 · **Registered Area:** 86.6 ha\n\n- **Type And Rivers:** **Freshwater oxbow wetland between the Ganga and Mahananda**; floodwater can reconnect it with the river systems.\n- **Community Protection:** Recognized as **Bihar’s first Community Reserve**, managed with local participation; this legal/community arrangement is distinct from the Ramsar designation.\n- **Wildlife:** Central Asian Flyway wintering habitat with **common pochard [VU]**; **Wallago attu [VU]** uses the wetland for breeding.\n- **Uses:** Fisheries, irrigation and cattle access occur; maintaining seasonal water connections supports both aquatic organisms and livelihoods.\n- **Pressures And Contrast:** Fertilizer and pesticide runoff can affect the productive food web. **Gogabil—Katihar, Ganga–Mahananda**; **Kabartal—Begusarai**.\n","species":["common pochard","wallago attu"]},"2576":{"name":"Gokul Jalashay","state":"Bihar","sections":[{"heading":"Location And Designation","facts":["**Location:** Buxar district, south bank of the Ganga · **Designation:** 13 May 2025 · **Registered Area:** 448 ha"]},{"heading":"Type","facts":["**Freshwater oxbow lake** on the southern margin of the Ganga floodplain."]},{"heading":"Seasonality","facts":["River flood pulses expand inundation after the monsoon; dry-season exposure creates marsh and cultivable areas. Land use changes with the water cycle."]},{"heading":"Ecology","facts":["Exposed shrubs and marshes provide feeding and breeding habitat before the monsoon, while wetter phases support aquatic organisms and waterbirds."]},{"heading":"Services","facts":["Flood buffering for nearby settlements, fishing, agriculture and irrigation; communities also undertake collective weed removal and catchment cleaning during a traditional festival."]},{"heading":"Distinction","facts":["**Gokul Jalashay—Buxar**; **Udaipur Jheel—West Champaran**; **Gogabil—Katihar**. The name “Jalashay” does not by itself prove that a waterbody is a dam reservoir: Gokul is an oxbow."]}],"markdown":"# Gokul Jalashay\n\n**Location:** Buxar district, south bank of the Ganga · **Designation:** 13 May 2025 · **Registered Area:** 448 ha\n\n- **Type:** **Freshwater oxbow lake** on the southern margin of the Ganga floodplain.\n- **Seasonality:** River flood pulses expand inundation after the monsoon; dry-season exposure creates marsh and cultivable areas. Land use changes with the water cycle.\n- **Ecology:** Exposed shrubs and marshes provide feeding and breeding habitat before the monsoon, while wetter phases support aquatic organisms and waterbirds.\n- **Services:** Flood buffering for nearby settlements, fishing, agriculture and irrigation; communities also undertake collective weed removal and catchment cleaning during a traditional festival.\n- **Distinction:** **Gokul Jalashay—Buxar**; **Udaipur Jheel—West Champaran**; **Gogabil—Katihar**. The name “Jalashay” does not by itself prove that a waterbody is a dam reservoir: Gokul is an oxbow.\n","species":[]},"2436":{"name":"Kabartal Wetland","state":"Bihar","sections":[{"heading":"Location And Designation","facts":["**Location:** Begusarai district · **Designation:** 21 July 2020 · **Registered Area:** 2,620 ha"]},{"heading":"Name And Type","facts":["**Kabartal**, also called **Kanwar/Kabar Jheel**, is a freshwater floodplain wetland and oxbow-lake system in north Bihar."]},{"heading":"Hydrology","facts":["Part of a wider complex of floodplain wetlands; monsoon inundation stores floodwater, while seasonal drawdown exposes marshes used for cultivation."]},{"heading":"Wildlife","facts":["Central Asian Flyway stopover with **Baer’s pochard [CR]** and **sociable lapwing [CR]**, plus threatened vultures and diverse fish."]},{"heading":"Ecological Mechanism","facts":["Seasonal flooding supports fish movement and nutrient exchange; drainage or canalization can sever these functions even when some open water remains."]},{"heading":"Pressures And Distinction","facts":["Water abstraction, drainage and altered flood connections are major threats. **Kabartal—Begusarai** is distinct from **Gogabil—Katihar** and **Gokul Jalashay—Buxar**."]}],"markdown":"# Kabartal Wetland\n\n**Location:** Begusarai district · **Designation:** 21 July 2020 · **Registered Area:** 2,620 ha\n\n- **Name And Type:** **Kabartal**, also called **Kanwar/Kabar Jheel**, is a freshwater floodplain wetland and oxbow-lake system in north Bihar.\n- **Hydrology:** Part of a wider complex of floodplain wetlands; monsoon inundation stores floodwater, while seasonal drawdown exposes marshes used for cultivation.\n- **Wildlife:** Central Asian Flyway stopover with **Baer’s pochard [CR]** and **sociable lapwing [CR]**, plus threatened vultures and diverse fish.\n- **Ecological Mechanism:** Seasonal flooding supports fish movement and nutrient exchange; drainage or canalization can sever these functions even when some open water remains.\n- **Pressures And Distinction:** Water abstraction, drainage and altered flood connections are major threats. **Kabartal—Begusarai** is distinct from **Gogabil—Katihar** and **Gokul Jalashay—Buxar**.\n","species":["baer’s pochard","sociable lapwing"]},"2545":{"name":"Nagi Bird Sanctuary","state":"Bihar","sections":[{"heading":"Location And Designation","facts":["**Location:** Jamui district · **Designation:** 11 October 2023 · **Registered Area:** 205.8 ha"]},{"heading":"Origin","facts":["**Reservoir created by damming the Nagi River**, surrounded by hills and predominantly dry-deciduous catchment forest."]},{"heading":"Wildlife","facts":["Important wintering habitat for **bar-headed goose [LC]**, with **Baer’s pochard [CR]** and **steppe eagle [EN]** recorded."]},{"heading":"Functions","facts":["Irrigation water, migratory-bird refuge, aquatic habitat, recreation and education; upstream catchment cover influences sediment entering the reservoir."]},{"heading":"Designation Dates","facts":["The sanctuary predates its Ramsar status. Its **Ramsar designation date is 11 October 2023**, although its inclusion was announced in 2024."]},{"heading":"Distinction","facts":["**Nagi and Nakti are two separate reservoirs and Ramsar sites in Jamui**. Nagi is particularly associated with bar-headed goose concentrations; Nakti with red-crested pochard concentrations."]}],"markdown":"# Nagi Bird Sanctuary\n\n**Location:** Jamui district · **Designation:** 11 October 2023 · **Registered Area:** 205.8 ha\n\n- **Origin:** **Reservoir created by damming the Nagi River**, surrounded by hills and predominantly dry-deciduous catchment forest.\n- **Wildlife:** Important wintering habitat for **bar-headed goose [LC]**, with **Baer’s pochard [CR]** and **steppe eagle [EN]** recorded.\n- **Functions:** Irrigation water, migratory-bird refuge, aquatic habitat, recreation and education; upstream catchment cover influences sediment entering the reservoir.\n- **Designation Dates:** The sanctuary predates its Ramsar status. Its **Ramsar designation date is 11 October 2023**, although its inclusion was announced in 2024.\n- **Distinction:** **Nagi and Nakti are two separate reservoirs and Ramsar sites in Jamui**. Nagi is particularly associated with bar-headed goose concentrations; Nakti with red-crested pochard concentrations.\n","species":["bar-headed goose","baer’s pochard","steppe eagle"]},"2546":{"name":"Nakti Bird Sanctuary","state":"Bihar","sections":[{"heading":"Location And Designation","facts":["**Location:** Jamui district · **Designation:** 11 October 2023 · **Registered Area:** 332.6 ha"]},{"heading":"Origin","facts":["**Nakti Dam reservoir**, a human-made freshwater wetland developed for irrigation, with a hilly, dry-deciduous catchment."]},{"heading":"Wildlife","facts":["Important wintering ground for **red-crested pochard [LC]**; **Wallago attu [VU]** is among the aquatic fauna recorded."]},{"heading":"Ecology","facts":["Open reservoir water, aquatic vegetation and margins support birds, fish and other wetland organisms; the surrounding catchment is part of the functional system."]},{"heading":"Uses","facts":["Irrigation, domestic water needs and birdwatching; operating the reservoir changes the habitat available in different seasons."]},{"heading":"Distinction","facts":["Its **11 October 2023 designation** is separate from the 2024 announcement. **Nakti and Nagi share Jamui district but are not one combined Ramsar site**."]}],"markdown":"# Nakti Bird Sanctuary\n\n**Location:** Jamui district · **Designation:** 11 October 2023 · **Registered Area:** 332.6 ha\n\n- **Origin:** **Nakti Dam reservoir**, a human-made freshwater wetland developed for irrigation, with a hilly, dry-deciduous catchment.\n- **Wildlife:** Important wintering ground for **red-crested pochard [LC]**; **Wallago attu [VU]** is among the aquatic fauna recorded.\n- **Ecology:** Open reservoir water, aquatic vegetation and margins support birds, fish and other wetland organisms; the surrounding catchment is part of the functional system.\n- **Uses:** Irrigation, domestic water needs and birdwatching; operating the reservoir changes the habitat available in different seasons.\n- **Distinction:** Its **11 October 2023 designation** is separate from the 2024 announcement. **Nakti and Nagi share Jamui district but are not one combined Ramsar site**.\n","species":["red-crested pochard","wallago attu"]},"2577":{"name":"Udaipur Jheel","state":"Bihar","sections":[{"heading":"Location And Designation","facts":["**Location:** West Champaran district · **Designation:** 13 May 2025 · **Registered Area:** 319 ha"]},{"heading":"Type","facts":["**Freshwater oxbow lake** adjoining the forested **Udaipur Wildlife Sanctuary** landscape; the lake surrounds a village."]},{"heading":"Ecology","facts":["Wetland–forest edges and aquatic vegetation support wintering birds, including **common pochard [VU]**, and diverse terrestrial and aquatic plants."]},{"heading":"Hydrology And Use","facts":["Floodplain storage, fisheries and adjacent agricultural activities connect wetland condition with local livelihoods."]},{"heading":"Pressures","facts":["Illegal fishing, intensive agriculture, fertilizers and pesticides can damage habitat and water quality."]},{"heading":"Distinction","facts":["This is **Udaipur Jheel in Bihar**, not the lakes of Udaipur city in Rajasthan. Reports of fruit “purifying” the water should not replace an evidence-based explanation of water treatment."]}],"markdown":"# Udaipur Jheel\n\n**Location:** West Champaran district · **Designation:** 13 May 2025 · **Registered Area:** 319 ha\n\n- **Type:** **Freshwater oxbow lake** adjoining the forested **Udaipur Wildlife Sanctuary** landscape; the lake surrounds a village.\n- **Ecology:** Wetland–forest edges and aquatic vegetation support wintering birds, including **common pochard [VU]**, and diverse terrestrial and aquatic plants.\n- **Hydrology And Use:** Floodplain storage, fisheries and adjacent agricultural activities connect wetland condition with local livelihoods.\n- **Pressures:** Illegal fishing, intensive agriculture, fertilizers and pesticides can damage habitat and water quality.\n- **Distinction:** This is **Udaipur Jheel in Bihar**, not the lakes of Udaipur city in Rajasthan. Reports of fruit “purifying” the water should not replace an evidence-based explanation of water treatment.\n","species":["common pochard"]},"2602":{"name":"Sukhna Wetland","state":"Chandigarh","sections":[{"heading":"Location And Designation","facts":["**Location:** Sukhna Lake, Outer Himalayan/Shivalik foothills · **Designation:** 16 March 2026 · **Registered Area:** 199.5 ha"]},{"heading":"Origin","facts":["**Peri-urban reservoir created in 1958**, at the edge of Chandigarh; the Ramsar site is **Sukhna Wetland**, not the entire adjoining catchment or wildlife sanctuary."]},{"heading":"Hydrology","facts":["Seasonal water-level changes create open water, littoral vegetation and terrestrial edges. Erosion in the foothill catchment brings sediment into the reservoir."]},{"heading":"Wildlife","facts":["Central Asian Flyway habitat with **common pochard [VU]**, **Pallas’s fish eagle [EN]** and **spotted pond turtle/black pond turtle [EN]**."]},{"heading":"Management","facts":["Soil-and-moisture conservation reduces catchment erosion; invasive-plant removal helps maintain suitable habitat. Sediment control must address upstream causes, not only dredging within the lake."]},{"heading":"Dates","facts":["Official designation **16 March 2026**; announcement with Sauj Jheel **15 October 2026**. One of the two additions bringing India’s total to **103**."]}],"markdown":"# Sukhna Wetland\n\n**Location:** Sukhna Lake, Outer Himalayan/Shivalik foothills · **Designation:** 16 March 2026 · **Registered Area:** 199.5 ha\n\n- **Origin:** **Peri-urban reservoir created in 1958**, at the edge of Chandigarh; the Ramsar site is **Sukhna Wetland**, not the entire adjoining catchment or wildlife sanctuary.\n- **Hydrology:** Seasonal water-level changes create open water, littoral vegetation and terrestrial edges. Erosion in the foothill catchment brings sediment into the reservoir.\n- **Wildlife:** Central Asian Flyway habitat with **common pochard [VU]**, **Pallas’s fish eagle [EN]** and **spotted pond turtle/black pond turtle [EN]**.\n- **Management:** Soil-and-moisture conservation reduces catchment erosion; invasive-plant removal helps maintain suitable habitat. Sediment control must address upstream causes, not only dredging within the lake.\n- **Dates:** Official designation **16 March 2026**; announcement with Sauj Jheel **15 October 2026**. One of the two additions bringing India’s total to **103**.\n","species":["common pochard","pallas’s fish eagle","spotted pond turtle"]},"2583":{"name":"Kopra Jalashay","state":"Chhattisgarh","sections":[{"heading":"Location And Designation","facts":["**Location:** Bilaspur district, Takhatpur block · **Designation:** 8 August 2025 · **Registered Area:** 210 ha"]},{"heading":"Origin","facts":["**Irrigation reservoir in the upper Mahanadi catchment**, surrounded mainly by farmland and villages."]},{"heading":"Habitats","facts":["Open water, shallow backwaters and nutrient-rich margins support fish and seasonal bird habitats."]},{"heading":"Wildlife","facts":["Migratory and resident birds include **greater spotted eagle [VU]** and **Egyptian vulture [EN]**; shallow-water food resources support the wider bird assemblage."]},{"heading":"Functions","facts":["Irrigation water, wetland connectivity and nature observation; bird use and fisheries depend on the surrounding catchment as well as the reservoir."]},{"heading":"Pressures And Contrast","facts":["Siltation, invasive organisms and intensive agricultural runoff threaten habitat. **Kopra—Chhattisgarh** is not **Kolleru—Andhra Pradesh** or **Karaivetti—Tamil Nadu**."]}],"markdown":"# Kopra Jalashay\n\n**Location:** Bilaspur district, Takhatpur block · **Designation:** 8 August 2025 · **Registered Area:** 210 ha\n\n- **Origin:** **Irrigation reservoir in the upper Mahanadi catchment**, surrounded mainly by farmland and villages.\n- **Habitats:** Open water, shallow backwaters and nutrient-rich margins support fish and seasonal bird habitats.\n- **Wildlife:** Migratory and resident birds include **greater spotted eagle [VU]** and **Egyptian vulture [EN]**; shallow-water food resources support the wider bird assemblage.\n- **Functions:** Irrigation water, wetland connectivity and nature observation; bird use and fisheries depend on the surrounding catchment as well as the reservoir.\n- **Pressures And Contrast:** Siltation, invasive organisms and intensive agricultural runoff threaten habitat. **Kopra—Chhattisgarh** is not **Kolleru—Andhra Pradesh** or **Karaivetti—Tamil Nadu**.\n","species":["greater spotted eagle","egyptian vulture"]},"2471":{"name":"Nanda Lake","state":"Goa","sections":[{"heading":"Location And Designation","facts":["**Location:** Quepem, South Goa · **Designation:** 8 June 2022 · **Registered Area:** 42 ha"]},{"heading":"Type","facts":["**Seasonal/intermittent freshwater marsh** beside a tributary of the **Zuari**; wetland water levels are controlled partly through a **sluice gate**."]},{"heading":"Hydrology","facts":["Closing the gate retains water and floods marsh habitat; water storage supports dry-season use and rice cultivation downstream."]},{"heading":"Wildlife","facts":["**Bronze-winged jacana [LC]** and **lesser whistling duck [LC]** illustrate floating-vegetation and shallow-water habitats used by resident waterbirds."]},{"heading":"Functions","facts":["Irrigation, fisheries, monsoon flood buffering and recreation; seasonal drying is part of the ecosystem rather than automatic evidence of wetland destruction."]},{"heading":"Pressures","facts":["Invasive organisms, solid waste, excessive fishing and unsustainable extraction threaten ecological character. Nanda is a **freshwater Ramsar site**, not a tidal marine wetland merely because Goa is coastal."]}],"markdown":"# Nanda Lake\n\n**Location:** Quepem, South Goa · **Designation:** 8 June 2022 · **Registered Area:** 42 ha\n\n- **Type:** **Seasonal/intermittent freshwater marsh** beside a tributary of the **Zuari**; wetland water levels are controlled partly through a **sluice gate**.\n- **Hydrology:** Closing the gate retains water and floods marsh habitat; water storage supports dry-season use and rice cultivation downstream.\n- **Wildlife:** **Bronze-winged jacana [LC]** and **lesser whistling duck [LC]** illustrate floating-vegetation and shallow-water habitats used by resident waterbirds.\n- **Functions:** Irrigation, fisheries, monsoon flood buffering and recreation; seasonal drying is part of the ecosystem rather than automatic evidence of wetland destruction.\n- **Pressures:** Invasive organisms, solid waste, excessive fishing and unsustainable extraction threaten ecological character. Nanda is a **freshwater Ramsar site**, not a tidal marine wetland merely because Goa is coastal.\n","species":["bronze-winged jacana","lesser whistling duck"]},"2588":{"name":"Chhari Dhand","state":"Gujarat","sections":[{"heading":"Location And Designation","facts":["**Location:** Kachchh district, between Banni grasslands and the Rann · **Designation:** 16 June 2025 · **Registered Area:** 22,700 ha"]},{"heading":"Type","facts":["**Seasonal saline wetland**, locally a **dhand**, flooded during the monsoon within an arid grassland–salt-flat landscape."]},{"heading":"Water Balance","facts":["Strong seasonal inundation and evaporation produce changing water extent and salinity; it is not a perennial freshwater reservoir."]},{"heading":"Wildlife","facts":["Important wintering habitat for **common crane [LC]**, **common pochard [VU]** and **sociable lapwing [CR]**."]},{"heading":"Landscape Connections","facts":["Open grasslands, saline flats and wet patches support different feeding and resting niches; protecting only the wet-season water surface misses dry-season habitat."]},{"heading":"Pressures","facts":["Invasive vegetation and altered inflow can change the wetland mosaic. **Chhari Dhand—Kachchh** differs from **Khijadia—Jamnagar’s coastal freshwater–saline complex**."]}],"markdown":"# Chhari Dhand\n\n**Location:** Kachchh district, between Banni grasslands and the Rann · **Designation:** 16 June 2025 · **Registered Area:** 22,700 ha\n\n- **Type:** **Seasonal saline wetland**, locally a **dhand**, flooded during the monsoon within an arid grassland–salt-flat landscape.\n- **Water Balance:** Strong seasonal inundation and evaporation produce changing water extent and salinity; it is not a perennial freshwater reservoir.\n- **Wildlife:** Important wintering habitat for **common crane [LC]**, **common pochard [VU]** and **sociable lapwing [CR]**.\n- **Landscape Connections:** Open grasslands, saline flats and wet patches support different feeding and resting niches; protecting only the wet-season water surface misses dry-season habitat.\n- **Pressures:** Invasive vegetation and altered inflow can change the wetland mosaic. **Chhari Dhand—Kachchh** differs from **Khijadia—Jamnagar’s coastal freshwater–saline complex**.\n","species":["common crane","common pochard","sociable lapwing"]},"2464":{"name":"Khijadia Wildlife Sanctuary","state":"Gujarat","sections":[{"heading":"Location And Designation","facts":["**Location:** Jamnagar district, Gulf of Kachchh coast · **Designation:** 13 April 2021 · **Registered Area:** 511.7 ha"]},{"heading":"Origin","facts":["A **bund constructed in 1920** to prevent saline intrusion created freshwater habitat close to tidal and saline coastal areas."]},{"heading":"Ecological Contrast","facts":["Adjacent freshwater and marine-influenced habitats support a broad set of feeding niches; “coastal” does not make the whole sanctuary uniformly saline."]},{"heading":"Wildlife","facts":["Associated with **Indian skimmer [EN]**, **Pallas’s fish eagle [EN]**, **common pochard [VU]**, **Dalmatian pelican [NT]** and **common crane [LC]**."]},{"heading":"Functions","facts":["Bird feeding and roosting, nursery habitats, nutrient cycling and erosion protection."]},{"heading":"Distinction","facts":["**Khijadia is a Wildlife Sanctuary near Jamnagar**; **Chhari Dhand is a seasonal saline wetland in Kachchh**. Both are Gujarat Ramsar sites, but their water sources and salinity regimes differ."]}],"markdown":"# Khijadia Wildlife Sanctuary\n\n**Location:** Jamnagar district, Gulf of Kachchh coast · **Designation:** 13 April 2021 · **Registered Area:** 511.7 ha\n\n- **Origin:** A **bund constructed in 1920** to prevent saline intrusion created freshwater habitat close to tidal and saline coastal areas.\n- **Ecological Contrast:** Adjacent freshwater and marine-influenced habitats support a broad set of feeding niches; “coastal” does not make the whole sanctuary uniformly saline.\n- **Wildlife:** Associated with **Indian skimmer [EN]**, **Pallas’s fish eagle [EN]**, **common pochard [VU]**, **Dalmatian pelican [NT]** and **common crane [LC]**.\n- **Functions:** Bird feeding and roosting, nursery habitats, nutrient cycling and erosion protection.\n- **Distinction:** **Khijadia is a Wildlife Sanctuary near Jamnagar**; **Chhari Dhand is a seasonal saline wetland in Kachchh**. Both are Gujarat Ramsar sites, but their water sources and salinity regimes differ.\n","species":["indian skimmer","pallas’s fish eagle","common pochard","dalmatian pelican","common crane"]},"2078":{"name":"Nalsarovar","state":"Gujarat","sections":[{"heading":"Location And Designation","facts":["**Location:** Ahmedabad–Surendranagar landscape · **Designation:** 24 September 2012 · **Registered Area:** 12,000 ha"]},{"heading":"Type","facts":["Broad, shallow **natural lake and marsh complex**; rainfall and seasonal water balance produce variation in depth and salinity."]},{"heading":"Setting","facts":["A wetland refuge in the semi-arid landscape adjoining the **Thar Desert biogeographic province**, with numerous shallow feeding areas and islands."]},{"heading":"Wildlife","facts":["Important Central Asian Flyway stopover; associated with **sociable lapwing [CR]**, **marbled duck [NT]** and **sarus crane [VU]**. Their seasonal use of the site need not be identical."]},{"heading":"Uses","facts":["Fisheries, grazing, tourism and irrigation depend on a functioning wetland and its water balance."]},{"heading":"Distinction","facts":["**Nalsarovar is natural**; **Thol and Wadhvana are reservoirs**. A seasonal increase in salinity does not make Nalsarovar a permanently hypersaline lake like a salt pan."]}],"markdown":"# Nalsarovar\n\n**Location:** Ahmedabad–Surendranagar landscape · **Designation:** 24 September 2012 · **Registered Area:** 12,000 ha\n\n- **Type:** Broad, shallow **natural lake and marsh complex**; rainfall and seasonal water balance produce variation in depth and salinity.\n- **Setting:** A wetland refuge in the semi-arid landscape adjoining the **Thar Desert biogeographic province**, with numerous shallow feeding areas and islands.\n- **Wildlife:** Important Central Asian Flyway stopover; associated with **sociable lapwing [CR]**, **marbled duck [NT]** and **sarus crane [VU]**. Their seasonal use of the site need not be identical.\n- **Uses:** Fisheries, grazing, tourism and irrigation depend on a functioning wetland and its water balance.\n- **Distinction:** **Nalsarovar is natural**; **Thol and Wadhvana are reservoirs**. A seasonal increase in salinity does not make Nalsarovar a permanently hypersaline lake like a salt pan.\n","species":["sociable lapwing","marbled duck","sarus crane"]},"2458":{"name":"Thol Lake Wildlife Sanctuary","state":"Gujarat","sections":[{"heading":"Location And Designation","facts":["**Location:** Near Ahmedabad, Mehsana district · **Designation:** 5 April 2021 · **Registered Area:** 699 ha"]},{"heading":"Origin","facts":["Shallow **irrigation reservoir built in 1912**, subsequently protected as **Thol Lake Wildlife Sanctuary**."]},{"heading":"Habitats","facts":["Open water, shallow feeding areas, aquatic vegetation and surrounding semi-arid land provide different seasonal resources."]},{"heading":"Wildlife","facts":["Important Central Asian Flyway site with **sarus crane [VU]**, **common pochard [VU]**, **sociable lapwing [CR]** and **white-rumped vulture [CR]** recorded."]},{"heading":"Services","facts":["Groundwater recharge, irrigation, drinking-water support and recreation coexist with bird conservation."]},{"heading":"Pressures And Contrast","facts":["Water allocation, disturbance and changes in depth affect habitat suitability. **Thol is artificial**, whereas **Nalsarovar is a natural wetland**; both are in Gujarat but differ in origin and water regime."]}],"markdown":"# Thol Lake Wildlife Sanctuary\n\n**Location:** Near Ahmedabad, Mehsana district · **Designation:** 5 April 2021 · **Registered Area:** 699 ha\n\n- **Origin:** Shallow **irrigation reservoir built in 1912**, subsequently protected as **Thol Lake Wildlife Sanctuary**.\n- **Habitats:** Open water, shallow feeding areas, aquatic vegetation and surrounding semi-arid land provide different seasonal resources.\n- **Wildlife:** Important Central Asian Flyway site with **sarus crane [VU]**, **common pochard [VU]**, **sociable lapwing [CR]** and **white-rumped vulture [CR]** recorded.\n- **Services:** Groundwater recharge, irrigation, drinking-water support and recreation coexist with bird conservation.\n- **Pressures And Contrast:** Water allocation, disturbance and changes in depth affect habitat suitability. **Thol is artificial**, whereas **Nalsarovar is a natural wetland**; both are in Gujarat but differ in origin and water regime.\n","species":["sarus crane","common pochard","sociable lapwing","white-rumped vulture"]},"2454":{"name":"Wadhvana Wetland","state":"Gujarat","sections":[{"heading":"Location And Designation","facts":["**Location:** Dabhoi, Vadodara district · **Designation:** 5 April 2021 · **Registered Area:** 630 ha"]},{"heading":"Origin","facts":["**Irrigation reservoir created in 1910** by the former Baroda State, within a semi-arid agricultural landscape."]},{"heading":"Wildlife","facts":["Important wintering habitat on the Central Asian Flyway, with **red-crested pochard [LC]**, **common pochard [VU]**, **Dalmatian pelican [NT]** and **Pallas’s fish eagle [EN]**."]},{"heading":"Resident Use","facts":["**Sarus crane [VU]** and **river tern [VU]** illustrate that a reservoir can also support resident wetland-dependent birds."]},{"heading":"Functions","facts":["Irrigation water, bird habitat, nature education and tourism; shoreline shallows and agricultural surroundings contribute to feeding opportunities."]},{"heading":"Distinction","facts":["**Wadhvana—Vadodara, artificial reservoir**; **Nalsarovar—natural shallow lake**; **Thol—1912 irrigation reservoir**. Water release timing affects the availability of shallow habitat."]}],"markdown":"# Wadhvana Wetland\n\n**Location:** Dabhoi, Vadodara district · **Designation:** 5 April 2021 · **Registered Area:** 630 ha\n\n- **Origin:** **Irrigation reservoir created in 1910** by the former Baroda State, within a semi-arid agricultural landscape.\n- **Wildlife:** Important wintering habitat on the Central Asian Flyway, with **red-crested pochard [LC]**, **common pochard [VU]**, **Dalmatian pelican [NT]** and **Pallas’s fish eagle [EN]**.\n- **Resident Use:** **Sarus crane [VU]** and **river tern [VU]** illustrate that a reservoir can also support resident wetland-dependent birds.\n- **Functions:** Irrigation water, bird habitat, nature education and tourism; shoreline shallows and agricultural surroundings contribute to feeding opportunities.\n- **Distinction:** **Wadhvana—Vadodara, artificial reservoir**; **Nalsarovar—natural shallow lake**; **Thol—1912 irrigation reservoir**. Water release timing affects the availability of shallow habitat.\n","species":["red-crested pochard","common pochard","dalmatian pelican","pallas’s fish eagle","sarus crane","river tern"]},"2459":{"name":"Bhindawas Wildlife Sanctuary","state":"Haryana","sections":[{"heading":"Location And Designation","facts":["**Location:** Jhajjar district · **Designation:** 25 May 2021 · **Registered Area:** 412 ha"]},{"heading":"Type","facts":["**Human-made freshwater wetland** and Wildlife Sanctuary; an important flood buffer and groundwater-recharge area in a cultivated landscape."]},{"heading":"Wildlife","facts":["Resident and migrant waterbirds include **greylag goose [LC]** and **Indian cormorant [LC]**, with **steppe eagle [EN]**, **Egyptian vulture [EN]** and **black-bellied tern [EN]** recorded."]},{"heading":"Ecology","facts":["Shallow water, marsh vegetation and terrestrial edges offer distinct feeding and roosting niches."]},{"heading":"Designations","facts":["Wildlife Sanctuary, Ramsar site and an eco-sensitive-zone framework around the protected area; these have separate legal meanings."]},{"heading":"Distinction","facts":["**Bhindawas is in Jhajjar**, despite older descriptions referring to the broader Rohtak administrative landscape. Compare it with **Sultanpur National Park in Gurugram**."]}],"markdown":"# Bhindawas Wildlife Sanctuary\n\n**Location:** Jhajjar district · **Designation:** 25 May 2021 · **Registered Area:** 412 ha\n\n- **Type:** **Human-made freshwater wetland** and Wildlife Sanctuary; an important flood buffer and groundwater-recharge area in a cultivated landscape.\n- **Wildlife:** Resident and migrant waterbirds include **greylag goose [LC]** and **Indian cormorant [LC]**, with **steppe eagle [EN]**, **Egyptian vulture [EN]** and **black-bellied tern [EN]** recorded.\n- **Ecology:** Shallow water, marsh vegetation and terrestrial edges offer distinct feeding and roosting niches.\n- **Designations:** Wildlife Sanctuary, Ramsar site and an eco-sensitive-zone framework around the protected area; these have separate legal meanings.\n- **Distinction:** **Bhindawas is in Jhajjar**, despite older descriptions referring to the broader Rohtak administrative landscape. Compare it with **Sultanpur National Park in Gurugram**.\n","species":["greylag goose","indian cormorant","steppe eagle","egyptian vulture","black-bellied tern"]},"2457":{"name":"Sultanpur National Park","state":"Haryana","sections":[{"heading":"Location And Designation","facts":["**Location:** Gurugram district · **Designation:** 25 May 2021 · **Registered Area:** 142.5 ha"]},{"heading":"Type","facts":["Shallow lake, grassland and woodland within **Sultanpur National Park**; receives canal/field inflow, rainfall and groundwater contributions."]},{"heading":"Water Regime","facts":["Seasonal water levels and locally saline groundwater influence vegetation and habitat; a freshwater wetland setting can still experience salinity stress."]},{"heading":"Wildlife","facts":["Major waterbird habitat, including **bar-headed goose [LC]**, **greylag goose [LC]**, **sociable lapwing [CR]** and recorded threatened raptors."]},{"heading":"Designations","facts":["**National Park** and Ramsar site; surrounding eco-sensitive-zone regulation is another legal layer and has its own boundary."]},{"heading":"Distinction","facts":["One of Haryana’s two Ramsar sites, alongside **Bhindawas Wildlife Sanctuary in Jhajjar**. National Park designation is not a prerequisite for Ramsar listing."]}],"markdown":"# Sultanpur National Park\n\n**Location:** Gurugram district · **Designation:** 25 May 2021 · **Registered Area:** 142.5 ha\n\n- **Type:** Shallow lake, grassland and woodland within **Sultanpur National Park**; receives canal/field inflow, rainfall and groundwater contributions.\n- **Water Regime:** Seasonal water levels and locally saline groundwater influence vegetation and habitat; a freshwater wetland setting can still experience salinity stress.\n- **Wildlife:** Major waterbird habitat, including **bar-headed goose [LC]**, **greylag goose [LC]**, **sociable lapwing [CR]** and recorded threatened raptors.\n- **Designations:** **National Park** and Ramsar site; surrounding eco-sensitive-zone regulation is another legal layer and has its own boundary.\n- **Distinction:** One of Haryana’s two Ramsar sites, alongside **Bhindawas Wildlife Sanctuary in Jhajjar**. National Park designation is not a prerequisite for Ramsar listing.\n","species":["bar-headed goose","greylag goose","sociable lapwing"]},"1569":{"name":"Chandertal Wetland","state":"Himachal Pradesh","sections":[{"heading":"Location And Designation","facts":["**Location:** Upper Chandra Valley, Lahaul–Spiti, near Kunzum Pass · **Designation:** 8 November 2005 · **Registered Area:** 49 ha"]},{"heading":"Type","facts":["Small, high-altitude **freshwater lake**, commonly called **Chandratal**, at over **4,300 m** in a cold-arid Himalayan landscape."]},{"heading":"Drainage","facts":["Associated with the **Chandra River** catchment; the Chandra joins the Bhaga to form the Chenab. It is not an isolated lowland oxbow lake."]},{"heading":"Ecology","facts":["The lake, surrounding grasslands and sparse vegetation form a short-summer habitat mosaic; the larger landscape supports **snow leopard [VU]**."]},{"heading":"Adaptation And Pressure","facts":["Low temperatures, intense radiation and a short growing season make vegetation slow to recover from trampling. Grazing, camping, trekking waste and sanitation pressure can damage the catchment."]},{"heading":"Distinction","facts":["Compare **Chandratal—Chandra/Chenab basin** with **Pong—Beas** and **Renuka—Giri/Yamuna drainage**; all three are Himachal Pradesh Ramsar sites."]}],"markdown":"# Chandertal Wetland\n\n**Location:** Upper Chandra Valley, Lahaul–Spiti, near Kunzum Pass · **Designation:** 8 November 2005 · **Registered Area:** 49 ha\n\n- **Type:** Small, high-altitude **freshwater lake**, commonly called **Chandratal**, at over **4,300 m** in a cold-arid Himalayan landscape.\n- **Drainage:** Associated with the **Chandra River** catchment; the Chandra joins the Bhaga to form the Chenab. It is not an isolated lowland oxbow lake.\n- **Ecology:** The lake, surrounding grasslands and sparse vegetation form a short-summer habitat mosaic; the larger landscape supports **snow leopard [VU]**.\n- **Adaptation And Pressure:** Low temperatures, intense radiation and a short growing season make vegetation slow to recover from trampling. Grazing, camping, trekking waste and sanitation pressure can damage the catchment.\n- **Distinction:** Compare **Chandratal—Chandra/Chenab basin** with **Pong—Beas** and **Renuka—Giri/Yamuna drainage**; all three are Himachal Pradesh Ramsar sites.\n","species":["snow leopard"]},"1211":{"name":"Pong Dam Lake","state":"Himachal Pradesh","sections":[{"heading":"Location And Designation","facts":["**Location:** Kangra district, Beas River · **Designation:** 19 August 2002 · **Registered Area:** 15,662 ha"]},{"heading":"Origin","facts":["Reservoir created by **Pong Dam on the Beas**, also known as **Maharana Pratap Sagar**; a human-made wetland in the outer Himalayan foothills."]},{"heading":"Hydrology","facts":["Monsoon storage and controlled release support irrigation, flood regulation and hydropower. Drawdown exposes shallow margins and feeding areas used by birds."]},{"heading":"Wildlife","facts":["Major wintering habitat on trans-Himalayan migratory routes; especially associated with **bar-headed goose [LC]**, alongside other waterfowl."]},{"heading":"Livelihoods","facts":["Reservoir fisheries and water supply link wetland management to surrounding and downstream communities."]},{"heading":"Distinction","facts":["**Pong—Beas**; **Bhakra’s Govind Sagar—Sutlej**; **Nangal Wildlife Sanctuary** is another Ramsar wetland associated with the Bhakra–Nangal project. Reservoir operating schedules affect ecological conditions."]}],"markdown":"# Pong Dam Lake\n\n**Location:** Kangra district, Beas River · **Designation:** 19 August 2002 · **Registered Area:** 15,662 ha\n\n- **Origin:** Reservoir created by **Pong Dam on the Beas**, also known as **Maharana Pratap Sagar**; a human-made wetland in the outer Himalayan foothills.\n- **Hydrology:** Monsoon storage and controlled release support irrigation, flood regulation and hydropower. Drawdown exposes shallow margins and feeding areas used by birds.\n- **Wildlife:** Major wintering habitat on trans-Himalayan migratory routes; especially associated with **bar-headed goose [LC]**, alongside other waterfowl.\n- **Livelihoods:** Reservoir fisheries and water supply link wetland management to surrounding and downstream communities.\n- **Distinction:** **Pong—Beas**; **Bhakra’s Govind Sagar—Sutlej**; **Nangal Wildlife Sanctuary** is another Ramsar wetland associated with the Bhakra–Nangal project. Reservoir operating schedules affect ecological conditions.\n","species":["bar-headed goose"]},"1571":{"name":"Renuka Wetland","state":"Himachal Pradesh","sections":[{"heading":"Location And Designation","facts":["**Location:** Sirmaur district · **Designation:** 8 November 2005 · **Registered Area:** 20 ha"]},{"heading":"Type","facts":["Small natural **freshwater, spring-influenced lake** in the lower Himalayas, with adjoining forest and protected wetland habitat."]},{"heading":"Drainage","facts":["Local streams and groundwater connections link it to the **Giri–Yamuna** drainage landscape; runoff from steep slopes affects sediment inputs."]},{"heading":"Culture","facts":["Named after **Renuka**, traditionally associated with Parashurama; pilgrimage and tourism are major human uses around the shore."]},{"heading":"Ecology And Pressures","facts":["Lake, littoral vegetation and terrestrial slopes support different communities. Slope erosion, sedimentation, nutrient loading and concentrated visitor pressure can shrink or alter the shallow margins."]},{"heading":"Area Distinction","facts":["Its registered **20 ha** makes it very small, but it is not the smallest of the 103-site inventory: **Vembannur Wetland Complex is 19.7 ha**."]}],"markdown":"# Renuka Wetland\n\n**Location:** Sirmaur district · **Designation:** 8 November 2005 · **Registered Area:** 20 ha\n\n- **Type:** Small natural **freshwater, spring-influenced lake** in the lower Himalayas, with adjoining forest and protected wetland habitat.\n- **Drainage:** Local streams and groundwater connections link it to the **Giri–Yamuna** drainage landscape; runoff from steep slopes affects sediment inputs.\n- **Culture:** Named after **Renuka**, traditionally associated with Parashurama; pilgrimage and tourism are major human uses around the shore.\n- **Ecology And Pressures:** Lake, littoral vegetation and terrestrial slopes support different communities. Slope erosion, sedimentation, nutrient loading and concentrated visitor pressure can shrink or alter the shallow margins.\n- **Area Distinction:** Its registered **20 ha** makes it very small, but it is not the smallest of the 103-site inventory: **Vembannur Wetland Complex is 19.7 ha**.\n","species":[]},"1570":{"name":"Hokera Wetland","state":"Jammu And Kashmir","sections":[{"heading":"Location And Designation","facts":["**Location:** Near Srinagar, Kashmir Valley · **Designation:** 8 November 2005 · **Registered Area:** 1,375 ha"]},{"heading":"Name And Type","facts":["**Hokera**, also widely called **Hokersar**, is a shallow freshwater marsh in the Jhelum basin with extensive reed and aquatic-plant habitats."]},{"heading":"Water And Birds","facts":["Fed by catchment inflows and seasonal hydrology; open water, reeds and shallow margins provide feeding, resting and wintering habitat for Central Asian migrants."]},{"heading":"Wildlife","facts":["Associated with wintering ducks including **ferruginous duck [NT]**. The older name “white-eyed pochard” refers to this duck and must not be confused with **Baer’s pochard [CR]**."]},{"heading":"Functions","facts":["Fish nursery, local aquatic-resource supply, storage of floodwater and maintenance of wetland connectivity."]},{"heading":"Pressures","facts":["Siltation, reduced inflow, urban expansion, waste disposal and excessive nutrient input can replace open water with dense vegetation and terrestrialized ground. Reedbed habitat also survives at other Kashmir wetlands."]}],"markdown":"# Hokera Wetland\n\n**Location:** Near Srinagar, Kashmir Valley · **Designation:** 8 November 2005 · **Registered Area:** 1,375 ha\n\n- **Name And Type:** **Hokera**, also widely called **Hokersar**, is a shallow freshwater marsh in the Jhelum basin with extensive reed and aquatic-plant habitats.\n- **Water And Birds:** Fed by catchment inflows and seasonal hydrology; open water, reeds and shallow margins provide feeding, resting and wintering habitat for Central Asian migrants.\n- **Wildlife:** Associated with wintering ducks including **ferruginous duck [NT]**. The older name “white-eyed pochard” refers to this duck and must not be confused with **Baer’s pochard [CR]**.\n- **Functions:** Fish nursery, local aquatic-resource supply, storage of floodwater and maintenance of wetland connectivity.\n- **Pressures:** Siltation, reduced inflow, urban expansion, waste disposal and excessive nutrient input can replace open water with dense vegetation and terrestrialized ground. Reedbed habitat also survives at other Kashmir wetlands.\n","species":["ferruginous duck","baer’s pochard"]},"2496":{"name":"Hygam Wetland Conservation Reserve","state":"Jammu And Kashmir","sections":[{"heading":"Location And Designation","facts":["**Location:** Baramulla district, lower Kashmir Valley · **Designation:** 8 June 2022 · **Registered Area:** 801.8 ha"]},{"heading":"Type And Connections","facts":["Freshwater wetland connected with the **Wular–Jhelum system**, with marsh vegetation and seasonal open water."]},{"heading":"Wildlife","facts":["Important wintering and resting habitat on the **Central Asian Flyway**; supports **common pochard [VU]** and **Eurasian otter [NT]**."]},{"heading":"Hydrological Role","facts":["Contributes to flood buffering, groundwater exchange and regulation of water moving through the connected lake–river landscape."]},{"heading":"Local Use","facts":["Fisheries, reed/wood resources and water supply support nearby communities."]},{"heading":"Pressures And Contrast","facts":["Siltation, nutrient accumulation and willow plantations can reduce open water. Counts of tens of thousands refer to **individual birds**, not tens of thousands of bird species."]}],"markdown":"# Hygam Wetland Conservation Reserve\n\n**Location:** Baramulla district, lower Kashmir Valley · **Designation:** 8 June 2022 · **Registered Area:** 801.8 ha\n\n- **Type And Connections:** Freshwater wetland connected with the **Wular–Jhelum system**, with marsh vegetation and seasonal open water.\n- **Wildlife:** Important wintering and resting habitat on the **Central Asian Flyway**; supports **common pochard [VU]** and **Eurasian otter [NT]**.\n- **Hydrological Role:** Contributes to flood buffering, groundwater exchange and regulation of water moving through the connected lake–river landscape.\n- **Local Use:** Fisheries, reed/wood resources and water supply support nearby communities.\n- **Pressures And Contrast:** Siltation, nutrient accumulation and willow plantations can reduce open water. Counts of tens of thousands refer to **individual birds**, not tens of thousands of bird species.\n","species":["common pochard","eurasian otter"]},"2488":{"name":"Shallbugh Wetland Conservation Reserve","state":"Jammu And Kashmir","sections":[{"heading":"Location And Designation","facts":["**Location:** Srinagar–Ganderbal districts · **Designation:** 8 June 2022 · **Registered Area:** 1,675 ha"]},{"heading":"Type And Setting","facts":["Shallow freshwater marsh in the **Sindh River delta west of Anchar Lake**, within the larger **Jhelum drainage basin**."]},{"heading":"Water Sources","facts":["Rainfall, Himalayan snowmelt and inflows from the Sindh–Anchar system; the local **Sindh** is not the main **Indus/Sindhu** River."]},{"heading":"Habitats And Wildlife","facts":["Reedbeds, open water and floating vegetation support migratory birds, including **Pallas’s fish eagle [EN]**, **steppe eagle [EN]** and recorded threatened waterbirds."]},{"heading":"Functions","facts":["Fisheries, flood regulation, water-quality functions and carbon storage; its proximity to Hokera helps maintain a regional wetland network."]},{"heading":"Pressures","facts":["Heavy siltation is a major concern. Migratory birds recorded here are not thereby endemic to Shallbugh; **occurrence, migration and endemism are different claims**."]}],"markdown":"# Shallbugh Wetland Conservation Reserve\n\n**Location:** Srinagar–Ganderbal districts · **Designation:** 8 June 2022 · **Registered Area:** 1,675 ha\n\n- **Type And Setting:** Shallow freshwater marsh in the **Sindh River delta west of Anchar Lake**, within the larger **Jhelum drainage basin**.\n- **Water Sources:** Rainfall, Himalayan snowmelt and inflows from the Sindh–Anchar system; the local **Sindh** is not the main **Indus/Sindhu** River.\n- **Habitats And Wildlife:** Reedbeds, open water and floating vegetation support migratory birds, including **Pallas’s fish eagle [EN]**, **steppe eagle [EN]** and recorded threatened waterbirds.\n- **Functions:** Fisheries, flood regulation, water-quality functions and carbon storage; its proximity to Hokera helps maintain a regional wetland network.\n- **Pressures:** Heavy siltation is a major concern. Migratory birds recorded here are not thereby endemic to Shallbugh; **occurrence, migration and endemism are different claims**.\n","species":["pallas’s fish eagle","steppe eagle"]},"1573":{"name":"Surinsar-Mansar Lakes","state":"Jammu And Kashmir","sections":[{"heading":"Location And Designation","facts":["**Location:** Jammu’s lower Shivalik landscape · **Designation:** 8 November 2005 · **Registered Area:** 350 ha"]},{"heading":"Components","facts":["**Surinsar and Mansar**, two freshwater lakes forming one Ramsar site within a shared protected landscape; one site does not mean one continuous lake."]},{"heading":"Hydrology","facts":["Primarily rainfall, runoff and groundwater contributions. Surinsar has no permanent discharge; the two lakes should not be treated as an active stretch of the Jhelum."]},{"heading":"Ecology","facts":["Nutrient-rich littoral and open-water habitats support freshwater fish, turtles and waterbirds."]},{"heading":"Culture","facts":["Sacred associations and temples influence use; religious restrictions can discourage fishing even where fish are abundant."]},{"heading":"Pressures And Contrast","facts":["Visitor pressure, sewage, bathing and agricultural runoff increase nutrient loads. Distinguish these **Jammu-region lakes** from the Kashmir Valley’s Wular, Hokera, Hygam and Shallbugh."]}],"markdown":"# Surinsar-Mansar Lakes\n\n**Location:** Jammu’s lower Shivalik landscape · **Designation:** 8 November 2005 · **Registered Area:** 350 ha\n\n- **Components:** **Surinsar and Mansar**, two freshwater lakes forming one Ramsar site within a shared protected landscape; one site does not mean one continuous lake.\n- **Hydrology:** Primarily rainfall, runoff and groundwater contributions. Surinsar has no permanent discharge; the two lakes should not be treated as an active stretch of the Jhelum.\n- **Ecology:** Nutrient-rich littoral and open-water habitats support freshwater fish, turtles and waterbirds.\n- **Culture:** Sacred associations and temples influence use; religious restrictions can discourage fishing even where fish are abundant.\n- **Pressures And Contrast:** Visitor pressure, sewage, bathing and agricultural runoff increase nutrient loads. Distinguish these **Jammu-region lakes** from the Kashmir Valley’s Wular, Hokera, Hygam and Shallbugh.\n","species":[]},"461":{"name":"Wular Lake","state":"Jammu And Kashmir","sections":[{"heading":"Location And Designation","facts":["**Location:** Bandipora district, Kashmir Valley · **Designation:** 23 March 1990 · **Registered Area:** 18,900 ha"]},{"heading":"Type And Setting","facts":["Large natural **freshwater lake** and marsh complex in the Kashmir Valley, associated with a tectonic depression. The **Jhelum flows into and out of it**."]},{"heading":"Hydrology","facts":["Stores floodwater and moderates downstream discharge. Open-water area changes with season and water level; the Ramsar boundary is not an all-season measurement of open water."]},{"heading":"Ecology And Livelihoods","facts":["Shallow margins, reeds and floating vegetation support fish, wintering waterbirds and local harvesting of aquatic products. The lake forms part of the connected Jhelum wetland landscape."]},{"heading":"Pressures","facts":["Catchment erosion and siltation, settlement and agricultural encroachment, nutrient loading and willow expansion reduce water-storage space and alter habitats."]},{"heading":"Distinction","facts":["Wular is freshwater; **Sambhar** is inland saline; **Chilika** is a brackish coastal lagoon. Unqualified size rankings depend on season, area definition and the comparison used."]}],"markdown":"# Wular Lake\n\n**Location:** Bandipora district, Kashmir Valley · **Designation:** 23 March 1990 · **Registered Area:** 18,900 ha\n\n- **Type And Setting:** Large natural **freshwater lake** and marsh complex in the Kashmir Valley, associated with a tectonic depression. The **Jhelum flows into and out of it**.\n- **Hydrology:** Stores floodwater and moderates downstream discharge. Open-water area changes with season and water level; the Ramsar boundary is not an all-season measurement of open water.\n- **Ecology And Livelihoods:** Shallow margins, reeds and floating vegetation support fish, wintering waterbirds and local harvesting of aquatic products. The lake forms part of the connected Jhelum wetland landscape.\n- **Pressures:** Catchment erosion and siltation, settlement and agricultural encroachment, nutrient loading and willow expansion reduce water-storage space and alter habitats.\n- **Distinction:** Wular is freshwater; **Sambhar** is inland saline; **Chilika** is a brackish coastal lagoon. Unqualified size rankings depend on season, area definition and the comparison used.\n","species":[]},"2559":{"name":"Udhwa Lake Bird Sanctuary","state":"Jharkhand","sections":[{"heading":"Location And Designation","facts":["**Location:** Sahibganj district, Rajmahal Hills landscape · **Designation:** 8 January 2024 · **Registered Area:** 935.5 ha"]},{"heading":"Components","facts":["**Pataura and Barhel lakes**, two connected freshwater wetlands forming one Ramsar site."]},{"heading":"Drainage","facts":["A channel connects the wetland complex to the **Ganga**; seasonal river exchange influences water and ecological connectivity."]},{"heading":"Wildlife","facts":["Important for **Pallas’s fish eagle [EN]**, **common pochard [VU]** and **lesser adjutant [NT]**, among other resident and wintering birds."]},{"heading":"Uses","facts":["Bank cultivation, subsistence fisheries and grazing occur in the wetland landscape; seasonal water and vegetation support these livelihoods."]},{"heading":"Distinction","facts":["**Udhwa—Jharkhand, Sahibganj**, not Bihar. Its Ramsar designation is dated **8 January 2024**, although announcement of the addition came in 2025."]}],"markdown":"# Udhwa Lake Bird Sanctuary\n\n**Location:** Sahibganj district, Rajmahal Hills landscape · **Designation:** 8 January 2024 · **Registered Area:** 935.5 ha\n\n- **Components:** **Pataura and Barhel lakes**, two connected freshwater wetlands forming one Ramsar site.\n- **Drainage:** A channel connects the wetland complex to the **Ganga**; seasonal river exchange influences water and ecological connectivity.\n- **Wildlife:** Important for **Pallas’s fish eagle [EN]**, **common pochard [VU]** and **lesser adjutant [NT]**, among other resident and wintering birds.\n- **Uses:** Bank cultivation, subsistence fisheries and grazing occur in the wetland landscape; seasonal water and vegetation support these livelihoods.\n- **Distinction:** **Udhwa—Jharkhand, Sahibganj**, not Bihar. Its Ramsar designation is dated **8 January 2024**, although announcement of the addition came in 2025.\n","species":["pallas’s fish eagle","common pochard","lesser adjutant"]},"2534":{"name":"Aghanashini Estuary","state":"Karnataka","sections":[{"heading":"Location And Designation","facts":["**Location:** Kumta taluk, Uttara Kannada district · **Designation:** 14 February 2023 · **Registered Area:** 4,801 ha"]},{"heading":"Type","facts":["**Aghanashini River estuary opening into the Arabian Sea**, with brackish water, tidal flats, rocky shores, mangroves and adjoining agricultural wetlands."]},{"heading":"Wildlife","facts":["Fish and shellfish nursery habitat; waterbirds include **black-headed ibis [LC]**, **lesser adjutant [NT]** and **river tern [VU]**."]},{"heading":"Adaptation","facts":["Many estuarine fish tolerate a wide salinity range; other species use the estuary only during migration, spawning or juvenile growth."]},{"heading":"Agriculture And Livelihoods","facts":["**Kagga**, a locally adapted salt-tolerant rice, is cultivated in the estuarine landscape. Fisheries, bivalves, salt-related use and agriculture connect people with the wetland."]},{"heading":"Distinction","facts":["An **estuary is a river–sea mixing zone**, not a lagoon necessarily enclosed behind a coastal barrier. Maintaining freshwater inflow and tidal exchange is essential."]}],"markdown":"# Aghanashini Estuary\n\n**Location:** Kumta taluk, Uttara Kannada district · **Designation:** 14 February 2023 · **Registered Area:** 4,801 ha\n\n- **Type:** **Aghanashini River estuary opening into the Arabian Sea**, with brackish water, tidal flats, rocky shores, mangroves and adjoining agricultural wetlands.\n- **Wildlife:** Fish and shellfish nursery habitat; waterbirds include **black-headed ibis [LC]**, **lesser adjutant [NT]** and **river tern [VU]**.\n- **Adaptation:** Many estuarine fish tolerate a wide salinity range; other species use the estuary only during migration, spawning or juvenile growth.\n- **Agriculture And Livelihoods:** **Kagga**, a locally adapted salt-tolerant rice, is cultivated in the estuarine landscape. Fisheries, bivalves, salt-related use and agriculture connect people with the wetland.\n- **Distinction:** An **estuary is a river–sea mixing zone**, not a lagoon necessarily enclosed behind a coastal barrier. Maintaining freshwater inflow and tidal exchange is essential.\n","species":["black-headed ibis","lesser adjutant","river tern"]},"2535":{"name":"Ankasamudra Bird Conservation Reserve","state":"Karnataka","sections":[{"heading":"Location And Designation","facts":["**Location:** Vijayanagara district, Tungabhadra landscape · **Designation:** 10 March 2023 · **Registered Area:** 98.8 ha"]},{"heading":"Origin","facts":["Human-made **irrigation tank** retaining monsoon runoff in a drought-prone landscape; protected as a **Bird Conservation Reserve**."]},{"heading":"Nesting Habitat","facts":["Large stands of **babul [LC]** in the water provide roosting and breeding substrate for **Indian cormorant [LC]**, **painted stork [LC]** and other colonial birds."]},{"heading":"Wildlife","facts":["Particularly important for **glossy ibis [LC]**; fish and shallow-water productivity sustain waterbird feeding."]},{"heading":"Functions","facts":["Water storage, irrigation, breeding habitat and nature observation; the ecological role of trees depends on retaining water and suitable nesting conditions around them."]},{"heading":"Pressures","facts":["Invasive plants and introduced predatory fish can displace native communities. Removing all vegetation indiscriminately would also destroy valued nesting habitat."]}],"markdown":"# Ankasamudra Bird Conservation Reserve\n\n**Location:** Vijayanagara district, Tungabhadra landscape · **Designation:** 10 March 2023 · **Registered Area:** 98.8 ha\n\n- **Origin:** Human-made **irrigation tank** retaining monsoon runoff in a drought-prone landscape; protected as a **Bird Conservation Reserve**.\n- **Nesting Habitat:** Large stands of **babul [LC]** in the water provide roosting and breeding substrate for **Indian cormorant [LC]**, **painted stork [LC]** and other colonial birds.\n- **Wildlife:** Particularly important for **glossy ibis [LC]**; fish and shallow-water productivity sustain waterbird feeding.\n- **Functions:** Water storage, irrigation, breeding habitat and nature observation; the ecological role of trees depends on retaining water and suitable nesting conditions around them.\n- **Pressures:** Invasive plants and introduced predatory fish can displace native communities. Removing all vegetation indiscriminately would also destroy valued nesting habitat.\n","species":["babul","indian cormorant","painted stork","glossy ibis"]},"2536":{"name":"Magadi Kere Conservation Reserve","state":"Karnataka","sections":[{"heading":"Location And Designation","facts":["**Location:** Gadag district, Shirahatti taluk · **Designation:** 14 February 2023 · **Registered Area:** 54.4 ha"]},{"heading":"Origin","facts":["**Rainwater-storage irrigation tank** that has become an important alkaline-water bird refuge; protected as a Conservation Reserve."]},{"heading":"Wildlife","facts":["Especially notable as a southern Indian wintering ground for **bar-headed goose [LC]**; also supports **common pochard [VU]**, **northern shoveler [LC]** and **garganey [LC]**."]},{"heading":"Water Quality","facts":["Increasing alkalinity affected its suitability for irrigation, illustrating that ecological habitat value and agricultural suitability are not identical."]},{"heading":"Human Use","facts":["Fishing and cattle grazing occur in the surrounding landscape; waterbird conservation depends on compatible use and seasonal water retention."]},{"heading":"Distinction","facts":["**Magadi Kere Ramsar site is in Gadag**, not simply any lake near Magadi town in the Bengaluru region. The place-name must be attached to the correct district."]}],"markdown":"# Magadi Kere Conservation Reserve\n\n**Location:** Gadag district, Shirahatti taluk · **Designation:** 14 February 2023 · **Registered Area:** 54.4 ha\n\n- **Origin:** **Rainwater-storage irrigation tank** that has become an important alkaline-water bird refuge; protected as a Conservation Reserve.\n- **Wildlife:** Especially notable as a southern Indian wintering ground for **bar-headed goose [LC]**; also supports **common pochard [VU]**, **northern shoveler [LC]** and **garganey [LC]**.\n- **Water Quality:** Increasing alkalinity affected its suitability for irrigation, illustrating that ecological habitat value and agricultural suitability are not identical.\n- **Human Use:** Fishing and cattle grazing occur in the surrounding landscape; waterbird conservation depends on compatible use and seasonal water retention.\n- **Distinction:** **Magadi Kere Ramsar site is in Gadag**, not simply any lake near Magadi town in the Bengaluru region. The place-name must be attached to the correct district.\n","species":["bar-headed goose","common pochard","northern shoveler","garganey"]},"2473":{"name":"Ranganathittu Bird Sanctuary","state":"Karnataka","sections":[{"heading":"Location And Designation","facts":["**Location:** Mandya district, Kaveri/Cauvery River · **Designation:** 15 February 2022 · **Registered Area:** 517.7 ha"]},{"heading":"Type","facts":["**Riverine wetland with islands and rocky islets** on the Kaveri, downstream of the Krishnarajasagar landscape; protected as a Bird Sanctuary."]},{"heading":"Wildlife","facts":["Colonial nesting habitat for **painted stork [LC]**, **spot-billed pelican [NT]** and **black-headed ibis [LC]**. Aquatic fauna include **mugger crocodile [VU]**, **smooth-coated otter [VU]** and **hump-backed mahseer [CR]**."]},{"heading":"Mechanism","facts":["Islands provide relatively secure nesting/roosting space; fish and shallow feeding grounds connect river productivity with bird breeding."]},{"heading":"Functions","facts":["Nature tourism, research and local livelihoods alongside aquatic biodiversity."]},{"heading":"Distinction","facts":["**Ranganathittu—Kaveri, Mandya**; **Aghanashini—Arabian Sea estuary**; **Magadi Kere—Gadag irrigation tank**. These Karnataka sites represent three different wetland types."]}],"markdown":"# Ranganathittu Bird Sanctuary\n\n**Location:** Mandya district, Kaveri/Cauvery River · **Designation:** 15 February 2022 · **Registered Area:** 517.7 ha\n\n- **Type:** **Riverine wetland with islands and rocky islets** on the Kaveri, downstream of the Krishnarajasagar landscape; protected as a Bird Sanctuary.\n- **Wildlife:** Colonial nesting habitat for **painted stork [LC]**, **spot-billed pelican [NT]** and **black-headed ibis [LC]**. Aquatic fauna include **mugger crocodile [VU]**, **smooth-coated otter [VU]** and **hump-backed mahseer [CR]**.\n- **Mechanism:** Islands provide relatively secure nesting/roosting space; fish and shallow feeding grounds connect river productivity with bird breeding.\n- **Functions:** Nature tourism, research and local livelihoods alongside aquatic biodiversity.\n- **Distinction:** **Ranganathittu—Kaveri, Mandya**; **Aghanashini—Arabian Sea estuary**; **Magadi Kere—Gadag irrigation tank**. These Karnataka sites represent three different wetland types.\n","species":["painted stork","spot-billed pelican","black-headed ibis","mugger crocodile","smooth-coated otter","hump-backed mahseer"]},"1204":{"name":"Ashtamudi Wetland","state":"Kerala","sections":[{"heading":"Location And Designation","facts":["**Location:** Kollam estuarine system · **Designation:** 19 August 2002 · **Registered Area:** 6,140 ha"]},{"heading":"Type And Shape","facts":["**Brackish estuarine backwater** with branching arms; the name refers to its eight-armed form. It is distinct from the nearby freshwater Sasthamkotta Lake."]},{"heading":"Water Connections","facts":["Receives the **Kallada River** and exchanges water with the **Arabian Sea through the Neendakara inlet**. The freshwater–tidal balance controls salinity and aquatic communities."]},{"heading":"Ecology","facts":["Mangroves, shallow margins and estuarine waters provide fish and shellfish habitats. Clam fisheries are a characteristic livelihood; an estuarine nursery links inland inflow with coastal fisheries."]},{"heading":"Pressures","facts":["Urban and industrial effluent, boat-related oil pollution, shore conversion and reduced tidal flushing threaten the wetland."]},{"heading":"Area Distinction","facts":["The current RSIS boundary is **6,140 ha**; older narrative material can contain a larger figure. The registered boundary area is distinct from older narrative figures."]}],"markdown":"# Ashtamudi Wetland\n\n**Location:** Kollam estuarine system · **Designation:** 19 August 2002 · **Registered Area:** 6,140 ha\n\n- **Type And Shape:** **Brackish estuarine backwater** with branching arms; the name refers to its eight-armed form. It is distinct from the nearby freshwater Sasthamkotta Lake.\n- **Water Connections:** Receives the **Kallada River** and exchanges water with the **Arabian Sea through the Neendakara inlet**. The freshwater–tidal balance controls salinity and aquatic communities.\n- **Ecology:** Mangroves, shallow margins and estuarine waters provide fish and shellfish habitats. Clam fisheries are a characteristic livelihood; an estuarine nursery links inland inflow with coastal fisheries.\n- **Pressures:** Urban and industrial effluent, boat-related oil pollution, shore conversion and reduced tidal flushing threaten the wetland.\n- **Area Distinction:** The current RSIS boundary is **6,140 ha**; older narrative material can contain a larger figure. The registered boundary area is distinct from older narrative figures.\n","species":[]},"1212":{"name":"Sasthamkotta Lake","state":"Kerala","sections":[{"heading":"Location And Designation","facts":["**Location:** Kollam district · **Designation:** 19 August 2002 · **Registered Area:** 373 ha"]},{"heading":"Type","facts":["Natural **freshwater lake**, unlike brackish Ashtamudi. It is a major drinking-water source in the Kollam region."]},{"heading":"Water Regime","facts":["Rainfall, catchment runoff and groundwater/spring connections sustain the lake; its freshwater quality depends on protection of the surrounding basin."]},{"heading":"Ecology","facts":["Supports freshwater fish and aquatic food webs. Its importance does not require it to be a coastal estuary or a large bird colony."]},{"heading":"Pressures","facts":["Catchment erosion, sediment inflow, excessive extraction and pollution can affect both water availability and the drinking-water function."]},{"heading":"Distinction","facts":["Water clarity and ecological processes do not imply an absence of dissolved minerals or aquatic plants, nor guarantee bacteriological safety."]}],"markdown":"# Sasthamkotta Lake\n\n**Location:** Kollam district · **Designation:** 19 August 2002 · **Registered Area:** 373 ha\n\n- **Type:** Natural **freshwater lake**, unlike brackish Ashtamudi. It is a major drinking-water source in the Kollam region.\n- **Water Regime:** Rainfall, catchment runoff and groundwater/spring connections sustain the lake; its freshwater quality depends on protection of the surrounding basin.\n- **Ecology:** Supports freshwater fish and aquatic food webs. Its importance does not require it to be a coastal estuary or a large bird colony.\n- **Pressures:** Catchment erosion, sediment inflow, excessive extraction and pollution can affect both water availability and the drinking-water function.\n- **Distinction:** Water clarity and ecological processes do not imply an absence of dissolved minerals or aquatic plants, nor guarantee bacteriological safety.\n","species":[]},"1214":{"name":"Vembanad-Kol Wetland","state":"Kerala","sections":[{"heading":"Location And Designation","facts":["**Location:** Alappuzha–Kottayam–Ernakulam and Kol wetland landscape · **Designation:** 19 August 2002 · **Registered Area:** 151,250 ha"]},{"heading":"Type","facts":["Large **estuarine–backwater and floodplain wetland complex**, including freshwater and brackish sectors; the Ramsar extent is broader than a single open-water lake measurement."]},{"heading":"Rivers And Sea","facts":["Receives the **Pamba, Achankovil, Manimala, Meenachil and Muvattupuzha** systems, with tidal exchange through coastal outlets including Kochi."]},{"heading":"Human Intervention","facts":["**Thanneermukkom barrage** restricts saline intrusion into southern agricultural areas. Benefits to cultivation must be weighed against restricted flushing, altered fish migration and salinity change."]},{"heading":"Agriculture","facts":["Connected with **Kuttanad’s below-sea-level paddy cultivation** and the seasonally inundated Kol lands; fisheries, clams and navigation are other major uses."]},{"heading":"Pressures And Contrast","facts":["Reclamation, sewage, nutrient loading and altered hydrology threaten the complex. **Vembanad-Kol is not Vembannur**, the small Tamil Nadu irrigation wetland."]}],"markdown":"# Vembanad-Kol Wetland\n\n**Location:** Alappuzha–Kottayam–Ernakulam and Kol wetland landscape · **Designation:** 19 August 2002 · **Registered Area:** 151,250 ha\n\n- **Type:** Large **estuarine–backwater and floodplain wetland complex**, including freshwater and brackish sectors; the Ramsar extent is broader than a single open-water lake measurement.\n- **Rivers And Sea:** Receives the **Pamba, Achankovil, Manimala, Meenachil and Muvattupuzha** systems, with tidal exchange through coastal outlets including Kochi.\n- **Human Intervention:** **Thanneermukkom barrage** restricts saline intrusion into southern agricultural areas. Benefits to cultivation must be weighed against restricted flushing, altered fish migration and salinity change.\n- **Agriculture:** Connected with **Kuttanad’s below-sea-level paddy cultivation** and the seasonally inundated Kol lands; fisheries, clams and navigation are other major uses.\n- **Pressures And Contrast:** Reclamation, sewage, nutrient loading and altered hydrology threaten the complex. **Vembanad-Kol is not Vembannur**, the small Tamil Nadu irrigation wetland.\n","species":[]},"2443":{"name":"Tso Kar Wetland Complex","state":"Ladakh","sections":[{"heading":"Location And Designation","facts":["**Location:** Changthang plateau, Leh district · **Designation:** 17 November 2020 · **Registered Area:** 9,577 ha"]},{"heading":"Components","facts":["**Tso Kar**, a saline to hypersaline lake, and **Startsapuk Tso**, a freshwater lake, form one high-altitude wetland complex."]},{"heading":"Hydrology","facts":["Snow/glacial meltwater and streams sustain the cold-arid basin; evaporation leaves the white salt deposits reflected in the name “Tso Kar”."]},{"heading":"Wildlife","facts":["Important Indian breeding landscape for **black-necked crane [NT]** and a stopover on the Central Asian Flyway; the wider landscape supports **snow leopard [VU]** and **saker falcon [EN]**."]},{"heading":"Habitat Contrast","facts":["The juxtaposition of freshwater and saline water creates ecological diversity within a sparsely vegetated plateau."]},{"heading":"Pressures And Distinction","facts":["Water balance, disturbance, grazing and tourist access require care. **Tso Kar and Tsomoriri are separate Ramsar sites**; Startsapuk Tso is a component of Tso Kar’s designation, not an additional site."]}],"markdown":"# Tso Kar Wetland Complex\n\n**Location:** Changthang plateau, Leh district · **Designation:** 17 November 2020 · **Registered Area:** 9,577 ha\n\n- **Components:** **Tso Kar**, a saline to hypersaline lake, and **Startsapuk Tso**, a freshwater lake, form one high-altitude wetland complex.\n- **Hydrology:** Snow/glacial meltwater and streams sustain the cold-arid basin; evaporation leaves the white salt deposits reflected in the name “Tso Kar”.\n- **Wildlife:** Important Indian breeding landscape for **black-necked crane [NT]** and a stopover on the Central Asian Flyway; the wider landscape supports **snow leopard [VU]** and **saker falcon [EN]**.\n- **Habitat Contrast:** The juxtaposition of freshwater and saline water creates ecological diversity within a sparsely vegetated plateau.\n- **Pressures And Distinction:** Water balance, disturbance, grazing and tourist access require care. **Tso Kar and Tsomoriri are separate Ramsar sites**; Startsapuk Tso is a component of Tso Kar’s designation, not an additional site.\n","species":["black-necked crane","snow leopard","saker falcon"]},"1213":{"name":"Tsomoriri","state":"Ladakh","sections":[{"heading":"Location And Designation","facts":["**Location:** Changthang, near Korzok · **Designation:** 19 August 2002 · **Registered Area:** 12,000 ha"]},{"heading":"Type","facts":["High-altitude, **closed-basin lake** with freshwater-to-brackish conditions and salt-influenced margins; no outlet means evaporation can increase salinity."]},{"heading":"Setting","facts":["Cold-arid plateau at roughly **4,500 m**; snowmelt, streams and wet meadows create productive habitat within a sparse landscape."]},{"heading":"Wildlife","facts":["Breeding and feeding habitat for **black-necked crane [NT]** and **bar-headed goose [LC]**. These are summer breeding associations, not simply the wintering pattern of lowland Indian wetlands."]},{"heading":"Culture And Pressure","facts":["Korzok monastery, pastoral use, tourism, vehicle access and waste management connect ecological protection with local livelihoods and sacred values."]},{"heading":"Distinction","facts":["Now in the **Union Territory of Ladakh**, not Jammu and Kashmir UT. Black-necked cranes also breed at other Indian sites; Tsomoriri is not their sole breeding locality outside China."]}],"markdown":"# Tsomoriri\n\n**Location:** Changthang, near Korzok · **Designation:** 19 August 2002 · **Registered Area:** 12,000 ha\n\n- **Type:** High-altitude, **closed-basin lake** with freshwater-to-brackish conditions and salt-influenced margins; no outlet means evaporation can increase salinity.\n- **Setting:** Cold-arid plateau at roughly **4,500 m**; snowmelt, streams and wet meadows create productive habitat within a sparse landscape.\n- **Wildlife:** Breeding and feeding habitat for **black-necked crane [NT]** and **bar-headed goose [LC]**. These are summer breeding associations, not simply the wintering pattern of lowland Indian wetlands.\n- **Culture And Pressure:** Korzok monastery, pastoral use, tourism, vehicle access and waste management connect ecological protection with local livelihoods and sacred values.\n- **Distinction:** Now in the **Union Territory of Ladakh**, not Jammu and Kashmir UT. Black-necked cranes also breed at other Indian sites; Tsomoriri is not their sole breeding locality outside China.\n","species":["black-necked crane","bar-headed goose"]},"1206":{"name":"Bhoj Wetland","state":"Madhya Pradesh","sections":[{"heading":"Location And Designation","facts":["**Location:** Bhopal · **Designation:** 19 August 2002 · **Registered Area:** 3,201 ha"]},{"heading":"Components","facts":["**Upper Lake/Bhojtal** and **Lower Lake**, two human-made waterbodies with different origins and urban catchment conditions."]},{"heading":"Origin And Water","facts":["Upper Lake was formed by damming the **Kolans River** in the eleventh century; Lower Lake is much younger and receives water from the connected urban drainage system."]},{"heading":"Ecology","facts":["Shallow margins and aquatic plants support plankton, fish, reptiles and resident and migratory waterbirds. The wetland also supplies urban water and recreation."]},{"heading":"Mechanism","facts":["Nutrient enrichment increases algal and plant growth; excessive decomposition then consumes dissolved oxygen. Urban sewage is therefore not merely a visual-pollution issue."]},{"heading":"Pressures And Contrast","facts":["Sewage, runoff, sediment and shoreline encroachment affect the two-lake system. **Bhoj is in Bhopal**; **Sirpur and Yashwant Sagar are associated with Indore**."]}],"markdown":"# Bhoj Wetland\n\n**Location:** Bhopal · **Designation:** 19 August 2002 · **Registered Area:** 3,201 ha\n\n- **Components:** **Upper Lake/Bhojtal** and **Lower Lake**, two human-made waterbodies with different origins and urban catchment conditions.\n- **Origin And Water:** Upper Lake was formed by damming the **Kolans River** in the eleventh century; Lower Lake is much younger and receives water from the connected urban drainage system.\n- **Ecology:** Shallow margins and aquatic plants support plankton, fish, reptiles and resident and migratory waterbirds. The wetland also supplies urban water and recreation.\n- **Mechanism:** Nutrient enrichment increases algal and plant growth; excessive decomposition then consumes dissolved oxygen. Urban sewage is therefore not merely a visual-pollution issue.\n- **Pressures And Contrast:** Sewage, runoff, sediment and shoreline encroachment affect the two-lake system. **Bhoj is in Bhopal**; **Sirpur and Yashwant Sagar are associated with Indore**.\n","species":[]},"2483":{"name":"Sakhya Sagar","state":"Madhya Pradesh","sections":[{"heading":"Location And Designation","facts":["**Location:** Shivpuri, within Madhav National Park · **Designation:** 7 January 2022 · **Registered Area:** 248 ha"]},{"heading":"Type","facts":["Shallow, human-made **freshwater reservoir** with alkaline, nutrient-rich water and a mosaic of permanent water, marsh and seasonally dry margins."]},{"heading":"Protected Landscape","facts":["Located in **Madhav National Park**; a Ramsar designation does not create a separate tiger reserve or change the reservoir into a natural lake."]},{"heading":"Wildlife","facts":["Particularly associated with **mugger crocodile [VU]** and resident and migratory waterbirds; permanent water provides dry-season refuge."]},{"heading":"Functions","facts":["Water supply for wildlife, groundwater recharge, nutrient cycling, microclimate regulation and tourism."]},{"heading":"Distinction","facts":["**Sakhya Sagar—Shivpuri**; **Bhoj—Bhopal**; **Sirpur/Yashwant Sagar—Indore**. Seasonal drying in some sectors can expose productive feeding areas while other sectors retain water."]}],"markdown":"# Sakhya Sagar\n\n**Location:** Shivpuri, within Madhav National Park · **Designation:** 7 January 2022 · **Registered Area:** 248 ha\n\n- **Type:** Shallow, human-made **freshwater reservoir** with alkaline, nutrient-rich water and a mosaic of permanent water, marsh and seasonally dry margins.\n- **Protected Landscape:** Located in **Madhav National Park**; a Ramsar designation does not create a separate tiger reserve or change the reservoir into a natural lake.\n- **Wildlife:** Particularly associated with **mugger crocodile [VU]** and resident and migratory waterbirds; permanent water provides dry-season refuge.\n- **Functions:** Water supply for wildlife, groundwater recharge, nutrient cycling, microclimate regulation and tourism.\n- **Distinction:** **Sakhya Sagar—Shivpuri**; **Bhoj—Bhopal**; **Sirpur/Yashwant Sagar—Indore**. Seasonal drying in some sectors can expose productive feeding areas while other sectors retain water.\n","species":["mugger crocodile"]},"2478":{"name":"Sirpur Wetland","state":"Madhya Pradesh","sections":[{"heading":"Location And Designation","facts":["**Location:** Indore · **Designation:** 7 January 2022 · **Registered Area:** 161 ha"]},{"heading":"Origin","facts":["Human-made lake that has developed **near-natural wetland characteristics** over time; shallow, alkaline and nutrient-rich, with strong monsoon influence."]},{"heading":"Wildlife","facts":["Wintering and resident waterbirds include **common pochard [VU]**, **Egyptian vulture [EN]** and **river tern [VU]**."]},{"heading":"Mechanism","facts":["Shallow water and aquatic vegetation provide habitat and support nutrient processing; floodwater storage helps moderate local inundation."]},{"heading":"Functions","facts":["Urban biodiversity refuge, fisheries, medicinal-plant resources, education, recreation and microclimate regulation."]},{"heading":"Distinction","facts":["“**Pakshi Vihar**” is a common local description; That local phrase alone does not establish a separately notified Wildlife Sanctuary. **Sirpur and Yashwant Sagar are both associated with Indore**, but have different origins and basins."]}],"markdown":"# Sirpur Wetland\n\n**Location:** Indore · **Designation:** 7 January 2022 · **Registered Area:** 161 ha\n\n- **Origin:** Human-made lake that has developed **near-natural wetland characteristics** over time; shallow, alkaline and nutrient-rich, with strong monsoon influence.\n- **Wildlife:** Wintering and resident waterbirds include **common pochard [VU]**, **Egyptian vulture [EN]** and **river tern [VU]**.\n- **Mechanism:** Shallow water and aquatic vegetation provide habitat and support nutrient processing; floodwater storage helps moderate local inundation.\n- **Functions:** Urban biodiversity refuge, fisheries, medicinal-plant resources, education, recreation and microclimate regulation.\n- **Distinction:** “**Pakshi Vihar**” is a common local description; That local phrase alone does not establish a separately notified Wildlife Sanctuary. **Sirpur and Yashwant Sagar are both associated with Indore**, but have different origins and basins.\n","species":["common pochard","egyptian vulture","river tern"]},"2547":{"name":"Tawa Reservoir","state":"Madhya Pradesh","sections":[{"heading":"Location And Designation","facts":["**Location:** Narmadapuram district, Satpura landscape · **Designation:** 8 January 2024 · **Registered Area:** 20,050 ha"]},{"heading":"Origin And River","facts":["Large reservoir created by **Tawa Dam**; the **Tawa is a tributary of the Narmada**. The reservoir also receives the **Denwa** drainage."]},{"heading":"Protected Landscape","facts":["Associated with **Satpura Tiger Reserve**, with aquatic, shoreline and forest habitats; the reservoir area is not the same as the entire reserve."]},{"heading":"Wildlife","facts":["Supports freshwater fish including **tor mahseer [DD]** and **Wallago attu [VU]**, while the adjoining forests provide habitat for **Indian giant squirrel [LC]**."]},{"heading":"Functions","facts":["Irrigation, fisheries, fish spawning and recreation; shore drawdown and river connectivity affect fish recruitment."]},{"heading":"Distinction","facts":["**Data Deficient does not mean unthreatened**. Tawa is a **Narmada-basin reservoir**; it is not the Narmada main-stem reservoir created by Sardar Sarovar."]}],"markdown":"# Tawa Reservoir\n\n**Location:** Narmadapuram district, Satpura landscape · **Designation:** 8 January 2024 · **Registered Area:** 20,050 ha\n\n- **Origin And River:** Large reservoir created by **Tawa Dam**; the **Tawa is a tributary of the Narmada**. The reservoir also receives the **Denwa** drainage.\n- **Protected Landscape:** Associated with **Satpura Tiger Reserve**, with aquatic, shoreline and forest habitats; the reservoir area is not the same as the entire reserve.\n- **Wildlife:** Supports freshwater fish including **tor mahseer [DD]** and **Wallago attu [VU]**, while the adjoining forests provide habitat for **Indian giant squirrel [LC]**.\n- **Functions:** Irrigation, fisheries, fish spawning and recreation; shore drawdown and river connectivity affect fish recruitment.\n- **Distinction:** **Data Deficient does not mean unthreatened**. Tawa is a **Narmada-basin reservoir**; it is not the Narmada main-stem reservoir created by Sardar Sarovar.\n","species":["tor mahseer","wallago attu","indian giant squirrel"]},"2495":{"name":"Yashwant Sagar","state":"Madhya Pradesh","sections":[{"heading":"Location And Designation","facts":["**Location:** Indore district, Gambhir basin · **Designation:** 7 January 2022 · **Registered Area:** 822.9 ha"]},{"heading":"Origin","facts":["Freshwater reservoir built in the **1930s** for irrigation and drinking-water supply; subsequently used for fisheries and aquaculture."]},{"heading":"Wildlife","facts":["Important for **sarus crane [VU]** and other resident and migratory waterbirds; water recession exposes feeding and shallow-water habitats."]},{"heading":"Hydrology","facts":["The **Gambhir basin** association distinguishes it from Bhopal’s Kolans-fed Upper Lake. Reservoir inflow and operation influence seasonal habitat."]},{"heading":"Functions","facts":["Water supply, fisheries, maintenance of local hydrology, tourism and research."]},{"heading":"Distinction","facts":["**Yashwant Sagar and Sirpur—Indore**; **Bhoj—Bhopal**; **Sakhya Sagar—Shivpuri**. Historical bird counts should not be treated as permanent annual totals."]}],"markdown":"# Yashwant Sagar\n\n**Location:** Indore district, Gambhir basin · **Designation:** 7 January 2022 · **Registered Area:** 822.9 ha\n\n- **Origin:** Freshwater reservoir built in the **1930s** for irrigation and drinking-water supply; subsequently used for fisheries and aquaculture.\n- **Wildlife:** Important for **sarus crane [VU]** and other resident and migratory waterbirds; water recession exposes feeding and shallow-water habitats.\n- **Hydrology:** The **Gambhir basin** association distinguishes it from Bhopal’s Kolans-fed Upper Lake. Reservoir inflow and operation influence seasonal habitat.\n- **Functions:** Water supply, fisheries, maintenance of local hydrology, tourism and research.\n- **Distinction:** **Yashwant Sagar and Sirpur—Indore**; **Bhoj—Bhopal**; **Sakhya Sagar—Shivpuri**. Historical bird counts should not be treated as permanent annual totals.\n","species":["sarus crane"]},"2441":{"name":"Lonar Lake","state":"Maharashtra","sections":[{"heading":"Location And Designation","facts":["**Location:** Buldhana district, Deccan Plateau · **Designation:** 22 July 2020 · **Registered Area:** 427 ha"]},{"heading":"Origin","facts":["Almost circular **meteorite-impact crater in basalt**, containing an **endorheic saline and alkaline lake**; not a volcanic crater."]},{"heading":"Mechanism","facts":["No surface outlet means evaporation concentrates salts and alkalinity. Freshwater springs on the margins create a chemical contrast with the central lake."]},{"heading":"Ecology","facts":["Salt- and alkali-tolerant microorganisms thrive in the lake; forested slopes and freshwater edges support a different set of organisms."]},{"heading":"Wildlife","facts":["The wider site records **common pochard [VU]** and other birds; organisms using the margins need not tolerate the central lake’s chemistry."]},{"heading":"Pressures And Contrast","facts":["Sewage, runoff and visitor pressure threaten the system. **Salinity** concerns dissolved salts; **alkalinity** concerns acid-neutralizing capacity and is related to, but not identical with, high pH."]}],"markdown":"# Lonar Lake\n\n**Location:** Buldhana district, Deccan Plateau · **Designation:** 22 July 2020 · **Registered Area:** 427 ha\n\n- **Origin:** Almost circular **meteorite-impact crater in basalt**, containing an **endorheic saline and alkaline lake**; not a volcanic crater.\n- **Mechanism:** No surface outlet means evaporation concentrates salts and alkalinity. Freshwater springs on the margins create a chemical contrast with the central lake.\n- **Ecology:** Salt- and alkali-tolerant microorganisms thrive in the lake; forested slopes and freshwater edges support a different set of organisms.\n- **Wildlife:** The wider site records **common pochard [VU]** and other birds; organisms using the margins need not tolerate the central lake’s chemistry.\n- **Pressures And Contrast:** Sewage, runoff and visitor pressure threaten the system. **Salinity** concerns dissolved salts; **alkalinity** concerns acid-neutralizing capacity and is related to, but not identical with, high pH.\n","species":["common pochard"]},"2410":{"name":"Nandur Madhameshwar","state":"Maharashtra","sections":[{"heading":"Location And Designation","facts":["**Location:** Nashik district, Godavari–Kadwa confluence · **Designation:** 21 June 2019 · **Registered Area:** 1,437 ha"]},{"heading":"Origin","facts":["Wetland formed around a **weir at the confluence of the Godavari and Kadwa**; includes open water, marshes and riparian forest on the Deccan Plateau."]},{"heading":"Landscape","facts":["Lies in the **rain shadow of the Western Ghats**; stored water and heterogeneous habitats provide a refuge within a seasonally dry setting."]},{"heading":"Wildlife","facts":["Associated with **Deolali minnow [CR]**, **Indian vulture [CR]** and **white-rumped vulture [CR]**; different taxa indicate both aquatic and surrounding terrestrial habitat value."]},{"heading":"Function","facts":["Water storage, irrigation and flood buffering coexist with wildlife conservation; maintaining a range of depths benefits more species than uniformly deep water."]},{"heading":"Pressures","facts":["Water abstraction, urban inputs and invasive aquatic plants threaten ecological character. Maharashtra’s other contrasting Ramsar systems are **Lonar’s impact crater** and **tidal Thane Creek**."]}],"markdown":"# Nandur Madhameshwar\n\n**Location:** Nashik district, Godavari–Kadwa confluence · **Designation:** 21 June 2019 · **Registered Area:** 1,437 ha\n\n- **Origin:** Wetland formed around a **weir at the confluence of the Godavari and Kadwa**; includes open water, marshes and riparian forest on the Deccan Plateau.\n- **Landscape:** Lies in the **rain shadow of the Western Ghats**; stored water and heterogeneous habitats provide a refuge within a seasonally dry setting.\n- **Wildlife:** Associated with **Deolali minnow [CR]**, **Indian vulture [CR]** and **white-rumped vulture [CR]**; different taxa indicate both aquatic and surrounding terrestrial habitat value.\n- **Function:** Water storage, irrigation and flood buffering coexist with wildlife conservation; maintaining a range of depths benefits more species than uniformly deep water.\n- **Pressures:** Water abstraction, urban inputs and invasive aquatic plants threaten ecological character. Maharashtra’s other contrasting Ramsar systems are **Lonar’s impact crater** and **tidal Thane Creek**.\n","species":["deolali minnow","indian vulture","white-rumped vulture"]},"2490":{"name":"Thane Creek","state":"Maharashtra","sections":[{"heading":"Location And Designation","facts":["**Location:** Mumbai–Thane–Navi Mumbai estuarine landscape · **Designation:** 13 April 2022 · **Registered Area:** 6,521.1 ha"]},{"heading":"Type","facts":["**Brackish tidal creek** connected with the Arabian Sea and receiving freshwater inflows; includes mangroves, intertidal mudflats and shallow water."]},{"heading":"Wildlife","facts":["Especially associated with feeding congregations of **lesser flamingo [NT]** and **greater flamingo [LC]**; mudflat invertebrates and microorganisms support their food web."]},{"heading":"Protected Habitat","facts":["Includes the **Thane Creek Flamingo Sanctuary** landscape, but the Ramsar boundary is broader than a single viewing location."]},{"heading":"Functions","facts":["Fish nurseries, coastal flood buffering, sediment retention and urban biodiversity; intertidal feeding habitat is exposed and submerged with the tides."]},{"heading":"Pressures And Distinction","facts":["Reclamation, infrastructure, sewage, industrial pollution and disturbance affect mangroves and mudflats. **Thane Creek is tidal**, unlike **Lonar’s closed crater** and **Nandur Madhameshwar’s river-weir wetland**."]}],"markdown":"# Thane Creek\n\n**Location:** Mumbai–Thane–Navi Mumbai estuarine landscape · **Designation:** 13 April 2022 · **Registered Area:** 6,521.1 ha\n\n- **Type:** **Brackish tidal creek** connected with the Arabian Sea and receiving freshwater inflows; includes mangroves, intertidal mudflats and shallow water.\n- **Wildlife:** Especially associated with feeding congregations of **lesser flamingo [NT]** and **greater flamingo [LC]**; mudflat invertebrates and microorganisms support their food web.\n- **Protected Habitat:** Includes the **Thane Creek Flamingo Sanctuary** landscape, but the Ramsar boundary is broader than a single viewing location.\n- **Functions:** Fish nurseries, coastal flood buffering, sediment retention and urban biodiversity; intertidal feeding habitat is exposed and submerged with the tides.\n- **Pressures And Distinction:** Reclamation, infrastructure, sewage, industrial pollution and disturbance affect mangroves and mudflats. **Thane Creek is tidal**, unlike **Lonar’s closed crater** and **Nandur Madhameshwar’s river-weir wetland**.\n","species":["lesser flamingo","greater flamingo"]},"463":{"name":"Loktak Lake","state":"Manipur","sections":[{"heading":"Location And Designation","facts":["**Location:** Bishnupur district and adjoining Loktak basin · **Designation:** 23 March 1990 · **Registered Area:** 26,600 ha"]},{"heading":"Type","facts":["Large **freshwater lake** with **phumdis**—floating heterogeneous masses of vegetation, organic matter and soil, not ordinary rooted islands."]},{"heading":"Protected Habitat","facts":["**Keibul Lamjao National Park**, in the southern lake system, protects floating meadows used by **Sangai**, the Manipur brow-antlered deer; the species-level Eld’s deer assessment is **EN**."]},{"heading":"Mechanism","facts":["Under the natural seasonal regime, phumdis could settle during low water and obtain nutrients from the lake bed. Persistently high regulated water levels can disrupt this cycle and weaken floating-meadow habitat."]},{"heading":"Human Intervention","facts":["The **Ithai Barrage**, associated with the Loktak multipurpose project, altered water levels and fish connectivity. Lake use includes fisheries, irrigation, domestic water and hydropower."]},{"heading":"Conservation","facts":["Catchment degradation, sediment, sewage and invasive vegetation compound hydrological change. Entered the **Montreux Record in 1993** and remains listed; Keibul Lamjao’s UNESCO tentative-list entry is not World Heritage inscription."]}],"markdown":"# Loktak Lake\n\n**Location:** Bishnupur district and adjoining Loktak basin · **Designation:** 23 March 1990 · **Registered Area:** 26,600 ha\n\n- **Type:** Large **freshwater lake** with **phumdis**—floating heterogeneous masses of vegetation, organic matter and soil, not ordinary rooted islands.\n- **Protected Habitat:** **Keibul Lamjao National Park**, in the southern lake system, protects floating meadows used by **Sangai**, the Manipur brow-antlered deer; the species-level Eld’s deer assessment is **EN**.\n- **Mechanism:** Under the natural seasonal regime, phumdis could settle during low water and obtain nutrients from the lake bed. Persistently high regulated water levels can disrupt this cycle and weaken floating-meadow habitat.\n- **Human Intervention:** The **Ithai Barrage**, associated with the Loktak multipurpose project, altered water levels and fish connectivity. Lake use includes fisheries, irrigation, domestic water and hydropower.\n- **Conservation:** Catchment degradation, sediment, sewage and invasive vegetation compound hydrological change. Entered the **Montreux Record in 1993** and remains listed; Keibul Lamjao’s UNESCO tentative-list entry is not World Heritage inscription.\n","species":["eld’s deer/sangai"]},"2484":{"name":"Pala Wetland","state":"Mizoram","sections":[{"heading":"Location And Designation","facts":["**Location:** Siaha district, Mara region · **Designation:** 31 August 2021 · **Registered Area:** 1,850 ha"]},{"heading":"Name And Type","facts":["**Pala/Palak Dil**, a relatively deep **natural freshwater lake** with a forested catchment; the Ramsar boundary includes more than the open-water surface."]},{"heading":"Ecology","facts":["Lake, low marshes and surrounding forest support different animal communities. Forested slopes regulate runoff and sediment reaching the lake."]},{"heading":"Wildlife","facts":["The landscape supports **western hoolock gibbon [EN]** and **Phayre’s leaf monkey [EN]**; both are arboreal primates, but the gibbon is a tailless ape and the leaf monkey is a tailed colobine monkey."]},{"heading":"Community","facts":["Sacred and culturally important to the **Mara**; supports fishing, water supply and agriculture in nearby villages."]},{"heading":"Pressures","facts":["Road building, logging, hunting and catchment disturbance threaten the lake–forest system. It is not a floating-phumdi lake like Loktak."]}],"markdown":"# Pala Wetland\n\n**Location:** Siaha district, Mara region · **Designation:** 31 August 2021 · **Registered Area:** 1,850 ha\n\n- **Name And Type:** **Pala/Palak Dil**, a relatively deep **natural freshwater lake** with a forested catchment; the Ramsar boundary includes more than the open-water surface.\n- **Ecology:** Lake, low marshes and surrounding forest support different animal communities. Forested slopes regulate runoff and sediment reaching the lake.\n- **Wildlife:** The landscape supports **western hoolock gibbon [EN]** and **Phayre’s leaf monkey [EN]**; both are arboreal primates, but the gibbon is a tailless ape and the leaf monkey is a tailed colobine monkey.\n- **Community:** Sacred and culturally important to the **Mara**; supports fishing, water supply and agriculture in nearby villages.\n- **Pressures:** Road building, logging, hunting and catchment disturbance threaten the lake–forest system. It is not a floating-phumdi lake like Loktak.\n","species":["western hoolock gibbon","phayre’s leaf monkey"]},"2487":{"name":"Ansupa Lake","state":"Odisha","sections":[{"heading":"Location And Designation","facts":["**Location:** Cuttack district, near Subarnapur · **Designation:** 12 October 2021 · **Registered Area:** 231 ha"]},{"heading":"Type","facts":["**Freshwater oxbow lake of the Mahanadi**, with abundant aquatic vegetation and shallow waterbird habitat."]},{"heading":"Hydrological Issue","facts":["Its connecting channel with the Mahanadi has become impaired; lost river exchange can increase drought vulnerability, sediment accumulation and weed growth."]},{"heading":"Wildlife","facts":["Supports **Indian skimmer [EN]**, **black-bellied tern [EN]**, **river tern [VU]**, **magur [EN]** and **Wallago attu [VU]**."]},{"heading":"Functions","facts":["Fish habitat, fisheries, local water supply and agriculture; floodplain connectivity supports ecological processes beyond the permanent water area."]},{"heading":"Distinction","facts":["**Ansupa—Mahanadi oxbow**; **Satkosia—Mahanadi gorge**; **Hirakud—Mahanadi reservoir**. These represent three different landform and hydrological categories."]}],"markdown":"# Ansupa Lake\n\n**Location:** Cuttack district, near Subarnapur · **Designation:** 12 October 2021 · **Registered Area:** 231 ha\n\n- **Type:** **Freshwater oxbow lake of the Mahanadi**, with abundant aquatic vegetation and shallow waterbird habitat.\n- **Hydrological Issue:** Its connecting channel with the Mahanadi has become impaired; lost river exchange can increase drought vulnerability, sediment accumulation and weed growth.\n- **Wildlife:** Supports **Indian skimmer [EN]**, **black-bellied tern [EN]**, **river tern [VU]**, **magur [EN]** and **Wallago attu [VU]**.\n- **Functions:** Fish habitat, fisheries, local water supply and agriculture; floodplain connectivity supports ecological processes beyond the permanent water area.\n- **Distinction:** **Ansupa—Mahanadi oxbow**; **Satkosia—Mahanadi gorge**; **Hirakud—Mahanadi reservoir**. These represent three different landform and hydrological categories.\n","species":["indian skimmer","black-bellied tern","river tern","magur","wallago attu"]},"1205":{"name":"Bhitarkanika Mangroves","state":"Odisha","sections":[{"heading":"Location And Designation","facts":["**Location:** Kendrapara coast, Brahmani–Baitarani delta · **Designation:** 19 August 2002 · **Registered Area:** 65,000 ha"]},{"heading":"Type","facts":["Tidal **mangrove–estuarine complex** with creeks, mudflats and brackish-water nurseries; linked to the **Brahmani–Baitarani–Dhamra** coastal system."]},{"heading":"Wildlife","facts":["Particularly associated with **saltwater crocodile [LC]**. Nearby **Gahirmatha** is famous for mass nesting, or **arribada**, of **olive ridley turtle [VU]**."]},{"heading":"Geographical Distinction","facts":["Bhitarkanika’s mangrove/protected-area landscape and Gahirmatha’s marine turtle habitat are closely connected, but their legal boundaries and designations are not identical."]},{"heading":"Mechanisms","facts":["Mangrove roots trap sediment, create juvenile-fish refuges and reduce wave energy; protection weakens when tidal exchange or freshwater supply is disrupted."]},{"heading":"Pressures","facts":["Encroachment, unsustainable extraction, upstream hydrological alteration and pollution affect the system. **Ramsar site, National Park and Wildlife Sanctuary** describe different designations and spatial extents."]}],"markdown":"# Bhitarkanika Mangroves\n\n**Location:** Kendrapara coast, Brahmani–Baitarani delta · **Designation:** 19 August 2002 · **Registered Area:** 65,000 ha\n\n- **Type:** Tidal **mangrove–estuarine complex** with creeks, mudflats and brackish-water nurseries; linked to the **Brahmani–Baitarani–Dhamra** coastal system.\n- **Wildlife:** Particularly associated with **saltwater crocodile [LC]**. Nearby **Gahirmatha** is famous for mass nesting, or **arribada**, of **olive ridley turtle [VU]**.\n- **Geographical Distinction:** Bhitarkanika’s mangrove/protected-area landscape and Gahirmatha’s marine turtle habitat are closely connected, but their legal boundaries and designations are not identical.\n- **Mechanisms:** Mangrove roots trap sediment, create juvenile-fish refuges and reduce wave energy; protection weakens when tidal exchange or freshwater supply is disrupted.\n- **Pressures:** Encroachment, unsustainable extraction, upstream hydrological alteration and pollution affect the system. **Ramsar site, National Park and Wildlife Sanctuary** describe different designations and spatial extents.\n","species":["saltwater crocodile","olive ridley turtle"]},"229":{"name":"Chilika Lake","state":"Odisha","sections":[{"heading":"Location And Designation","facts":["**Location:** Puri–Khordha–Ganjam coastal belt · **Designation:** 1 October 1981 · **Registered Area:** 116,500 ha"]},{"heading":"Type And Setting","facts":["Large **brackish coastal lagoon** separated from the Bay of Bengal by a sandy barrier; seawater enters through an inlet. It is not an inland freshwater lake."]},{"heading":"Water Connections","facts":["Freshwater from the Mahanadi delta distributary system and smaller catchments mixes with tidal seawater. Rainfall, river discharge and the condition of the sea mouth produce seasonal and spatial salinity gradients."]},{"heading":"Habitats And Wildlife","facts":["Open water, mudflats, islands and submerged vegetation support fisheries and migratory waterbirds. **Nalabana Bird Sanctuary** lies within the lagoon; **Irrawaddy dolphin [EN]** is its distinctive aquatic mammal."]},{"heading":"Restoration","facts":["Siltation and restriction of the sea mouth reduced seawater exchange, altered salinity and affected fisheries. Restoring exchange improved the lagoon’s ecological functioning; protection must address both the catchment and inlet."]},{"heading":"Designations","facts":["One of India’s first two Ramsar sites, designated **1 October 1981**. On the **Montreux Record, 1993–2002**; removal from that record did not remove Ramsar designation."]}],"markdown":"# Chilika Lake\n\n**Location:** Puri–Khordha–Ganjam coastal belt · **Designation:** 1 October 1981 · **Registered Area:** 116,500 ha\n\n- **Type And Setting:** Large **brackish coastal lagoon** separated from the Bay of Bengal by a sandy barrier; seawater enters through an inlet. It is not an inland freshwater lake.\n- **Water Connections:** Freshwater from the Mahanadi delta distributary system and smaller catchments mixes with tidal seawater. Rainfall, river discharge and the condition of the sea mouth produce seasonal and spatial salinity gradients.\n- **Habitats And Wildlife:** Open water, mudflats, islands and submerged vegetation support fisheries and migratory waterbirds. **Nalabana Bird Sanctuary** lies within the lagoon; **Irrawaddy dolphin [EN]** is its distinctive aquatic mammal.\n- **Restoration:** Siltation and restriction of the sea mouth reduced seawater exchange, altered salinity and affected fisheries. Restoring exchange improved the lagoon’s ecological functioning; protection must address both the catchment and inlet.\n- **Designations:** One of India’s first two Ramsar sites, designated **1 October 1981**. On the **Montreux Record, 1993–2002**; removal from that record did not remove Ramsar designation.\n","species":["irrawaddy dolphin"]},"2494":{"name":"Hirakud Reservoir","state":"Odisha","sections":[{"heading":"Location And Designation","facts":["**Location:** Mahanadi River near Sambalpur, extending towards Bargarh and Jharsuguda · **Designation:** 12 October 2021 · **Registered Area:** 65,400 ha"]},{"heading":"Origin","facts":["Large **human-made reservoir behind Hirakud Dam on the Mahanadi**; distinct from a natural floodplain lake."]},{"heading":"Hydrology","facts":["Stores monsoon water and regulates downstream flow towards the **Mahanadi delta**, supporting irrigation, flood moderation and hydropower."]},{"heading":"Ecology","facts":["Open water, islands and seasonally exposed margins support fish production and resident and migratory birds."]},{"heading":"Tradeoff","facts":["Storage benefits and aquatic habitat coexist with changes in flow, sediment passage and fish connectivity. Maximum impoundment is not automatically the optimum habitat condition."]},{"heading":"Distinction","facts":["The area of the Ramsar wetland, the entire engineering project and the total length of dam plus dykes are different measurements. **Hirakud—reservoir; Satkosia—downstream gorge; Ansupa—oxbow**."]}],"markdown":"# Hirakud Reservoir\n\n**Location:** Mahanadi River near Sambalpur, extending towards Bargarh and Jharsuguda · **Designation:** 12 October 2021 · **Registered Area:** 65,400 ha\n\n- **Origin:** Large **human-made reservoir behind Hirakud Dam on the Mahanadi**; distinct from a natural floodplain lake.\n- **Hydrology:** Stores monsoon water and regulates downstream flow towards the **Mahanadi delta**, supporting irrigation, flood moderation and hydropower.\n- **Ecology:** Open water, islands and seasonally exposed margins support fish production and resident and migratory birds.\n- **Tradeoff:** Storage benefits and aquatic habitat coexist with changes in flow, sediment passage and fish connectivity. Maximum impoundment is not automatically the optimum habitat condition.\n- **Distinction:** The area of the Ramsar wetland, the entire engineering project and the total length of dam plus dykes are different measurements. **Hirakud—reservoir; Satkosia—downstream gorge; Ansupa—oxbow**.\n","species":[]},"2470":{"name":"Satkosia Gorge","state":"Odisha","sections":[{"heading":"Location And Designation","facts":["**Location:** Mahanadi gorge across the Eastern Ghats landscape · **Designation:** 12 October 2021 · **Registered Area:** 98,196.7 ha"]},{"heading":"Type","facts":["**River-gorge wetland** where the **Mahanadi cuts through the Eastern Ghats**; includes river channels, marshes and adjacent forests."]},{"heading":"Setting","facts":["A transition between major peninsular biogeographic landscapes creates terrestrial and aquatic habitat diversity."]},{"heading":"Wildlife","facts":["Associated with **gharial [CR]**, **mugger crocodile [VU]** and threatened river turtles and terns in the wider river landscape."]},{"heading":"Functions","facts":["Fisheries, river connectivity, groundwater interactions, flood regulation and cultural/recreational uses."]},{"heading":"Distinction","facts":["**Satkosia is a river gorge**, **Ansupa an oxbow lake of the Mahanadi**, and **Hirakud a reservoir on the Mahanadi**. The Ramsar area is not automatically identical to Satkosia Tiger Reserve or sanctuary boundaries."]}],"markdown":"# Satkosia Gorge\n\n**Location:** Mahanadi gorge across the Eastern Ghats landscape · **Designation:** 12 October 2021 · **Registered Area:** 98,196.7 ha\n\n- **Type:** **River-gorge wetland** where the **Mahanadi cuts through the Eastern Ghats**; includes river channels, marshes and adjacent forests.\n- **Setting:** A transition between major peninsular biogeographic landscapes creates terrestrial and aquatic habitat diversity.\n- **Wildlife:** Associated with **gharial [CR]**, **mugger crocodile [VU]** and threatened river turtles and terns in the wider river landscape.\n- **Functions:** Fisheries, river connectivity, groundwater interactions, flood regulation and cultural/recreational uses.\n- **Distinction:** **Satkosia is a river gorge**, **Ansupa an oxbow lake of the Mahanadi**, and **Hirakud a reservoir on the Mahanadi**. The Ramsar area is not automatically identical to Satkosia Tiger Reserve or sanctuary boundaries.\n","species":["gharial","mugger crocodile"]},"2489":{"name":"Tampara Lake","state":"Odisha","sections":[{"heading":"Location And Designation","facts":["**Location:** Ganjam district, near the Rushikulya coastal landscape · **Designation:** 12 October 2021 · **Registered Area:** 300 ha"]},{"heading":"Type","facts":["Coastal **freshwater lake**, connected with the **Rushikulya** system; it is not a salt lake simply because it is close to the sea."]},{"heading":"Hydrology","facts":["Receives floodwater and helps store monsoon runoff; drying and extreme heat can reduce aquatic habitat."]},{"heading":"Wildlife","facts":["Supports fish and waterbirds including **common pochard [VU]** and **river tern [VU]**."]},{"heading":"Functions","facts":["Fisheries, local water use, agriculture, recreation and water-based transport connect the wetland with nearby communities."]},{"heading":"Distinction","facts":["**Tampara—Ganjam freshwater lake**; **Chilika—brackish coastal lagoon**. Protecting inflows, shallow margins and water quality matters more than treating the lake only as a tourism attraction."]}],"markdown":"# Tampara Lake\n\n**Location:** Ganjam district, near the Rushikulya coastal landscape · **Designation:** 12 October 2021 · **Registered Area:** 300 ha\n\n- **Type:** Coastal **freshwater lake**, connected with the **Rushikulya** system; it is not a salt lake simply because it is close to the sea.\n- **Hydrology:** Receives floodwater and helps store monsoon runoff; drying and extreme heat can reduce aquatic habitat.\n- **Wildlife:** Supports fish and waterbirds including **common pochard [VU]** and **river tern [VU]**.\n- **Functions:** Fisheries, local water use, agriculture, recreation and water-based transport connect the wetland with nearby communities.\n- **Distinction:** **Tampara—Ganjam freshwater lake**; **Chilika—brackish coastal lagoon**. Protecting inflows, shallow margins and water quality matters more than treating the lake only as a tourism attraction.\n","species":["common pochard","river tern"]},"2408":{"name":"Beas Conservation Reserve","state":"Punjab","sections":[{"heading":"Location And Designation","facts":["**Location:** Beas River from the foothills towards Harike · **Designation:** 26 September 2019 · **Registered Area:** 6,428.9 ha"]},{"heading":"Type And Extent","facts":["Approximately **185 km of riverine habitat**, with braided channels, islands and sand bars; the Ramsar boundary includes a flowing-river landscape, not a reservoir alone."]},{"heading":"Wildlife","facts":["India’s known **Indus river dolphin [EN]** population is associated with the Beas. Also supports **golden mahseer [EN]**, **hog deer [EN]** and **smooth-coated otter [VU]**."]},{"heading":"Reintroduction","facts":["A **gharial [CR]** reintroduction programme began in **2017**, after the species had disappeared locally; reintroduced presence must be distinguished from an uninterrupted native population."]},{"heading":"Connectivity","facts":["River flow, pools and connections between habitats maintain fish movement and dolphin feeding grounds; the reserve reaches the Harike headworks landscape."]},{"heading":"Pressures","facts":["Sewage, agricultural runoff, damaging fishing practices and hydrological regulation affect the river ecosystem. **Platanista minor** is distinct from the Ganges river dolphin."]}],"markdown":"# Beas Conservation Reserve\n\n**Location:** Beas River from the foothills towards Harike · **Designation:** 26 September 2019 · **Registered Area:** 6,428.9 ha\n\n- **Type And Extent:** Approximately **185 km of riverine habitat**, with braided channels, islands and sand bars; the Ramsar boundary includes a flowing-river landscape, not a reservoir alone.\n- **Wildlife:** India’s known **Indus river dolphin [EN]** population is associated with the Beas. Also supports **golden mahseer [EN]**, **hog deer [EN]** and **smooth-coated otter [VU]**.\n- **Reintroduction:** A **gharial [CR]** reintroduction programme began in **2017**, after the species had disappeared locally; reintroduced presence must be distinguished from an uninterrupted native population.\n- **Connectivity:** River flow, pools and connections between habitats maintain fish movement and dolphin feeding grounds; the reserve reaches the Harike headworks landscape.\n- **Pressures:** Sewage, agricultural runoff, damaging fishing practices and hydrological regulation affect the river ecosystem. **Platanista minor** is distinct from the Ganges river dolphin.\n","species":["indus river dolphin","golden mahseer","hog deer","smooth-coated otter","gharial"]},"462":{"name":"Harike Lake","state":"Punjab","sections":[{"heading":"Location And Designation","facts":["**Location:** Harike Headworks, confluence of the Beas and Sutlej · **Designation:** 23 March 1990 · **Registered Area:** 4,100 ha"]},{"heading":"Type And Origin","facts":["Shallow **human-made reservoir** created at a barrage where the **Beas meets the Sutlej**; islands, marshes and extensive aquatic vegetation diversify habitat."]},{"heading":"Hydrology","facts":["The confluence and headworks regulate water diverted into canals for irrigation. Pollution or altered flow in either river can affect the wetland."]},{"heading":"Ecology","facts":["A major wintering and staging ground for migratory ducks and other waterbirds; shallow feeding areas and islands are important, not just the water surface."]},{"heading":"Pressures","facts":["River-borne pollution, sediment accumulation and excessive floating weeds can lower habitat quality and obstruct water movement."]},{"heading":"Distinction","facts":["**Harike—Beas + Sutlej**; **Ropar—Sutlej barrage**; **Kanjli—Kali Bein**. These are three separate Ramsar sites."]}],"markdown":"# Harike Lake\n\n**Location:** Harike Headworks, confluence of the Beas and Sutlej · **Designation:** 23 March 1990 · **Registered Area:** 4,100 ha\n\n- **Type And Origin:** Shallow **human-made reservoir** created at a barrage where the **Beas meets the Sutlej**; islands, marshes and extensive aquatic vegetation diversify habitat.\n- **Hydrology:** The confluence and headworks regulate water diverted into canals for irrigation. Pollution or altered flow in either river can affect the wetland.\n- **Ecology:** A major wintering and staging ground for migratory ducks and other waterbirds; shallow feeding areas and islands are important, not just the water surface.\n- **Pressures:** River-borne pollution, sediment accumulation and excessive floating weeds can lower habitat quality and obstruct water movement.\n- **Distinction:** **Harike—Beas + Sutlej**; **Ropar—Sutlej barrage**; **Kanjli—Kali Bein**. These are three separate Ramsar sites.\n","species":[]},"1160":{"name":"Kanjli","state":"Punjab","sections":[{"heading":"Location And Designation","facts":["**Location:** Kapurthala, Kali Bein stream · **Designation:** 22 January 2002 · **Registered Area:** 183 ha"]},{"heading":"Origin","facts":["A barrage across the **Kali Bein** in **1870** created a water-storage wetland supporting irrigation; the system includes the stream and adjoining marsh."]},{"heading":"Hydrology","facts":["Supports both seasonal groundwater recharge and discharge. These are opposite water movements and may occur in different seasons or parts of the wetland."]},{"heading":"Ecology","facts":["Aquatic, marsh and terrestrial vegetation produce habitat diversity within an intensively cultivated landscape."]},{"heading":"Culture And Use","facts":["The Kali Bein is closely associated with **Guru Nanak**; irrigation, aquatic-resource use and recreation connect conservation with local communities."]},{"heading":"Pressures And Contrast","facts":["Sewage and other pollution, invasive floating weeds, catchment tree loss and excessive grazing threaten ecological character. **Kanjli is on Kali Bein**, not at the Beas–Sutlej confluence."]}],"markdown":"# Kanjli\n\n**Location:** Kapurthala, Kali Bein stream · **Designation:** 22 January 2002 · **Registered Area:** 183 ha\n\n- **Origin:** A barrage across the **Kali Bein** in **1870** created a water-storage wetland supporting irrigation; the system includes the stream and adjoining marsh.\n- **Hydrology:** Supports both seasonal groundwater recharge and discharge. These are opposite water movements and may occur in different seasons or parts of the wetland.\n- **Ecology:** Aquatic, marsh and terrestrial vegetation produce habitat diversity within an intensively cultivated landscape.\n- **Culture And Use:** The Kali Bein is closely associated with **Guru Nanak**; irrigation, aquatic-resource use and recreation connect conservation with local communities.\n- **Pressures And Contrast:** Sewage and other pollution, invasive floating weeds, catchment tree loss and excessive grazing threaten ecological character. **Kanjli is on Kali Bein**, not at the Beas–Sutlej confluence.\n","species":[]},"2414":{"name":"Keshopur-Miani Community Reserve","state":"Punjab","sections":[{"heading":"Location And Designation","facts":["**Location:** Gurdaspur district · **Designation:** 26 September 2019 · **Registered Area:** 343.9 ha"]},{"heading":"Type","facts":["Mosaic of **natural marsh, managed fishponds and agricultural wetlands** maintained largely by rainfall runoff."]},{"heading":"Community Management","facts":["Community-reserve arrangements combine habitat protection with local production, including fish and cultivated aquatic crops; it illustrates **wise use**, not complete exclusion of people."]},{"heading":"Wildlife","facts":["Supports **common pochard [VU]** and **spotted pond turtle/black pond turtle [EN]**, among other wetland fauna."]},{"heading":"Hydrological Importance","facts":["Retaining shallow water and connectivity sustains seasonal habitat, groundwater functions and aquatic production."]},{"heading":"Distinction","facts":["A **Community Reserve** under Indian wildlife law differs from a state-owned **Conservation Reserve** and from the international Ramsar label. Cultivation within a wetland mosaic does not make every paddy field a Ramsar site."]}],"markdown":"# Keshopur-Miani Community Reserve\n\n**Location:** Gurdaspur district · **Designation:** 26 September 2019 · **Registered Area:** 343.9 ha\n\n- **Type:** Mosaic of **natural marsh, managed fishponds and agricultural wetlands** maintained largely by rainfall runoff.\n- **Community Management:** Community-reserve arrangements combine habitat protection with local production, including fish and cultivated aquatic crops; it illustrates **wise use**, not complete exclusion of people.\n- **Wildlife:** Supports **common pochard [VU]** and **spotted pond turtle/black pond turtle [EN]**, among other wetland fauna.\n- **Hydrological Importance:** Retaining shallow water and connectivity sustains seasonal habitat, groundwater functions and aquatic production.\n- **Distinction:** A **Community Reserve** under Indian wildlife law differs from a state-owned **Conservation Reserve** and from the international Ramsar label. Cultivation within a wetland mosaic does not make every paddy field a Ramsar site.\n","species":["common pochard","spotted pond turtle"]},"2407":{"name":"Nangal Wildlife Sanctuary","state":"Punjab","sections":[{"heading":"Location And Designation","facts":["**Location:** Nangal, Rupnagar district · **Designation:** 26 September 2019 · **Registered Area:** 116 ha"]},{"heading":"Origin","facts":["Small reservoir wetland in the Shivalik foothills associated with the **Bhakra–Nangal project on the Sutlej**; not the entire Govind Sagar reservoir."]},{"heading":"Hydrological Role","facts":["Regulates downstream water delivery and provides flood moderation. The aquatic pool and surrounding vegetation create an important foothill refuge."]},{"heading":"Wildlife","facts":["The sanctuary landscape supports waterbirds and terrestrial fauna, including **Indian pangolin [EN]**, **Egyptian vulture [EN]** and **leopard [VU]**."]},{"heading":"Protection And Use","facts":["A **Wildlife Sanctuary** as well as a Ramsar site; water regulation benefits downstream communities alongside biodiversity conservation."]},{"heading":"Distinction","facts":["**Nangal and Ropar are Sutlej-associated**; **Harike is the Beas–Sutlej confluence**. Compare location and function rather than assuming all Punjab wetlands have the same origin."]}],"markdown":"# Nangal Wildlife Sanctuary\n\n**Location:** Nangal, Rupnagar district · **Designation:** 26 September 2019 · **Registered Area:** 116 ha\n\n- **Origin:** Small reservoir wetland in the Shivalik foothills associated with the **Bhakra–Nangal project on the Sutlej**; not the entire Govind Sagar reservoir.\n- **Hydrological Role:** Regulates downstream water delivery and provides flood moderation. The aquatic pool and surrounding vegetation create an important foothill refuge.\n- **Wildlife:** The sanctuary landscape supports waterbirds and terrestrial fauna, including **Indian pangolin [EN]**, **Egyptian vulture [EN]** and **leopard [VU]**.\n- **Protection And Use:** A **Wildlife Sanctuary** as well as a Ramsar site; water regulation benefits downstream communities alongside biodiversity conservation.\n- **Distinction:** **Nangal and Ropar are Sutlej-associated**; **Harike is the Beas–Sutlej confluence**. Compare location and function rather than assuming all Punjab wetlands have the same origin.\n","species":["indian pangolin","egyptian vulture","leopard"]},"1161":{"name":"Ropar","state":"Punjab","sections":[{"heading":"Location And Designation","facts":["**Location:** Rupnagar/Ropar, Sutlej River · **Designation:** 22 January 2002 · **Registered Area:** 1,365 ha"]},{"heading":"Origin","facts":["Human-made river–lake wetland produced by the **Ropar barrage on the Sutlej**, completed in **1952**, for water diversion and irrigation."]},{"heading":"Ecology","facts":["River channels, reservoir margins and adjoining vegetation support fish, resident and migratory birds, and riparian mammals such as **smooth-coated otter [VU]**."]},{"heading":"Function","facts":["Fish habitats support food webs and local fisheries; water regulation supplies agriculture and domestic use. Habitat quality depends on both the barrage pool and its upstream catchment."]},{"heading":"Pressures","facts":["Erosion of surrounding hills increases siltation; industrial and domestic pollutants and invasive plants affect water quality and habitat structure."]},{"heading":"Distinction","facts":["The Ropar Ramsar site, Nangal reservoir wetland and Harike confluence are separate parts of the wider Sutlej–Beas water landscape, not interchangeable names."]}],"markdown":"# Ropar\n\n**Location:** Rupnagar/Ropar, Sutlej River · **Designation:** 22 January 2002 · **Registered Area:** 1,365 ha\n\n- **Origin:** Human-made river–lake wetland produced by the **Ropar barrage on the Sutlej**, completed in **1952**, for water diversion and irrigation.\n- **Ecology:** River channels, reservoir margins and adjoining vegetation support fish, resident and migratory birds, and riparian mammals such as **smooth-coated otter [VU]**.\n- **Function:** Fish habitats support food webs and local fisheries; water regulation supplies agriculture and domestic use. Habitat quality depends on both the barrage pool and its upstream catchment.\n- **Pressures:** Erosion of surrounding hills increases siltation; industrial and domestic pollutants and invasive plants affect water quality and habitat structure.\n- **Distinction:** The Ropar Ramsar site, Nangal reservoir wetland and Harike confluence are separate parts of the wider Sutlej–Beas water landscape, not interchangeable names.\n","species":["smooth-coated otter"]},"230":{"name":"Keoladeo National Park","state":"Rajasthan","sections":[{"heading":"Location And Designation","facts":["**Location:** Bharatpur · **Designation:** 1 October 1981 · **Registered Area:** 2,873 ha"]},{"heading":"Type And Origin","facts":["Managed, shallow **freshwater wetland** with artificial seasonal impoundments, grassland and woodland. Artificial wetlands can qualify for Ramsar designation."]},{"heading":"Water Regime","facts":["Water supply, depth, timing and drawdown determine feeding conditions for different waterbirds; a permanent deep reservoir would not reproduce the same habitat mosaic."]},{"heading":"Wildlife","facts":["Important for resident breeding colonies and winter visitors. **Siberian crane [CR]** has a historical association with Bharatpur; it must not be described as a regular present-day winter visitor."]},{"heading":"Conservation","facts":["Water shortage, altered grazing and invasive vegetation have changed habitat structure. Excess plant growth can replace open feeding areas rather than simply increase useful habitat."]},{"heading":"Designations","facts":["**National Park**, **UNESCO World Heritage property**, and one of India’s first two Ramsar sites. Entered the **Montreux Record in 1990** and remains listed as of the inventory date."]}],"markdown":"# Keoladeo National Park\n\n**Location:** Bharatpur · **Designation:** 1 October 1981 · **Registered Area:** 2,873 ha\n\n- **Type And Origin:** Managed, shallow **freshwater wetland** with artificial seasonal impoundments, grassland and woodland. Artificial wetlands can qualify for Ramsar designation.\n- **Water Regime:** Water supply, depth, timing and drawdown determine feeding conditions for different waterbirds; a permanent deep reservoir would not reproduce the same habitat mosaic.\n- **Wildlife:** Important for resident breeding colonies and winter visitors. **Siberian crane [CR]** has a historical association with Bharatpur; it must not be described as a regular present-day winter visitor.\n- **Conservation:** Water shortage, altered grazing and invasive vegetation have changed habitat structure. Excess plant growth can replace open feeding areas rather than simply increase useful habitat.\n- **Designations:** **National Park**, **UNESCO World Heritage property**, and one of India’s first two Ramsar sites. Entered the **Montreux Record in 1990** and remains listed as of the inventory date.\n","species":["siberian crane"]},"2568":{"name":"Khichan Wetland","state":"Rajasthan","sections":[{"heading":"Location And Designation","facts":["**Location:** Khichan village, Phalodi district, northern Thar · **Designation:** 19 February 2025 · **Registered Area:** 54.2 ha"]},{"heading":"Components","facts":["Small desert wetland complex including **Ratri Nadi and Vijaysagar Talab**, with riparian and scrub habitat."]},{"heading":"Wildlife","facts":["Internationally notable wintering congregation of **demoiselle crane [LC]**; the association is with seasonal migrants, not a claim that all cranes at Khichan breed there."]},{"heading":"Community Role","facts":["Village protection, traditional feeding and attention to power-line collisions and stray-dog attacks support crane survival."]},{"heading":"Ecology","facts":["Even small waterbodies provide critical resting and drinking habitat within a dry desert landscape."]},{"heading":"Distinction","facts":["**Khichan—demoiselle crane**; **Sarsai Nawar—sarus crane**; **Tso Kar/Tsomoriri—black-necked crane**. Older descriptions may use Jodhpur, reflecting former district boundaries."]}],"markdown":"# Khichan Wetland\n\n**Location:** Khichan village, Phalodi district, northern Thar · **Designation:** 19 February 2025 · **Registered Area:** 54.2 ha\n\n- **Components:** Small desert wetland complex including **Ratri Nadi and Vijaysagar Talab**, with riparian and scrub habitat.\n- **Wildlife:** Internationally notable wintering congregation of **demoiselle crane [LC]**; the association is with seasonal migrants, not a claim that all cranes at Khichan breed there.\n- **Community Role:** Village protection, traditional feeding and attention to power-line collisions and stray-dog attacks support crane survival.\n- **Ecology:** Even small waterbodies provide critical resting and drinking habitat within a dry desert landscape.\n- **Distinction:** **Khichan—demoiselle crane**; **Sarsai Nawar—sarus crane**; **Tso Kar/Tsomoriri—black-necked crane**. Older descriptions may use Jodhpur, reflecting former district boundaries.\n","species":["demoiselle crane"]},"2567":{"name":"Menar Wetland Complex","state":"Rajasthan","sections":[{"heading":"Location And Designation","facts":["**Location:** Menar–Kheroda villages, Udaipur district · **Designation:** 19 February 2025 · **Registered Area:** 463.4 ha"]},{"heading":"Components","facts":["**Braham Talab, Dhand Talab and Kheroda Talab**, with agricultural land connecting parts of the complex."]},{"heading":"Hydrology","facts":["Monsoon flooding extends waterbird habitat into fields; the seasonal land–water transition is integral to the wetland."]},{"heading":"Wildlife","facts":["Recorded **white-rumped vulture [CR]** and **Indian vulture [CR]**, with substantial resident and migratory waterbird diversity."]},{"heading":"Community Conservation","facts":["Local residents protect birds and oppose poaching and fishing; this is a prominent community-stewardship landscape."]},{"heading":"Distinction","facts":["**Menar—freshwater pond complex, Udaipur**; **Khichan—Thar wetland and demoiselle cranes**; **Sambhar—inland saline lake**. The state contains markedly different wetland types."]}],"markdown":"# Menar Wetland Complex\n\n**Location:** Menar–Kheroda villages, Udaipur district · **Designation:** 19 February 2025 · **Registered Area:** 463.4 ha\n\n- **Components:** **Braham Talab, Dhand Talab and Kheroda Talab**, with agricultural land connecting parts of the complex.\n- **Hydrology:** Monsoon flooding extends waterbird habitat into fields; the seasonal land–water transition is integral to the wetland.\n- **Wildlife:** Recorded **white-rumped vulture [CR]** and **Indian vulture [CR]**, with substantial resident and migratory waterbird diversity.\n- **Community Conservation:** Local residents protect birds and oppose poaching and fishing; this is a prominent community-stewardship landscape.\n- **Distinction:** **Menar—freshwater pond complex, Udaipur**; **Khichan—Thar wetland and demoiselle cranes**; **Sambhar—inland saline lake**. The state contains markedly different wetland types.\n","species":["white-rumped vulture","indian vulture"]},"464":{"name":"Sambhar Lake","state":"Rajasthan","sections":[{"heading":"Location And Designation","facts":["**Location:** Sambhar basin west of Jaipur · **Designation:** 23 March 1990 · **Registered Area:** 24,000 ha"]},{"heading":"Type","facts":["**Inland saline, endorheic lake**—water collects in a closed basin with no natural outlet to the sea. It is not a coastal lagoon."]},{"heading":"Water Balance","facts":["Seasonal streams and runoff recharge the shallow basin; evaporation concentrates dissolved salts. Water spread and salinity fluctuate markedly through the year."]},{"heading":"Ecology","facts":["Salt-tolerant microorganisms and associated food chains support **greater flamingo [LC]** and **lesser flamingo [NT]**, with other wintering waterbirds."]},{"heading":"Livelihoods And Pressure","facts":["Salt extraction is the characteristic economic activity. Excessive water abstraction, altered inflows, encroachment and changes to shallow-water habitat can disturb the salt–water–food-web balance."]},{"heading":"Distinction","facts":["India’s major inland salt-lake system; unlike **Lonar**, its defining origin is not meteorite impact. Ramsar status does not mean that all traditional salt-related livelihoods are automatically prohibited by the Convention."]}],"markdown":"# Sambhar Lake\n\n**Location:** Sambhar basin west of Jaipur · **Designation:** 23 March 1990 · **Registered Area:** 24,000 ha\n\n- **Type:** **Inland saline, endorheic lake**—water collects in a closed basin with no natural outlet to the sea. It is not a coastal lagoon.\n- **Water Balance:** Seasonal streams and runoff recharge the shallow basin; evaporation concentrates dissolved salts. Water spread and salinity fluctuate markedly through the year.\n- **Ecology:** Salt-tolerant microorganisms and associated food chains support **greater flamingo [LC]** and **lesser flamingo [NT]**, with other wintering waterbirds.\n- **Livelihoods And Pressure:** Salt extraction is the characteristic economic activity. Excessive water abstraction, altered inflows, encroachment and changes to shallow-water habitat can disturb the salt–water–food-web balance.\n- **Distinction:** India’s major inland salt-lake system; unlike **Lonar**, its defining origin is not meteorite impact. Ramsar status does not mean that all traditional salt-related livelihoods are automatically prohibited by the Convention.\n","species":["greater flamingo","lesser flamingo"]},"2581":{"name":"Siliserh Lake","state":"Rajasthan","sections":[{"heading":"Location And Designation","facts":["**Location:** Alwar district, Sariska landscape · **Designation:** 7 July 2025 · **Registered Area:** 316 ha"]},{"heading":"Origin","facts":["**Human-made freshwater lake**, created in the nineteenth century; lies within the **buffer landscape of Sariska Tiger Reserve**."]},{"heading":"Wildlife","facts":["Provides water and wetland habitat in a semi-arid setting; records include **river tern [VU]**, **black stork [LC]** and **tiger [EN]** in the surrounding reserve landscape."]},{"heading":"Culture","facts":["**Siliserh Lake Palace** overlooks the reservoir; drinking-water supply, recreation and tourism are major historical uses."]},{"heading":"Pressures","facts":["Intensive agriculture, settlement growth and visitor pressure can affect the catchment and shore."]},{"heading":"Distinction","facts":["A lake within a tiger-reserve buffer does not mean the Ramsar site equals the reserve or its core. **Siliserh is freshwater**, unlike Rajasthan’s saline Sambhar."]}],"markdown":"# Siliserh Lake\n\n**Location:** Alwar district, Sariska landscape · **Designation:** 7 July 2025 · **Registered Area:** 316 ha\n\n- **Origin:** **Human-made freshwater lake**, created in the nineteenth century; lies within the **buffer landscape of Sariska Tiger Reserve**.\n- **Wildlife:** Provides water and wetland habitat in a semi-arid setting; records include **river tern [VU]**, **black stork [LC]** and **tiger [EN]** in the surrounding reserve landscape.\n- **Culture:** **Siliserh Lake Palace** overlooks the reservoir; drinking-water supply, recreation and tourism are major historical uses.\n- **Pressures:** Intensive agriculture, settlement growth and visitor pressure can affect the catchment and shore.\n- **Distinction:** A lake within a tiger-reserve buffer does not mean the Ramsar site equals the reserve or its core. **Siliserh is freshwater**, unlike Rajasthan’s saline Sambhar.\n","species":["river tern","black stork","tiger"]},"2560":{"name":"Khachoedpalri Wetland","state":"Sikkim","sections":[{"heading":"Location And Designation","facts":["**Location:** Gyalshing district, western Sikkim · **Designation:** 15 July 2024 · **Registered Area:** 172 ha"]},{"heading":"Name And Type","facts":["**Khachoedpalri/Khecheopalri**, a sacred Himalayan freshwater lake surrounded by **peatland and temperate evergreen forest**."]},{"heading":"Ecology","facts":["The lake, peat margins and forest catchment create a connected wetland rather than only a water surface; peat stores partly decomposed organic material under waterlogged conditions."]},{"heading":"Wildlife","facts":["**Baer’s pochard [CR]** uses the migratory-bird habitat; the wider forest landscape supports **red panda [EN]** and **Asiatic black bear [VU]**."]},{"heading":"Culture","facts":["Sacred to local Himalayan communities; pilgrimage and tourism have to retain shore vegetation, water quality and low disturbance."]},{"heading":"Distinction","facts":["Its **15 July 2024 designation** differs from the later public announcement. Species occurring here are not necessarily endemic to this lake or to Sikkim."]}],"markdown":"# Khachoedpalri Wetland\n\n**Location:** Gyalshing district, western Sikkim · **Designation:** 15 July 2024 · **Registered Area:** 172 ha\n\n- **Name And Type:** **Khachoedpalri/Khecheopalri**, a sacred Himalayan freshwater lake surrounded by **peatland and temperate evergreen forest**.\n- **Ecology:** The lake, peat margins and forest catchment create a connected wetland rather than only a water surface; peat stores partly decomposed organic material under waterlogged conditions.\n- **Wildlife:** **Baer’s pochard [CR]** uses the migratory-bird habitat; the wider forest landscape supports **red panda [EN]** and **Asiatic black bear [VU]**.\n- **Culture:** Sacred to local Himalayan communities; pilgrimage and tourism have to retain shore vegetation, water quality and low disturbance.\n- **Distinction:** Its **15 July 2024 designation** differs from the later public announcement. Species occurring here are not necessarily endemic to this lake or to Sikkim.\n","species":["baer’s pochard","red panda","asiatic black bear"]},"2491":{"name":"Chitrangudi Bird Sanctuary","state":"Tamil Nadu","sections":[{"heading":"Location And Designation","facts":["**Location:** Chitrangudi village, Ramanathapuram district · **Designation:** 8 November 2021 · **Registered Area:** 260.5 ha"]},{"heading":"Type","facts":["Seasonal **freshwater tank**, locally **Chitrangudi Kanmoli**, adjacent to Kanjirankulam; protected as a Bird Sanctuary."]},{"heading":"Wildlife","facts":["Nesting and feeding habitat for **spot-billed pelican [NT]**, **painted stork [LC]**, **little egret [LC]** and **grey heron [LC]**."]},{"heading":"Hydrology","facts":["Rainfall and runoff govern water availability; periodic drying and wet-season storage are central features of the tank system."]},{"heading":"Functions","facts":["Stores floodwater, traps sediment and nutrients, supports birds and provides local agricultural benefits."]},{"heading":"Pressure And Contrast","facts":["Drought, reduced inflow, disturbance and degradation of nesting vegetation can affect the colony. Winter occurrence and local breeding are separate attributes; not every winter visitor breeds at the site."]}],"markdown":"# Chitrangudi Bird Sanctuary\n\n**Location:** Chitrangudi village, Ramanathapuram district · **Designation:** 8 November 2021 · **Registered Area:** 260.5 ha\n\n- **Type:** Seasonal **freshwater tank**, locally **Chitrangudi Kanmoli**, adjacent to Kanjirankulam; protected as a Bird Sanctuary.\n- **Wildlife:** Nesting and feeding habitat for **spot-billed pelican [NT]**, **painted stork [LC]**, **little egret [LC]** and **grey heron [LC]**.\n- **Hydrology:** Rainfall and runoff govern water availability; periodic drying and wet-season storage are central features of the tank system.\n- **Functions:** Stores floodwater, traps sediment and nutrients, supports birds and provides local agricultural benefits.\n- **Pressure And Contrast:** Drought, reduced inflow, disturbance and degradation of nesting vegetation can affect the colony. Winter occurrence and local breeding are separate attributes; not every winter visitor breeds at the site.\n","species":["spot-billed pelican","painted stork","little egret","grey heron"]},"2472":{"name":"Gulf of Mannar Marine Biosphere Reserve","state":"Tamil Nadu","sections":[{"heading":"Location And Designation","facts":["**Location:** Gulf of Mannar, Ramanathapuram–Thoothukudi coast · **Designation:** 8 April 2022 · **Registered Area:** 52,671.9 ha"]},{"heading":"Type","facts":["**Marine–coastal wetland** with coral reefs, seagrass beds, mangroves, islands, mudflats and shallow sea; lies between southeastern India and Sri Lanka."]},{"heading":"Protected Landscape","facts":["The **21-island Marine National Park** is within the larger biosphere-reserve landscape. Ramsar, National Park and UNESCO **Man and the Biosphere** recognition are different frameworks; MAB recognition is not World Heritage inscription."]},{"heading":"Wildlife","facts":["**Dugong [VU]** depends on seagrass; **whale shark [EN]** is a filter-feeding fish; **hawksbill turtle [CR]** is associated with coral-reef food webs."]},{"heading":"Mechanisms","facts":["Seagrasses are flowering marine plants with roots and rhizomes, unlike algae. Corals are animals; their reef-building function depends on suitable temperature, light and water quality."]},{"heading":"Pressures","facts":["Destructive fishing, bycatch, habitat extraction, marine heat stress, sediment and land-based pollution threaten connected reef–seagrass–mangrove habitats. The Ramsar boundary is not the entire Gulf."]}],"markdown":"# Gulf of Mannar Marine Biosphere Reserve\n\n**Location:** Gulf of Mannar, Ramanathapuram–Thoothukudi coast · **Designation:** 8 April 2022 · **Registered Area:** 52,671.9 ha\n\n- **Type:** **Marine–coastal wetland** with coral reefs, seagrass beds, mangroves, islands, mudflats and shallow sea; lies between southeastern India and Sri Lanka.\n- **Protected Landscape:** The **21-island Marine National Park** is within the larger biosphere-reserve landscape. Ramsar, National Park and UNESCO **Man and the Biosphere** recognition are different frameworks; MAB recognition is not World Heritage inscription.\n- **Wildlife:** **Dugong [VU]** depends on seagrass; **whale shark [EN]** is a filter-feeding fish; **hawksbill turtle [CR]** is associated with coral-reef food webs.\n- **Mechanisms:** Seagrasses are flowering marine plants with roots and rhizomes, unlike algae. Corals are animals; their reef-building function depends on suitable temperature, light and water quality.\n- **Pressures:** Destructive fishing, bycatch, habitat extraction, marine heat stress, sediment and land-based pollution threaten connected reef–seagrass–mangrove habitats. The Ramsar boundary is not the entire Gulf.\n","species":["dugong","whale shark","hawksbill turtle"]},"2486":{"name":"Kanjirankulam Bird Sanctuary","state":"Tamil Nadu","sections":[{"heading":"Location And Designation","facts":["**Location:** Ramanathapuram district, near Mudukulathur · **Designation:** 8 April 2022 · **Registered Area:** 96.9 ha"]},{"heading":"Type","facts":["Seasonal **freshwater tank and tree-nesting habitat**, protected as **Kanjirankulam Bird Sanctuary**."]},{"heading":"Wildlife","facts":["Colonial nesting birds include **painted stork [LC]**, **spot-billed pelican [NT]**, **oriental darter [LC]** and **black-headed ibis [LC]**."]},{"heading":"Habitat Mechanism","facts":["Native **babul [LC]** trees provide nesting structure; replacement or suppression by invasive thorny trees can change nesting suitability rather than merely add “green cover”."]},{"heading":"Community Functions","facts":["Irrigation, flood buffering and local bird protection link the sanctuary with surrounding villages."]},{"heading":"Pressures And Contrast","facts":["Seasonal water variability, invasive vegetation and disturbance matter. **Kanjirankulam and adjacent Chitrangudi are separate Ramsar sites**, not alternative spellings of the same sanctuary."]}],"markdown":"# Kanjirankulam Bird Sanctuary\n\n**Location:** Ramanathapuram district, near Mudukulathur · **Designation:** 8 April 2022 · **Registered Area:** 96.9 ha\n\n- **Type:** Seasonal **freshwater tank and tree-nesting habitat**, protected as **Kanjirankulam Bird Sanctuary**.\n- **Wildlife:** Colonial nesting birds include **painted stork [LC]**, **spot-billed pelican [NT]**, **oriental darter [LC]** and **black-headed ibis [LC]**.\n- **Habitat Mechanism:** Native **babul [LC]** trees provide nesting structure; replacement or suppression by invasive thorny trees can change nesting suitability rather than merely add “green cover”.\n- **Community Functions:** Irrigation, flood buffering and local bird protection link the sanctuary with surrounding villages.\n- **Pressures And Contrast:** Seasonal water variability, invasive vegetation and disturbance matter. **Kanjirankulam and adjacent Chitrangudi are separate Ramsar sites**, not alternative spellings of the same sanctuary.\n","species":["painted stork","spot-billed pelican","oriental darter","black-headed ibis","babul"]},"2537":{"name":"Karaivetti Bird Sanctuary","state":"Tamil Nadu","sections":[{"heading":"Location And Designation","facts":["**Location:** Ariyalur district · **Designation:** 24 May 2023 · **Registered Area:** 453.7 ha"]},{"heading":"Type","facts":["Large **inland freshwater irrigation tank** protected as a Bird Sanctuary, within the wider Cauvery irrigation landscape."]},{"heading":"Water Supply","facts":["The **Mettur reservoir network** helps sustain water during dry periods; seasonal recession creates feeding areas for larger waterbirds."]},{"heading":"Wildlife","facts":["**Babul [LC]** supports nesting and roosting; recorded birds include **painted stork [LC]**, **oriental darter [LC]** and **greater spotted eagle [VU]**. The site also supports **Indian flapshell turtle [VU]**."]},{"heading":"Functions","facts":["Irrigation of surrounding farmland, colonial bird breeding, groundwater support and seasonal refuge."]},{"heading":"Distinction","facts":["Inland freshwater character contrasts with **Kazhuveli’s north–south saline-to-fresh gradient** and **Point Calimere’s coastal salt-marsh mosaic**."]}],"markdown":"# Karaivetti Bird Sanctuary\n\n**Location:** Ariyalur district · **Designation:** 24 May 2023 · **Registered Area:** 453.7 ha\n\n- **Type:** Large **inland freshwater irrigation tank** protected as a Bird Sanctuary, within the wider Cauvery irrigation landscape.\n- **Water Supply:** The **Mettur reservoir network** helps sustain water during dry periods; seasonal recession creates feeding areas for larger waterbirds.\n- **Wildlife:** **Babul [LC]** supports nesting and roosting; recorded birds include **painted stork [LC]**, **oriental darter [LC]** and **greater spotted eagle [VU]**. The site also supports **Indian flapshell turtle [VU]**.\n- **Functions:** Irrigation of surrounding farmland, colonial bird breeding, groundwater support and seasonal refuge.\n- **Distinction:** Inland freshwater character contrasts with **Kazhuveli’s north–south saline-to-fresh gradient** and **Point Calimere’s coastal salt-marsh mosaic**.\n","species":["babul","painted stork","oriental darter","greater spotted eagle","indian flapshell turtle"]},"2480":{"name":"Karikili Bird Sanctuary","state":"Tamil Nadu","sections":[{"heading":"Location And Designation","facts":["**Location:** Chengalpattu–Kancheepuram landscape · **Designation:** 8 April 2022 · **Registered Area:** 58.4 ha"]},{"heading":"Components","facts":["**Two rain-fed, non-perennial irrigation tanks**, with planted nesting trees and surrounding scrub/low hills."]},{"heading":"Wildlife","facts":["Breeding habitat for **oriental darter [LC]** and **spot-billed pelican [NT]**, among other colonial waterbirds."]},{"heading":"Hydrology","facts":["Large year-to-year variation in rainfall changes water spread and duration; “non-perennial” does not make the tanks ecologically unimportant."]},{"heading":"Community Link","facts":["Protection of waterbirds supports nutrient-rich irrigation water, giving farmers a direct incentive to retain bird habitat."]},{"heading":"Distinction","facts":["**Karikili and Vedanthangal are separate sites**. Open feeding water, nesting trees and low-disturbance conditions all matter; simply increasing tree cover everywhere would not replace the wetland mosaic."]}],"markdown":"# Karikili Bird Sanctuary\n\n**Location:** Chengalpattu–Kancheepuram landscape · **Designation:** 8 April 2022 · **Registered Area:** 58.4 ha\n\n- **Components:** **Two rain-fed, non-perennial irrigation tanks**, with planted nesting trees and surrounding scrub/low hills.\n- **Wildlife:** Breeding habitat for **oriental darter [LC]** and **spot-billed pelican [NT]**, among other colonial waterbirds.\n- **Hydrology:** Large year-to-year variation in rainfall changes water spread and duration; “non-perennial” does not make the tanks ecologically unimportant.\n- **Community Link:** Protection of waterbirds supports nutrient-rich irrigation water, giving farmers a direct incentive to retain bird habitat.\n- **Distinction:** **Karikili and Vedanthangal are separate sites**. Open feeding water, nesting trees and low-disturbance conditions all matter; simply increasing tree cover everywhere would not replace the wetland mosaic.\n","species":["oriental darter","spot-billed pelican"]},"2548":{"name":"Kazhuveli Bird Sanctuary","state":"Tamil Nadu","sections":[{"heading":"Location And Designation","facts":["**Location:** Villupuram district, north of Puducherry · **Designation:** 16 January 2024 · **Registered Area:** 5,151.6 ha"]},{"heading":"Type","facts":["Large **brackish-to-fresh coastal wetland**, protected as **Kazhuveli Bird Sanctuary** in 2021."]},{"heading":"Sea Connection","facts":["Connected northward to the Bay of Bengal through **Uppukalli Creek**; seawater entry during tides or cyclones produces a generally saltier north and fresher southern basin."]},{"heading":"Ecology","facts":["The salinity gradient and wetland vegetation support fish movement, spawning and diverse waterbirds; nesting trees support **spot-billed pelican [NT]**."]},{"heading":"Wildlife","facts":["Recorded **greater spotted eagle [VU]**, **eastern imperial eagle [VU]** and **river tern [VU]** illustrate raptor and aquatic-bird associations."]},{"heading":"Distinction","facts":["The Ramsar area is **5,151.6 ha**. Descriptions calling it a “second-largest” lake depend on the geographical scope and area measure; the salinity gradient and sea connection are more precise identifiers."]}],"markdown":"# Kazhuveli Bird Sanctuary\n\n**Location:** Villupuram district, north of Puducherry · **Designation:** 16 January 2024 · **Registered Area:** 5,151.6 ha\n\n- **Type:** Large **brackish-to-fresh coastal wetland**, protected as **Kazhuveli Bird Sanctuary** in 2021.\n- **Sea Connection:** Connected northward to the Bay of Bengal through **Uppukalli Creek**; seawater entry during tides or cyclones produces a generally saltier north and fresher southern basin.\n- **Ecology:** The salinity gradient and wetland vegetation support fish movement, spawning and diverse waterbirds; nesting trees support **spot-billed pelican [NT]**.\n- **Wildlife:** Recorded **greater spotted eagle [VU]**, **eastern imperial eagle [VU]** and **river tern [VU]** illustrate raptor and aquatic-bird associations.\n- **Distinction:** The Ramsar area is **5,151.6 ha**. Descriptions calling it a “second-largest” lake depend on the geographical scope and area measure; the salinity gradient and sea connection are more precise identifiers.\n","species":["spot-billed pelican","greater spotted eagle","eastern imperial eagle","river tern"]},"2479":{"name":"Koonthankulam Bird Sanctuary","state":"Tamil Nadu","sections":[{"heading":"Location And Designation","facts":["**Location:** Tirunelveli district · **Designation:** 8 November 2021 · **Registered Area:** 72 ha"]},{"heading":"Type","facts":["Irrigation tanks and associated village habitat, connected by traditional canals and supplied by runoff and rivers originating in the **Western Ghats**."]},{"heading":"Wildlife","facts":["A major breeding landscape for colonial waterbirds, notably **spot-billed pelican [NT]** and **oriental darter [LC]**, with **northern pintail [LC]** and other seasonal visitors."]},{"heading":"Community Conservation","facts":["Birds nest in and around the village; local protection links breeding success with farming and the nutrient value of droppings."]},{"heading":"Functions","facts":["Irrigation, seasonal flood storage, bird breeding and cultural heritage; nearby agricultural habitat is part of the functional landscape."]},{"heading":"Pressures","facts":["Encroachment, sewage, land-use change and disturbance affect water and nesting opportunities. Migratory visitors and locally breeding resident birds should not be assigned one uniform seasonal pattern."]}],"markdown":"# Koonthankulam Bird Sanctuary\n\n**Location:** Tirunelveli district · **Designation:** 8 November 2021 · **Registered Area:** 72 ha\n\n- **Type:** Irrigation tanks and associated village habitat, connected by traditional canals and supplied by runoff and rivers originating in the **Western Ghats**.\n- **Wildlife:** A major breeding landscape for colonial waterbirds, notably **spot-billed pelican [NT]** and **oriental darter [LC]**, with **northern pintail [LC]** and other seasonal visitors.\n- **Community Conservation:** Birds nest in and around the village; local protection links breeding success with farming and the nutrient value of droppings.\n- **Functions:** Irrigation, seasonal flood storage, bird breeding and cultural heritage; nearby agricultural habitat is part of the functional landscape.\n- **Pressures:** Encroachment, sewage, land-use change and disturbance affect water and nesting opportunities. Migratory visitors and locally breeding resident birds should not be assigned one uniform seasonal pattern.\n","species":["spot-billed pelican","oriental darter","northern pintail"]},"2538":{"name":"Longwood Shola Reserve Forest","state":"Tamil Nadu","sections":[{"heading":"Location And Designation","facts":["**Location:** Kotagiri, Nilgiris district · **Designation:** 24 May 2023 · **Registered Area:** 116 ha"]},{"heading":"Type","facts":["**Montane shola forest with intermittent freshwater marshes and streams**, not a large open lake; a Ramsar site may be a forested wetland."]},{"heading":"Landscape","facts":["Sholas are patches of southern Indian montane evergreen forest in a grassland mosaic. The wetland helps retain and regulate water in the highland catchment."]},{"heading":"Wildlife","facts":["Western Ghats endemic birds include **Nilgiri laughingthrush [NT]**, **Nilgiri sholakili [NT]** and **Nilgiri woodpigeon [LC]**; **Wight’s cinnamon [EN]** is a noteworthy threatened tree."]},{"heading":"Conservation","facts":["Endemism concerns restricted geographic range, not merely rarity. Fragmentation can isolate specialized montane populations even when some tree cover remains."]},{"heading":"Pressures","facts":["Encroachment, invasive vegetation and deforestation threaten the forest–stream–marsh system; local residents participate in protection."]}],"markdown":"# Longwood Shola Reserve Forest\n\n**Location:** Kotagiri, Nilgiris district · **Designation:** 24 May 2023 · **Registered Area:** 116 ha\n\n- **Type:** **Montane shola forest with intermittent freshwater marshes and streams**, not a large open lake; a Ramsar site may be a forested wetland.\n- **Landscape:** Sholas are patches of southern Indian montane evergreen forest in a grassland mosaic. The wetland helps retain and regulate water in the highland catchment.\n- **Wildlife:** Western Ghats endemic birds include **Nilgiri laughingthrush [NT]**, **Nilgiri sholakili [NT]** and **Nilgiri woodpigeon [LC]**; **Wight’s cinnamon [EN]** is a noteworthy threatened tree.\n- **Conservation:** Endemism concerns restricted geographic range, not merely rarity. Fragmentation can isolate specialized montane populations even when some tree cover remains.\n- **Pressures:** Encroachment, invasive vegetation and deforestation threaten the forest–stream–marsh system; local residents participate in protection.\n","species":["nilgiri laughingthrush","nilgiri sholakili","nilgiri woodpigeon","wight’s cinnamon"]},"2549":{"name":"Nanjarayan Bird Sanctuary","state":"Tamil Nadu","sections":[{"heading":"Location And Designation","facts":["**Location:** Tiruppur district, Neruperichal–Sarkar Periyapalayam · **Designation:** 16 January 2024 · **Registered Area:** 125.9 ha"]},{"heading":"Type","facts":["Human-made **freshwater lake**, historically associated with King Nanjarayan; protected as a Bird Sanctuary in **2022**."]},{"heading":"Water Connections","facts":["Water levels respond to rainfall, catchment runoff and the **Nallar River**; excess water can be diverted for irrigation."]},{"heading":"Wildlife","facts":["**Babul [LC]** on bunds provides nesting and roosting habitat for **oriental darter [LC]** and **Indian cormorant [LC]**; **Indian flapshell turtle [VU]** uses suitable banks and wetland margins."]},{"heading":"Functions","facts":["Bird habitat, local agriculture and water storage; community groups participate with the forest department in management."]},{"heading":"Distinction","facts":["**Nanjarayan—Tiruppur**; **Vellode—Erode**; **Karaivetti—Ariyalur**. District–site associations distinguish these inland Tamil Nadu tanks."]}],"markdown":"# Nanjarayan Bird Sanctuary\n\n**Location:** Tiruppur district, Neruperichal–Sarkar Periyapalayam · **Designation:** 16 January 2024 · **Registered Area:** 125.9 ha\n\n- **Type:** Human-made **freshwater lake**, historically associated with King Nanjarayan; protected as a Bird Sanctuary in **2022**.\n- **Water Connections:** Water levels respond to rainfall, catchment runoff and the **Nallar River**; excess water can be diverted for irrigation.\n- **Wildlife:** **Babul [LC]** on bunds provides nesting and roosting habitat for **oriental darter [LC]** and **Indian cormorant [LC]**; **Indian flapshell turtle [VU]** uses suitable banks and wetland margins.\n- **Functions:** Bird habitat, local agriculture and water storage; community groups participate with the forest department in management.\n- **Distinction:** **Nanjarayan—Tiruppur**; **Vellode—Erode**; **Karaivetti—Ariyalur**. District–site associations distinguish these inland Tamil Nadu tanks.\n","species":["babul","oriental darter","indian cormorant","indian flapshell turtle"]},"2481":{"name":"Pallikaranai Marsh Reserve Forest","state":"Tamil Nadu","sections":[{"heading":"Location And Designation","facts":["**Location:** Southern Chennai, extending into the Chengalpattu landscape · **Designation:** 8 April 2022 · **Registered Area:** 1,247.5 ha"]},{"heading":"Type","facts":["**Freshwater marsh with partly saline influence**, not a deep lake or a mangrove forest; an urban flood-storage system."]},{"heading":"Drainage","facts":["Connects to coastal drainage through **Okkiyam Maduvu and the Kovalam Creek system**, with the Buckingham Canal along its eastern side; the marsh’s function depends on maintaining outlets as well as incoming drainage."]},{"heading":"Wildlife","facts":["Supports diverse fish, amphibians, reptiles and waterbirds, including **glossy ibis [LC]**, **grey-headed lapwing [LC]** and **pheasant-tailed jacana [LC]**."]},{"heading":"Mechanism","facts":["The marsh stores stormwater and releases it gradually; filling or narrowing it can increase flood peaks elsewhere in the urban catchment."]},{"heading":"Pressures","facts":["Urban encroachment, solid waste, sewage, roads, fragmented drainage and invasive plants threaten ecological character. The **Reserve Forest** designation and Ramsar designation have different legal origins."]}],"markdown":"# Pallikaranai Marsh Reserve Forest\n\n**Location:** Southern Chennai, extending into the Chengalpattu landscape · **Designation:** 8 April 2022 · **Registered Area:** 1,247.5 ha\n\n- **Type:** **Freshwater marsh with partly saline influence**, not a deep lake or a mangrove forest; an urban flood-storage system.\n- **Drainage:** Connects to coastal drainage through **Okkiyam Maduvu and the Kovalam Creek system**, with the Buckingham Canal along its eastern side; the marsh’s function depends on maintaining outlets as well as incoming drainage.\n- **Wildlife:** Supports diverse fish, amphibians, reptiles and waterbirds, including **glossy ibis [LC]**, **grey-headed lapwing [LC]** and **pheasant-tailed jacana [LC]**.\n- **Mechanism:** The marsh stores stormwater and releases it gradually; filling or narrowing it can increase flood peaks elsewhere in the urban catchment.\n- **Pressures:** Urban encroachment, solid waste, sewage, roads, fragmented drainage and invasive plants threaten ecological character. The **Reserve Forest** designation and Ramsar designation have different legal origins.\n","species":["glossy ibis","grey-headed lapwing","pheasant-tailed jacana"]},"2482":{"name":"Pichavaram Mangrove","state":"Tamil Nadu","sections":[{"heading":"Location And Designation","facts":["**Location:** Cuddalore district, near Chidambaram · **Designation:** 8 April 2022 · **Registered Area:** 1,478.6 ha"]},{"heading":"Type And Rivers","facts":["**Tidal mangrove wetland between the Vellar and Coleroon/Kollidam estuaries**, with intertidal channels, mudflats and littoral forest."]},{"heading":"Mechanisms","facts":["Salt tolerance, sediment trapping, aerial-root adaptations and sheltered nursery waters explain mangrove ecosystem function; mangroves are not seagrasses."]},{"heading":"Wildlife And Livelihoods","facts":["Provides nursery habitat for fish, prawns and crabs and supports artisanal fisheries; **olive ridley turtle [VU]** is recorded in the associated coastal landscape."]},{"heading":"Culture","facts":["The mangrove tree **Tillai [LC]** has cultural significance in the Chidambaram region; its latex is irritant/toxic, so a cultural association is not evidence of edibility."]},{"heading":"Distinction And Pressure","facts":["**Pichavaram—Vellar/Kollidam**; **Bhitarkanika—Brahmani/Baitarani**. Altered tidal exchange, reduced freshwater supply, cutting and pollution affect these systems; they are separate mangrove regions."]}],"markdown":"# Pichavaram Mangrove\n\n**Location:** Cuddalore district, near Chidambaram · **Designation:** 8 April 2022 · **Registered Area:** 1,478.6 ha\n\n- **Type And Rivers:** **Tidal mangrove wetland between the Vellar and Coleroon/Kollidam estuaries**, with intertidal channels, mudflats and littoral forest.\n- **Mechanisms:** Salt tolerance, sediment trapping, aerial-root adaptations and sheltered nursery waters explain mangrove ecosystem function; mangroves are not seagrasses.\n- **Wildlife And Livelihoods:** Provides nursery habitat for fish, prawns and crabs and supports artisanal fisheries; **olive ridley turtle [VU]** is recorded in the associated coastal landscape.\n- **Culture:** The mangrove tree **Tillai [LC]** has cultural significance in the Chidambaram region; its latex is irritant/toxic, so a cultural association is not evidence of edibility.\n- **Distinction And Pressure:** **Pichavaram—Vellar/Kollidam**; **Bhitarkanika—Brahmani/Baitarani**. Altered tidal exchange, reduced freshwater supply, cutting and pollution affect these systems; they are separate mangrove regions.\n","species":["olive ridley turtle","tillai"]},"1210":{"name":"Point Calimere Wildlife and Bird Sanctuary","state":"Tamil Nadu","sections":[{"heading":"Location And Designation","facts":["**Location:** Kodikkarai/Point Calimere, Nagapattinam coast · **Designation:** 19 August 2002 · **Registered Area:** 38,500 ha"]},{"heading":"Type","facts":["Coastal mosaic of **salt marshes, mudflats, saline lagoons, mangroves, sand bars and salt-working areas**; located at the southeastern edge of the Cauvery delta near the Palk Strait."]},{"heading":"Wildlife","facts":["Feeding and staging habitat for waders, **greater flamingo [LC]** and **lesser flamingo [NT]**. The adjoining dry evergreen/scrub landscape is associated with **blackbuck [LC]**."]},{"heading":"Ecological Connections","facts":["Fish, prawn and crab nursery habitats depend on the mixture of seawater exchange and freshwater inflow; changing salinity can reorganize the food web."]},{"heading":"Pressures","facts":["Expansion of salt works, reduced freshwater inflow, fuelwood extraction and invasive thorny vegetation can alter both wetland and terrestrial habitats."]},{"heading":"Boundary Distinction","facts":["The Ramsar site is a broader coastal wetland complex; it should not be equated automatically with only the land area of the wildlife sanctuary."]}],"markdown":"# Point Calimere Wildlife and Bird Sanctuary\n\n**Location:** Kodikkarai/Point Calimere, Nagapattinam coast · **Designation:** 19 August 2002 · **Registered Area:** 38,500 ha\n\n- **Type:** Coastal mosaic of **salt marshes, mudflats, saline lagoons, mangroves, sand bars and salt-working areas**; located at the southeastern edge of the Cauvery delta near the Palk Strait.\n- **Wildlife:** Feeding and staging habitat for waders, **greater flamingo [LC]** and **lesser flamingo [NT]**. The adjoining dry evergreen/scrub landscape is associated with **blackbuck [LC]**.\n- **Ecological Connections:** Fish, prawn and crab nursery habitats depend on the mixture of seawater exchange and freshwater inflow; changing salinity can reorganize the food web.\n- **Pressures:** Expansion of salt works, reduced freshwater inflow, fuelwood extraction and invasive thorny vegetation can alter both wetland and terrestrial habitats.\n- **Boundary Distinction:** The Ramsar site is a broader coastal wetland complex; it should not be equated automatically with only the land area of the wildlife sanctuary.\n","species":["greater flamingo","lesser flamingo","blackbuck"]},"2561":{"name":"Sakkarakottai Bird Sanctuary","state":"Tamil Nadu","sections":[{"heading":"Location And Designation","facts":["**Location:** Ramanathapuram district · **Designation:** 15 July 2024 · **Registered Area:** 230.5 ha"]},{"heading":"Type","facts":["**Peri-urban freshwater tank wetland**, protected as **Sakkarakottai Bird Sanctuary** in **2012**."]},{"heading":"Hydrology","facts":["Retains runoff, supports groundwater replenishment, traps sediment and buffers floods and heavy rainfall."]},{"heading":"Wildlife","facts":["Nesting **babul [LC]** supports colonial birds including **spot-billed pelican [NT]**; marsh margins also support reptiles, amphibians and invertebrates."]},{"heading":"Community Link","facts":["Nutrient-enriched water from bird droppings is used in nearby fields, helping sustain local support for bird conservation."]},{"heading":"Distinction","facts":["A separate Ramsar site from **Therthangal, Chitrangudi and Kanjirankulam**, all of which are also in Ramanathapuram district. Its Ramsar date is **15 July 2024**, not the announcement year alone."]}],"markdown":"# Sakkarakottai Bird Sanctuary\n\n**Location:** Ramanathapuram district · **Designation:** 15 July 2024 · **Registered Area:** 230.5 ha\n\n- **Type:** **Peri-urban freshwater tank wetland**, protected as **Sakkarakottai Bird Sanctuary** in **2012**.\n- **Hydrology:** Retains runoff, supports groundwater replenishment, traps sediment and buffers floods and heavy rainfall.\n- **Wildlife:** Nesting **babul [LC]** supports colonial birds including **spot-billed pelican [NT]**; marsh margins also support reptiles, amphibians and invertebrates.\n- **Community Link:** Nutrient-enriched water from bird droppings is used in nearby fields, helping sustain local support for bird conservation.\n- **Distinction:** A separate Ramsar site from **Therthangal, Chitrangudi and Kanjirankulam**, all of which are also in Ramanathapuram district. Its Ramsar date is **15 July 2024**, not the announcement year alone.\n","species":["babul","spot-billed pelican"]},"2492":{"name":"Suchindram Theroor Wetland Complex","state":"Tamil Nadu","sections":[{"heading":"Location And Designation","facts":["**Location:** Kanniyakumari district · **Designation:** 8 April 2022 · **Registered Area:** 94.2 ha"]},{"heading":"Components","facts":["**Suchindram and Theroor**, two irrigation-tank wetlands within the **Suchindram–Theroor–Manakudi Conservation Reserve** landscape."]},{"heading":"Water Connections","facts":["Part of the **Kodaiyar/Kodayar drainage and reservoir–canal irrigation network**, associated with reservoirs such as Pechiparai and Perunchani."]},{"heading":"Ecology","facts":["Seasonal tank water, agricultural land and nesting vegetation provide feeding and staging habitat at the southern end of the **Central Asian Flyway**."]},{"heading":"Functions","facts":["Traditional irrigation, local livelihoods, bird habitat and flood moderation; the functional wetland is tied to a much larger network of ponds and channels."]},{"heading":"Distinction","facts":["One Ramsar designation covers the complex; **Manakudi’s wider coastal conservation landscape** should not be assumed to have the same boundary as these two Ramsar tanks."]}],"markdown":"# Suchindram Theroor Wetland Complex\n\n**Location:** Kanniyakumari district · **Designation:** 8 April 2022 · **Registered Area:** 94.2 ha\n\n- **Components:** **Suchindram and Theroor**, two irrigation-tank wetlands within the **Suchindram–Theroor–Manakudi Conservation Reserve** landscape.\n- **Water Connections:** Part of the **Kodaiyar/Kodayar drainage and reservoir–canal irrigation network**, associated with reservoirs such as Pechiparai and Perunchani.\n- **Ecology:** Seasonal tank water, agricultural land and nesting vegetation provide feeding and staging habitat at the southern end of the **Central Asian Flyway**.\n- **Functions:** Traditional irrigation, local livelihoods, bird habitat and flood moderation; the functional wetland is tied to a much larger network of ponds and channels.\n- **Distinction:** One Ramsar designation covers the complex; **Manakudi’s wider coastal conservation landscape** should not be assumed to have the same boundary as these two Ramsar tanks.\n","species":[]},"2562":{"name":"Therthangal Bird Sanctuary","state":"Tamil Nadu","sections":[{"heading":"Location And Designation","facts":["**Location:** Therthangal village, Ramanathapuram district · **Designation:** 15 July 2024 · **Registered Area:** 29.3 ha"]},{"heading":"Type","facts":["Marshy **freshwater irrigation lake**, with rainy-season river inflows and nesting trees planted by the forest department."]},{"heading":"Protection","facts":["Declared a **Bird Sanctuary in 2010**; Ramsar designation is a later, separate recognition."]},{"heading":"Wildlife","facts":["Recorded **Egyptian vulture [EN]**, **Indian spotted eagle [NT]** and colonial waterbirds using **babul [LC]** nesting habitat."]},{"heading":"Functions","facts":["Irrigation for adjacent fields, aquatic habitat, recreation and tourism; both seasonal water supply and nesting structure determine habitat quality."]},{"heading":"Distinction","facts":["**Indian spotted eagle and greater spotted eagle are different species**, with different current IUCN categories. The protected-area declaration year and **15 July 2024 Ramsar designation** must not be merged."]}],"markdown":"# Therthangal Bird Sanctuary\n\n**Location:** Therthangal village, Ramanathapuram district · **Designation:** 15 July 2024 · **Registered Area:** 29.3 ha\n\n- **Type:** Marshy **freshwater irrigation lake**, with rainy-season river inflows and nesting trees planted by the forest department.\n- **Protection:** Declared a **Bird Sanctuary in 2010**; Ramsar designation is a later, separate recognition.\n- **Wildlife:** Recorded **Egyptian vulture [EN]**, **Indian spotted eagle [NT]** and colonial waterbirds using **babul [LC]** nesting habitat.\n- **Functions:** Irrigation for adjacent fields, aquatic habitat, recreation and tourism; both seasonal water supply and nesting structure determine habitat quality.\n- **Distinction:** **Indian spotted eagle and greater spotted eagle are different species**, with different current IUCN categories. The protected-area declaration year and **15 July 2024 Ramsar designation** must not be merged.\n","species":["egyptian vulture","indian spotted eagle","babul"]},"2476":{"name":"Udhayamarthandapuram Bird Sanctuary","state":"Tamil Nadu","sections":[{"heading":"Location And Designation","facts":["**Location:** Tiruvarur district · **Designation:** 8 April 2022 · **Registered Area:** 43.8 ha"]},{"heading":"Type","facts":["Irrigation-tank wetland connected to an old canal network; supply from the **Mettur reservoir system reaches it through the Koraiyar canal**."]},{"heading":"Wildlife","facts":["Important for **oriental darter [LC]**, **black-headed ibis [LC]**, **northern pintail [LC]** and **garganey [LC]**, among other waterbirds."]},{"heading":"Hydrology","facts":["Stores wet-season water, sustains dry-season surface flows, recharges groundwater and supplies surrounding tanks and fields."]},{"heading":"Connectivity","facts":["Its ecology depends on the wider **Cauvery irrigation network**, not just rainfall falling directly on the tank."]},{"heading":"Pressures","facts":["Disturbance, unsustainable harvesting and changes in inflow or water level affect feeding and nesting habitat. “Irrigation tank” and “bird sanctuary” describe compatible functions, not mutually exclusive classifications."]}],"markdown":"# Udhayamarthandapuram Bird Sanctuary\n\n**Location:** Tiruvarur district · **Designation:** 8 April 2022 · **Registered Area:** 43.8 ha\n\n- **Type:** Irrigation-tank wetland connected to an old canal network; supply from the **Mettur reservoir system reaches it through the Koraiyar canal**.\n- **Wildlife:** Important for **oriental darter [LC]**, **black-headed ibis [LC]**, **northern pintail [LC]** and **garganey [LC]**, among other waterbirds.\n- **Hydrology:** Stores wet-season water, sustains dry-season surface flows, recharges groundwater and supplies surrounding tanks and fields.\n- **Connectivity:** Its ecology depends on the wider **Cauvery irrigation network**, not just rainfall falling directly on the tank.\n- **Pressures:** Disturbance, unsustainable harvesting and changes in inflow or water level affect feeding and nesting habitat. “Irrigation tank” and “bird sanctuary” describe compatible functions, not mutually exclusive classifications.\n","species":["oriental darter","black-headed ibis","northern pintail","garganey"]},"2493":{"name":"Vaduvur Bird Sanctuary","state":"Tamil Nadu","sections":[{"heading":"Location And Designation","facts":["**Location:** Tiruvarur district, Thanjavur–Mannargudi corridor · **Designation:** 8 April 2022 · **Registered Area:** 112.6 ha"]},{"heading":"Type","facts":["Irrigation-tank wetland linked through traditional canals to the **Mettur/Cauvery reservoir system**; protected as a Bird Sanctuary."]},{"heading":"Wildlife","facts":["Aquatic and emergent vegetation support **spot-billed pelican [NT]**, **black-headed ibis [LC]**, **Eurasian wigeon [LC]** and **northern pintail [LC]**."]},{"heading":"Mechanism","facts":["Rooted-floating and submerged vegetation create feeding niches; seasonal inflow and drawdown determine which niches remain available."]},{"heading":"Functions","facts":["Irrigation, drought buffering and storage of floodwater within a connected tank network."]},{"heading":"Pressures And Contrast","facts":["Excess water abstraction, unsuitable fishing, invasive species and urban pressure alter habitat. **Vaduvur and Udhayamarthandapuram are different Tiruvarur Ramsar sites**, despite shared dependence on canal irrigation."]}],"markdown":"# Vaduvur Bird Sanctuary\n\n**Location:** Tiruvarur district, Thanjavur–Mannargudi corridor · **Designation:** 8 April 2022 · **Registered Area:** 112.6 ha\n\n- **Type:** Irrigation-tank wetland linked through traditional canals to the **Mettur/Cauvery reservoir system**; protected as a Bird Sanctuary.\n- **Wildlife:** Aquatic and emergent vegetation support **spot-billed pelican [NT]**, **black-headed ibis [LC]**, **Eurasian wigeon [LC]** and **northern pintail [LC]**.\n- **Mechanism:** Rooted-floating and submerged vegetation create feeding niches; seasonal inflow and drawdown determine which niches remain available.\n- **Functions:** Irrigation, drought buffering and storage of floodwater within a connected tank network.\n- **Pressures And Contrast:** Excess water abstraction, unsuitable fishing, invasive species and urban pressure alter habitat. **Vaduvur and Udhayamarthandapuram are different Tiruvarur Ramsar sites**, despite shared dependence on canal irrigation.\n","species":["spot-billed pelican","black-headed ibis","eurasian wigeon","northern pintail"]},"2477":{"name":"Vedanthangal Bird Sanctuary","state":"Tamil Nadu","sections":[{"heading":"Location And Designation","facts":["**Location:** Chengalpattu district, Vedanthangal village · **Designation:** 8 April 2022 · **Registered Area:** 40.3 ha"]},{"heading":"Type","facts":["Small **irrigation tank with nesting trees**, surrounded by agricultural land and low rocky hills; a long-established community-protected bird landscape."]},{"heading":"Wildlife","facts":["Colonial nesting birds include **painted stork [LC]**, **black-headed ibis [LC]**, **Eurasian spoonbill [LC]** and **black-crowned night heron [LC]**."]},{"heading":"Human–Bird Relationship","facts":["Farmers value nutrient-enriched irrigation water from bird droppings; maintaining nesting trees and water beneath them helps sustain the bird colony."]},{"heading":"Functions","facts":["Breeding habitat, groundwater recharge, nutrient cycling, education and tourism."]},{"heading":"Pressures And Contrast","facts":["Housing, disturbance and unsustainable aquatic-resource use can degrade the tank. **Vedanthangal and Karikili are separate Ramsar sites**, although both belong to the Chengalpattu-region tank landscape."]}],"markdown":"# Vedanthangal Bird Sanctuary\n\n**Location:** Chengalpattu district, Vedanthangal village · **Designation:** 8 April 2022 · **Registered Area:** 40.3 ha\n\n- **Type:** Small **irrigation tank with nesting trees**, surrounded by agricultural land and low rocky hills; a long-established community-protected bird landscape.\n- **Wildlife:** Colonial nesting birds include **painted stork [LC]**, **black-headed ibis [LC]**, **Eurasian spoonbill [LC]** and **black-crowned night heron [LC]**.\n- **Human–Bird Relationship:** Farmers value nutrient-enriched irrigation water from bird droppings; maintaining nesting trees and water beneath them helps sustain the bird colony.\n- **Functions:** Breeding habitat, groundwater recharge, nutrient cycling, education and tourism.\n- **Pressures And Contrast:** Housing, disturbance and unsustainable aquatic-resource use can degrade the tank. **Vedanthangal and Karikili are separate Ramsar sites**, although both belong to the Chengalpattu-region tank landscape.\n","species":["painted stork","black-headed ibis","eurasian spoonbill","black-crowned night heron"]},"2475":{"name":"Vellode Bird Sanctuary","state":"Tamil Nadu","sections":[{"heading":"Location And Designation","facts":["**Location:** Erode district · **Designation:** 8 April 2022 · **Registered Area:** 77.2 ha"]},{"heading":"Type","facts":["Human-made **freshwater tank** in an agricultural landscape; protected as **Vellode Bird Sanctuary**."]},{"heading":"Wildlife","facts":["Provides staging, feeding and nesting habitat for resident and migratory birds, including **river tern [VU]**, **oriental darter [LC]** and **painted stork [LC]**."]},{"heading":"Ecological Link","facts":["Aquatic organisms and nearby fields provide food; bird droppings transfer nutrients into water later used in agriculture."]},{"heading":"Functions","facts":["Local water supply, fisheries, waterbird habitat and nutrient cycling; benefits depend on water quality as well as water quantity."]},{"heading":"Pressures And Contrast","facts":["Sewage, urban wastewater, land conversion and invasive plants threaten the tank. Nutrient inputs can aid production at low levels but cause eutrophication when excessive."]}],"markdown":"# Vellode Bird Sanctuary\n\n**Location:** Erode district · **Designation:** 8 April 2022 · **Registered Area:** 77.2 ha\n\n- **Type:** Human-made **freshwater tank** in an agricultural landscape; protected as **Vellode Bird Sanctuary**.\n- **Wildlife:** Provides staging, feeding and nesting habitat for resident and migratory birds, including **river tern [VU]**, **oriental darter [LC]** and **painted stork [LC]**.\n- **Ecological Link:** Aquatic organisms and nearby fields provide food; bird droppings transfer nutrients into water later used in agriculture.\n- **Functions:** Local water supply, fisheries, waterbird habitat and nutrient cycling; benefits depend on water quality as well as water quantity.\n- **Pressures And Contrast:** Sewage, urban wastewater, land conversion and invasive plants threaten the tank. Nutrient inputs can aid production at low levels but cause eutrophication when excessive.\n","species":["river tern","oriental darter","painted stork"]},"2474":{"name":"Vembannur Wetland Complex","state":"Tamil Nadu","sections":[{"heading":"Location And Designation","facts":["**Location:** Kanniyakumari district, near Nagercoil · **Designation:** 8 April 2022 · **Registered Area:** 19.7 ha"]},{"heading":"Type","facts":["Small **human-made freshwater irrigation tank**, a few kilometres inland near the southern tip of mainland India."]},{"heading":"Ecology","facts":["Seasonal water, aquatic plants and agricultural surroundings support feeding, resting and breeding waterbirds, including **spot-billed pelican [NT]** and **river tern [VU]**."]},{"heading":"Services","facts":["Supplies irrigation and other local water needs, supports fish production, stores floodwater and buffers seasonal water shortages."]},{"heading":"Pressures","facts":["Clearing vegetation, land conversion and solid-waste disposal affect habitat and water-storage space."]},{"heading":"Distinction","facts":["At **19.7 ha**, it is the **smallest registered Ramsar site in this 103-site inventory**. It is in **Tamil Nadu**; **Vembanad-Kol** is a much larger Kerala wetland complex."]}],"markdown":"# Vembannur Wetland Complex\n\n**Location:** Kanniyakumari district, near Nagercoil · **Designation:** 8 April 2022 · **Registered Area:** 19.7 ha\n\n- **Type:** Small **human-made freshwater irrigation tank**, a few kilometres inland near the southern tip of mainland India.\n- **Ecology:** Seasonal water, aquatic plants and agricultural surroundings support feeding, resting and breeding waterbirds, including **spot-billed pelican [NT]** and **river tern [VU]**.\n- **Services:** Supplies irrigation and other local water needs, supports fish production, stores floodwater and buffers seasonal water shortages.\n- **Pressures:** Clearing vegetation, land conversion and solid-waste disposal affect habitat and water-storage space.\n- **Distinction:** At **19.7 ha**, it is the **smallest registered Ramsar site in this 103-site inventory**. It is in **Tamil Nadu**; **Vembanad-Kol** is a much larger Kerala wetland complex.\n","species":["spot-billed pelican","river tern"]},"1572":{"name":"Rudrasagar Lake","state":"Tripura","sections":[{"heading":"Location And Designation","facts":["**Location:** Melaghar, Sepahijala district · **Designation:** 8 November 2005 · **Registered Area:** 240 ha"]},{"heading":"Type","facts":["Lowland **freshwater lake/sedimentation reservoir**, fed by perennial streams and connected downstream to the **Gomati/Gumti** river system."]},{"heading":"Hydrology","facts":["Monsoon inflow expands the wetland; storage moderates flooding and contributes to groundwater recharge. Catchment erosion raises the sediment load."]},{"heading":"Wildlife","facts":["Fish-rich habitat with aquatic vegetation; associated with the **three-striped roofed turtle [CR]**, a river-basin turtle threatened by exploitation and habitat alteration."]},{"heading":"Culture","facts":["**Neermahal**, the water palace, stands in the lake; tourism and cultural activity coexist with fishing and seasonal cultivation."]},{"heading":"Pressures","facts":["Catchment deforestation, siltation, conversion of seasonal wetland areas and unsustainable resource use affect ecological character. Sepahijala is the current district; “West Tripura” appears in older descriptions."]}],"markdown":"# Rudrasagar Lake\n\n**Location:** Melaghar, Sepahijala district · **Designation:** 8 November 2005 · **Registered Area:** 240 ha\n\n- **Type:** Lowland **freshwater lake/sedimentation reservoir**, fed by perennial streams and connected downstream to the **Gomati/Gumti** river system.\n- **Hydrology:** Monsoon inflow expands the wetland; storage moderates flooding and contributes to groundwater recharge. Catchment erosion raises the sediment load.\n- **Wildlife:** Fish-rich habitat with aquatic vegetation; associated with the **three-striped roofed turtle [CR]**, a river-basin turtle threatened by exploitation and habitat alteration.\n- **Culture:** **Neermahal**, the water palace, stands in the lake; tourism and cultural activity coexist with fishing and seasonal cultivation.\n- **Pressures:** Catchment deforestation, siltation, conversion of seasonal wetland areas and unsustainable resource use affect ecological character. Sepahijala is the current district; “West Tripura” appears in older descriptions.\n","species":["three-striped roofed turtle"]},"2465":{"name":"Bakhira Wildlife Sanctuary","state":"Uttar Pradesh","sections":[{"heading":"Location And Designation","facts":["**Location:** Sant Kabir Nagar district · **Designation:** 29 June 2021 · **Registered Area:** 2,894 ha"]},{"heading":"Type","facts":["Extensive natural **freshwater floodplain marsh** of eastern Uttar Pradesh, protected as **Bakhira Wildlife Sanctuary**."]},{"heading":"Wildlife","facts":["Wintering birds on the Central Asian Flyway include **common pochard [VU]** and **greater spotted eagle [VU]**; **swamp francolin [NT]** links wetland edges with tall wet grass habitat."]},{"heading":"Ecology","facts":["Marsh vegetation and shallow water support fish, invertebrates and bird food webs; wetland grass habitat is not interchangeable with unvegetated deep water."]},{"heading":"Human Functions","facts":["Aquatic food resources, nutrient cycling, recreation and livelihoods in the surrounding agricultural landscape."]},{"heading":"Pressures And Contrast","facts":["Loss of wetland vegetation, unsuitable water management and pollution can undermine these functions. **Bakhira—Sant Kabir Nagar**; **Kabartal—Begusarai, Bihar**."]}],"markdown":"# Bakhira Wildlife Sanctuary\n\n**Location:** Sant Kabir Nagar district · **Designation:** 29 June 2021 · **Registered Area:** 2,894 ha\n\n- **Type:** Extensive natural **freshwater floodplain marsh** of eastern Uttar Pradesh, protected as **Bakhira Wildlife Sanctuary**.\n- **Wildlife:** Wintering birds on the Central Asian Flyway include **common pochard [VU]** and **greater spotted eagle [VU]**; **swamp francolin [NT]** links wetland edges with tall wet grass habitat.\n- **Ecology:** Marsh vegetation and shallow water support fish, invertebrates and bird food webs; wetland grass habitat is not interchangeable with unvegetated deep water.\n- **Human Functions:** Aquatic food resources, nutrient cycling, recreation and livelihoods in the surrounding agricultural landscape.\n- **Pressures And Contrast:** Loss of wetland vegetation, unsuitable water management and pollution can undermine these functions. **Bakhira—Sant Kabir Nagar**; **Kabartal—Begusarai, Bihar**.\n","species":["common pochard","greater spotted eagle","swamp francolin"]},"2463":{"name":"Haiderpur Wetland","state":"Uttar Pradesh","sections":[{"heading":"Location And Designation","facts":["**Location:** Ganga floodplain near Bijnor and Muzaffarnagar · **Designation:** 13 April 2021 · **Registered Area:** 6,908 ha"]},{"heading":"Origin","facts":["Wetland formed following construction of the **Madhya Ganga/Bijnor barrage in 1984**, within **Hastinapur Wildlife Sanctuary**."]},{"heading":"Habitats","facts":["River, reservoir-influenced water, marshes, floodplain grasslands and seasonal inundation create habitat connectivity."]},{"heading":"Wildlife","facts":["Supports **gharial [CR]**, **Indian skimmer [EN]**, **black-bellied tern [EN]**, **hog deer [EN]**, **golden mahseer [EN]** and **swamp deer [VU]** in the site landscape."]},{"heading":"Seasonal Relationship","facts":["Flood-driven movements make connected refuge and grassland areas important for swamp deer; retaining water alone does not protect all parts of this habitat."]},{"heading":"Functions And Pressures","facts":["Water regulation, flood buffering, bird habitat and livelihoods; abrupt water-level change, disturbance and pollution can alter the wetland mosaic. It is separate from the **Upper Ganga Brijghat–Narora** designation."]}],"markdown":"# Haiderpur Wetland\n\n**Location:** Ganga floodplain near Bijnor and Muzaffarnagar · **Designation:** 13 April 2021 · **Registered Area:** 6,908 ha\n\n- **Origin:** Wetland formed following construction of the **Madhya Ganga/Bijnor barrage in 1984**, within **Hastinapur Wildlife Sanctuary**.\n- **Habitats:** River, reservoir-influenced water, marshes, floodplain grasslands and seasonal inundation create habitat connectivity.\n- **Wildlife:** Supports **gharial [CR]**, **Indian skimmer [EN]**, **black-bellied tern [EN]**, **hog deer [EN]**, **golden mahseer [EN]** and **swamp deer [VU]** in the site landscape.\n- **Seasonal Relationship:** Flood-driven movements make connected refuge and grassland areas important for swamp deer; retaining water alone does not protect all parts of this habitat.\n- **Functions And Pressures:** Water regulation, flood buffering, bird habitat and livelihoods; abrupt water-level change, disturbance and pollution can alter the wetland mosaic. It is separate from the **Upper Ganga Brijghat–Narora** designation.\n","species":["gharial","indian skimmer","black-bellied tern","hog deer","golden mahseer","swamp deer"]},"2595":{"name":"Jai Prakash Narayan Bird Sanctuary","state":"Uttar Pradesh","sections":[{"heading":"Location And Designation","facts":["**Location:** Ballia district, Bansdeeh–Ballia floodplain · **Designation:** 19 January 2026 · **Registered Area:** 3,432 ha"]},{"heading":"Name And Type","facts":["**Jai Prakash Narayan Bird Sanctuary**, associated with **Surha Tal**, is a freshwater wetland formed from a former **Ganga meander**."]},{"heading":"Water Connections","facts":["Receives water through multiple channels; marshes, seasonally flooded ground and rice fields form part of its functional landscape."]},{"heading":"Wildlife","facts":["Dry-season refuge for **common pochard [VU]** and **river tern [VU]**; fish-rich habitat attracts **fishing cat [VU]** and supports **Wallago attu [VU]**."]},{"heading":"Conservation","facts":["Seasonal fishing controls and prohibitions on destructive harvesting help sustain fish breeding and the food web."]},{"heading":"Distinction","facts":["**Surha Tal/Jai Prakash Narayan—Ballia** is not **Sur Sarovar/Keetham—Agra**. Its addition was announced as India’s hundredth Ramsar site in June 2026, but designation is dated **19 January 2026**."]}],"markdown":"# Jai Prakash Narayan Bird Sanctuary\n\n**Location:** Ballia district, Bansdeeh–Ballia floodplain · **Designation:** 19 January 2026 · **Registered Area:** 3,432 ha\n\n- **Name And Type:** **Jai Prakash Narayan Bird Sanctuary**, associated with **Surha Tal**, is a freshwater wetland formed from a former **Ganga meander**.\n- **Water Connections:** Receives water through multiple channels; marshes, seasonally flooded ground and rice fields form part of its functional landscape.\n- **Wildlife:** Dry-season refuge for **common pochard [VU]** and **river tern [VU]**; fish-rich habitat attracts **fishing cat [VU]** and supports **Wallago attu [VU]**.\n- **Conservation:** Seasonal fishing controls and prohibitions on destructive harvesting help sustain fish breeding and the food web.\n- **Distinction:** **Surha Tal/Jai Prakash Narayan—Ballia** is not **Sur Sarovar/Keetham—Agra**. Its addition was announced as India’s hundredth Ramsar site in June 2026, but designation is dated **19 January 2026**.\n","species":["common pochard","river tern","fishing cat","wallago attu"]},"2412":{"name":"Nawabganj Bird Sanctuary","state":"Uttar Pradesh","sections":[{"heading":"Location And Designation","facts":["**Location:** Unnao district, Lucknow–Kanpur corridor · **Designation:** 19 September 2019 · **Registered Area:** 224.6 ha"]},{"heading":"Name","facts":["**Nawabganj Bird Sanctuary**, also known as **Shaheed Chandra Shekhar Azad Bird Sanctuary**; these are aliases of one site."]},{"heading":"Type And Supply","facts":["Shallow freshwater marsh replenished by monsoon rainfall, with supplementary supply through the **Sarda canal system**."]},{"heading":"Wildlife","facts":["Resident and migrant birds include **Egyptian vulture [EN]**, **Pallas’s fish eagle [EN]** and **lesser adjutant [NT]**. Current categories need not match the labels in older site descriptions."]},{"heading":"Functions","facts":["Waterbird habitat, environmental education, recreation and the surrounding wooded–wetland mosaic support different ecological niches."]},{"heading":"Pressures","facts":["Invasive floating weeds can blanket open water; timber extraction and disturbance affect wooded nesting and roosting areas. Its canal supplement contrasts with wetlands relying almost entirely on rainfall."]}],"markdown":"# Nawabganj Bird Sanctuary\n\n**Location:** Unnao district, Lucknow–Kanpur corridor · **Designation:** 19 September 2019 · **Registered Area:** 224.6 ha\n\n- **Name:** **Nawabganj Bird Sanctuary**, also known as **Shaheed Chandra Shekhar Azad Bird Sanctuary**; these are aliases of one site.\n- **Type And Supply:** Shallow freshwater marsh replenished by monsoon rainfall, with supplementary supply through the **Sarda canal system**.\n- **Wildlife:** Resident and migrant birds include **Egyptian vulture [EN]**, **Pallas’s fish eagle [EN]** and **lesser adjutant [NT]**. Current categories need not match the labels in older site descriptions.\n- **Functions:** Waterbird habitat, environmental education, recreation and the surrounding wooded–wetland mosaic support different ecological niches.\n- **Pressures:** Invasive floating weeds can blanket open water; timber extraction and disturbance affect wooded nesting and roosting areas. Its canal supplement contrasts with wetlands relying almost entirely on rainfall.\n","species":["egyptian vulture","pallas’s fish eagle","lesser adjutant"]},"2416":{"name":"Parvati Arga Bird Sanctuary","state":"Uttar Pradesh","sections":[{"heading":"Location And Designation","facts":["**Location:** Gonda district · **Designation:** 2 December 2019 · **Registered Area:** 722 ha"]},{"heading":"Components","facts":["**Parvati and Arga**, two permanent freshwater **oxbow lakes**, together form one Ramsar site."]},{"heading":"Hydrology","facts":["Floodplain water storage and groundwater exchange help maintain local water regimes; protection must retain the functioning lake margins and connections."]},{"heading":"Wildlife","facts":["Important waterbird refuge with recorded **white-rumped vulture [CR]**, **Indian vulture [CR]** and **Egyptian vulture [EN]** in the broader site habitat."]},{"heading":"Culture And Use","facts":["Temples around the lakes contribute religious and recreational importance."]},{"heading":"Pressures","facts":["Invasive aquatic weeds, infrastructure and fragmentation can alter habitat. **Two lakes under one Ramsar designation** should not be counted as two separate Ramsar sites."]}],"markdown":"# Parvati Arga Bird Sanctuary\n\n**Location:** Gonda district · **Designation:** 2 December 2019 · **Registered Area:** 722 ha\n\n- **Components:** **Parvati and Arga**, two permanent freshwater **oxbow lakes**, together form one Ramsar site.\n- **Hydrology:** Floodplain water storage and groundwater exchange help maintain local water regimes; protection must retain the functioning lake margins and connections.\n- **Wildlife:** Important waterbird refuge with recorded **white-rumped vulture [CR]**, **Indian vulture [CR]** and **Egyptian vulture [EN]** in the broader site habitat.\n- **Culture And Use:** Temples around the lakes contribute religious and recreational importance.\n- **Pressures:** Invasive aquatic weeds, infrastructure and fragmentation can alter habitat. **Two lakes under one Ramsar designation** should not be counted as two separate Ramsar sites.\n","species":["white-rumped vulture","indian vulture","egyptian vulture"]},"2589":{"name":"Patna Bird Sanctuary","state":"Uttar Pradesh","sections":[{"heading":"Location And Designation","facts":["**Location:** Jalesar tehsil, Etah district · **Designation:** 4 December 2025 · **Registered Area:** 108.9 ha"]},{"heading":"Type","facts":["**Freshwater marsh–woodland–grassland mosaic** surrounded by agricultural land; protected as **Patna Bird Sanctuary**."]},{"heading":"Ecology","facts":["Habitat transitions support waterbirds and terrestrial species; recorded fauna include **mugger crocodile [VU]**."]},{"heading":"Functions","facts":["Bird feeding and resting habitat, religious visits and nature-based recreation; seasonal wetland condition influences use by migratory birds."]},{"heading":"Pressures And Management","facts":["Invasive vegetation, visitor pressure and disturbance require control; monitoring includes migratory birds and avian disease risks."]},{"heading":"Distinction","facts":["**Patna Bird Sanctuary is in Uttar Pradesh, not Patna in Bihar**. Its registered Ramsar designation date is **4 December 2025**; a later announcement does not change that date."]}],"markdown":"# Patna Bird Sanctuary\n\n**Location:** Jalesar tehsil, Etah district · **Designation:** 4 December 2025 · **Registered Area:** 108.9 ha\n\n- **Type:** **Freshwater marsh–woodland–grassland mosaic** surrounded by agricultural land; protected as **Patna Bird Sanctuary**.\n- **Ecology:** Habitat transitions support waterbirds and terrestrial species; recorded fauna include **mugger crocodile [VU]**.\n- **Functions:** Bird feeding and resting habitat, religious visits and nature-based recreation; seasonal wetland condition influences use by migratory birds.\n- **Pressures And Management:** Invasive vegetation, visitor pressure and disturbance require control; monitoring includes migratory birds and avian disease risks.\n- **Distinction:** **Patna Bird Sanctuary is in Uttar Pradesh, not Patna in Bihar**. Its registered Ramsar designation date is **4 December 2025**; a later announcement does not change that date.\n","species":["mugger crocodile"]},"2413":{"name":"Saman Bird Sanctuary","state":"Uttar Pradesh","sections":[{"heading":"Location And Designation","facts":["**Location:** Mainpuri district · **Designation:** 2 December 2019 · **Registered Area:** 526.3 ha"]},{"heading":"Type","facts":["Seasonal **oxbow lake** on the Ganga floodplain, heavily dependent on the July–August southwest monsoon."]},{"heading":"Wildlife","facts":["Major wintering refuge for **greylag goose [LC]**; also supports **sarus crane [VU]** and **greater spotted eagle [VU]**."]},{"heading":"Ecology","facts":["Monsoon expansion, winter shallows and exposed margins produce different feeding conditions through the year. Floodplain setting does not mean an uninterrupted permanent river channel."]},{"heading":"Functions And Pressures","facts":["Water for agriculture, waterbird habitat and recreation; settlement encroachment, salinization and changes in seasonal water supply are key concerns."]},{"heading":"Distinction","facts":["**Saman Bird Sanctuary and Sauj Jheel are separate Ramsar sites in Mainpuri**, linked ecologically through the wider wetland network."]}],"markdown":"# Saman Bird Sanctuary\n\n**Location:** Mainpuri district · **Designation:** 2 December 2019 · **Registered Area:** 526.3 ha\n\n- **Type:** Seasonal **oxbow lake** on the Ganga floodplain, heavily dependent on the July–August southwest monsoon.\n- **Wildlife:** Major wintering refuge for **greylag goose [LC]**; also supports **sarus crane [VU]** and **greater spotted eagle [VU]**.\n- **Ecology:** Monsoon expansion, winter shallows and exposed margins produce different feeding conditions through the year. Floodplain setting does not mean an uninterrupted permanent river channel.\n- **Functions And Pressures:** Water for agriculture, waterbird habitat and recreation; settlement encroachment, salinization and changes in seasonal water supply are key concerns.\n- **Distinction:** **Saman Bird Sanctuary and Sauj Jheel are separate Ramsar sites in Mainpuri**, linked ecologically through the wider wetland network.\n","species":["greylag goose","sarus crane","greater spotted eagle"]},"2415":{"name":"Samaspur Bird Sanctuary","state":"Uttar Pradesh","sections":[{"heading":"Location And Designation","facts":["**Location:** Raebareli district · **Designation:** 3 October 2019 · **Registered Area:** 799.4 ha"]},{"heading":"Components","facts":["**Six connected lakes** form a perennial lowland marsh system; monsoon recharge sustains the network."]},{"heading":"Wildlife","facts":["Important for **common pochard [VU]**, **Egyptian vulture [EN]** and **Pallas’s fish eagle [EN]**, with resident and wintering waterbirds using varied depths and vegetation."]},{"heading":"Connectivity","facts":["Flood-season river connections allow some fish to enter the wetland, linking fish life cycles with inundation rather than only the permanent pool."]},{"heading":"Services","facts":["Supports fisheries, aquatic-resource supply, fodder and waterbird habitat."]},{"heading":"Pressures","facts":["Invasive plants can change open-water and feeding conditions. The sanctuary’s connected-lake structure distinguishes it from a single isolated tank or a flowing-river Ramsar site."]}],"markdown":"# Samaspur Bird Sanctuary\n\n**Location:** Raebareli district · **Designation:** 3 October 2019 · **Registered Area:** 799.4 ha\n\n- **Components:** **Six connected lakes** form a perennial lowland marsh system; monsoon recharge sustains the network.\n- **Wildlife:** Important for **common pochard [VU]**, **Egyptian vulture [EN]** and **Pallas’s fish eagle [EN]**, with resident and wintering waterbirds using varied depths and vegetation.\n- **Connectivity:** Flood-season river connections allow some fish to enter the wetland, linking fish life cycles with inundation rather than only the permanent pool.\n- **Services:** Supports fisheries, aquatic-resource supply, fodder and waterbird habitat.\n- **Pressures:** Invasive plants can change open-water and feeding conditions. The sanctuary’s connected-lake structure distinguishes it from a single isolated tank or a flowing-river Ramsar site.\n","species":["common pochard","egyptian vulture","pallas’s fish eagle"]},"2409":{"name":"Sandi Bird Sanctuary","state":"Uttar Pradesh","sections":[{"heading":"Location And Designation","facts":["**Location:** Hardoi district · **Designation:** 26 September 2019 · **Registered Area:** 308.5 ha"]},{"heading":"Type And Water","facts":["Natural **freshwater marsh**, primarily replenished by southwest-monsoon rainfall and local runoff; a representative Indo-Gangetic wetland."]},{"heading":"Bird Habitat","facts":["Productive shallow water supports wintering ducks and resident **sarus crane [VU]**. **Common teal [LC]**, **red-crested pochard [LC]** and **ferruginous duck [NT]** are significant recorded waterbirds."]},{"heading":"International Importance","facts":["Published counts demonstrate the importance of population thresholds as well as species diversity; a site can qualify through regularly supporting a substantial share of one waterbird population."]},{"heading":"Human Use","facts":["Nearby agriculture uses fodder and other wetland resources; recreation is another use."]},{"heading":"Pressures And Distinction","facts":["Severe drought dried the site in **2014–2015**, illustrating that natural rain dependence can cause abrupt habitat loss. **Sandi—Hardoi** is distinct from **Saman—Mainpuri** and **Samaspur—Raebareli**."]}],"markdown":"# Sandi Bird Sanctuary\n\n**Location:** Hardoi district · **Designation:** 26 September 2019 · **Registered Area:** 308.5 ha\n\n- **Type And Water:** Natural **freshwater marsh**, primarily replenished by southwest-monsoon rainfall and local runoff; a representative Indo-Gangetic wetland.\n- **Bird Habitat:** Productive shallow water supports wintering ducks and resident **sarus crane [VU]**. **Common teal [LC]**, **red-crested pochard [LC]** and **ferruginous duck [NT]** are significant recorded waterbirds.\n- **International Importance:** Published counts demonstrate the importance of population thresholds as well as species diversity; a site can qualify through regularly supporting a substantial share of one waterbird population.\n- **Human Use:** Nearby agriculture uses fodder and other wetland resources; recreation is another use.\n- **Pressures And Distinction:** Severe drought dried the site in **2014–2015**, illustrating that natural rain dependence can cause abrupt habitat loss. **Sandi—Hardoi** is distinct from **Saman—Mainpuri** and **Samaspur—Raebareli**.\n","species":["sarus crane","common teal","red-crested pochard","ferruginous duck"]},"2411":{"name":"Sarsai Nawar Jheel","state":"Uttar Pradesh","sections":[{"heading":"Location And Designation","facts":["**Location:** Etawah district · **Designation:** 19 September 2019 · **Registered Area:** 161.3 ha"]},{"heading":"Type","facts":["Monsoon-fed **marsh and agricultural wetland** in the Indo-Gangetic floodplain; “Sarsai” is associated with the sarus crane."]},{"heading":"Wildlife","facts":["Especially important for **sarus crane [VU]**, a largely resident bird whose nesting can occur in cultivated wetland landscapes; the site is not only a winter-migrant refuge."]},{"heading":"Human–Wildlife Relationship","facts":["Farming practices and retained wet patches can support cranes when drainage, disturbance and destruction of nests are avoided."]},{"heading":"Culture","facts":["The nearby **Hajari Mahadev temple** gives the wetland religious importance alongside its ecological role."]},{"heading":"Pressures","facts":["Drought and drainage reduce marsh habitat; compatible farming and water retention are central to protection. Historical flock counts are not fixed current population totals."]}],"markdown":"# Sarsai Nawar Jheel\n\n**Location:** Etawah district · **Designation:** 19 September 2019 · **Registered Area:** 161.3 ha\n\n- **Type:** Monsoon-fed **marsh and agricultural wetland** in the Indo-Gangetic floodplain; “Sarsai” is associated with the sarus crane.\n- **Wildlife:** Especially important for **sarus crane [VU]**, a largely resident bird whose nesting can occur in cultivated wetland landscapes; the site is not only a winter-migrant refuge.\n- **Human–Wildlife Relationship:** Farming practices and retained wet patches can support cranes when drainage, disturbance and destruction of nests are avoided.\n- **Culture:** The nearby **Hajari Mahadev temple** gives the wetland religious importance alongside its ecological role.\n- **Pressures:** Drought and drainage reduce marsh habitat; compatible farming and water retention are central to protection. Historical flock counts are not fixed current population totals.\n","species":["sarus crane"]},"2603":{"name":"Sauj Jheel","state":"Uttar Pradesh","sections":[{"heading":"Location And Designation","facts":["**Location:** Mainpuri district, near Saman Bird Sanctuary · **Designation:** 18 June 2026 · **Registered Area:** 40.8 ha"]},{"heading":"Type","facts":["Shallow **freshwater lake on the Ganga floodplain**, surrounded by farmland and connected ecologically with a broader wetland network."]},{"heading":"Habitat","facts":["Aquatic vegetation and tall wetland plants provide nesting substrate, shelter and feeding resources; open and vegetated water support different birds."]},{"heading":"Wildlife","facts":["Regularly supports large waterbird congregations, including **sarus crane [VU]** and **greater spotted eagle [VU]**; official descriptions report over **30,000 individual waterbirds**."]},{"heading":"Management","facts":["Proposed seasonal fishing restrictions, control of fine-mesh nets and managed cattle access address damage to breeding fish, vegetation and nesting habitat."]},{"heading":"Dates And Contrast","facts":["Designated **18 June 2026**, announced **15 October 2026**. **Sauj and Saman are separate Mainpuri Ramsar sites**, not alternative names for one lake."]}],"markdown":"# Sauj Jheel\n\n**Location:** Mainpuri district, near Saman Bird Sanctuary · **Designation:** 18 June 2026 · **Registered Area:** 40.8 ha\n\n- **Type:** Shallow **freshwater lake on the Ganga floodplain**, surrounded by farmland and connected ecologically with a broader wetland network.\n- **Habitat:** Aquatic vegetation and tall wetland plants provide nesting substrate, shelter and feeding resources; open and vegetated water support different birds.\n- **Wildlife:** Regularly supports large waterbird congregations, including **sarus crane [VU]** and **greater spotted eagle [VU]**; official descriptions report over **30,000 individual waterbirds**.\n- **Management:** Proposed seasonal fishing restrictions, control of fine-mesh nets and managed cattle access address damage to breeding fish, vegetation and nesting habitat.\n- **Dates And Contrast:** Designated **18 June 2026**, announced **15 October 2026**. **Sauj and Saman are separate Mainpuri Ramsar sites**, not alternative names for one lake.\n","species":["sarus crane","greater spotted eagle"]},"2594":{"name":"Sheikha Jheel Bird Sanctuary","state":"Uttar Pradesh","sections":[{"heading":"Location And Designation","facts":["**Location:** Koil tehsil, Aligarh district · **Designation:** 19 January 2026 · **Registered Area:** 40.3 ha"]},{"heading":"Origin","facts":["Partly human-made **freshwater wetland beside the Upper Ganges Canal**, developing after construction of the canal in the nineteenth century."]},{"heading":"Habitats","facts":["Lake and adjoining deciduous woodland form an ecotone supporting diverse terrestrial and aquatic species."]},{"heading":"Wildlife","facts":["**River tern [VU]**, **sarus crane [VU]**, **spotted pond turtle [EN]**, **Indian flapshell turtle [VU]** and **Ganges softshell turtle [EN]** are recorded."]},{"heading":"Management","facts":["Desilting and invasive-species control aim to retain suitable depths and habitat; interventions must retain shallow margins as well as open water."]},{"heading":"Distinction","facts":["**Sheikha Jheel—Aligarh**; **Patna Bird Sanctuary—Etah**; **Nawabganj—Unnao**. Canal-associated origin differs from a natural oxbow’s formation by river meandering."]}],"markdown":"# Sheikha Jheel Bird Sanctuary\n\n**Location:** Koil tehsil, Aligarh district · **Designation:** 19 January 2026 · **Registered Area:** 40.3 ha\n\n- **Origin:** Partly human-made **freshwater wetland beside the Upper Ganges Canal**, developing after construction of the canal in the nineteenth century.\n- **Habitats:** Lake and adjoining deciduous woodland form an ecotone supporting diverse terrestrial and aquatic species.\n- **Wildlife:** **River tern [VU]**, **sarus crane [VU]**, **spotted pond turtle [EN]**, **Indian flapshell turtle [VU]** and **Ganges softshell turtle [EN]** are recorded.\n- **Management:** Desilting and invasive-species control aim to retain suitable depths and habitat; interventions must retain shallow margins as well as open water.\n- **Distinction:** **Sheikha Jheel—Aligarh**; **Patna Bird Sanctuary—Etah**; **Nawabganj—Unnao**. Canal-associated origin differs from a natural oxbow’s formation by river meandering.\n","species":["river tern","sarus crane","spotted pond turtle","indian flapshell turtle","ganges softshell turtle"]},"2440":{"name":"Sur Sarovar","state":"Uttar Pradesh","sections":[{"heading":"Location And Designation","facts":["**Location:** Agra district · **Designation:** 21 August 2020 · **Registered Area:** 431 ha"]},{"heading":"Name And Origin","facts":["**Sur Sarovar/Keetham Lake** is a human-made freshwater reservoir developed originally for Agra’s water supply."]},{"heading":"Habitats","facts":["Open water, shallow margins and vegetation patches support fish and both resident and migratory waterbirds."]},{"heading":"Wildlife","facts":["Associated with **greater spotted eagle [VU]**, **sarus crane [VU]**, **greylag goose [LC]** and the large predatory catfish **Wallago attu [VU]**."]},{"heading":"Flyway Function","facts":["Provides wintering and resting habitat on the **Central Asian Flyway**; large goose congregations illustrate population-based importance beyond species richness."]},{"heading":"Pressures And Contrast","facts":["Sewage and urban wastewater, invasive plants and unmanaged tourism threaten the reservoir. **Sur Sarovar is in Agra**, not at the **Surha Tal/Jai Prakash Narayan sanctuary in Ballia**."]}],"markdown":"# Sur Sarovar\n\n**Location:** Agra district · **Designation:** 21 August 2020 · **Registered Area:** 431 ha\n\n- **Name And Origin:** **Sur Sarovar/Keetham Lake** is a human-made freshwater reservoir developed originally for Agra’s water supply.\n- **Habitats:** Open water, shallow margins and vegetation patches support fish and both resident and migratory waterbirds.\n- **Wildlife:** Associated with **greater spotted eagle [VU]**, **sarus crane [VU]**, **greylag goose [LC]** and the large predatory catfish **Wallago attu [VU]**.\n- **Flyway Function:** Provides wintering and resting habitat on the **Central Asian Flyway**; large goose congregations illustrate population-based importance beyond species richness.\n- **Pressures And Contrast:** Sewage and urban wastewater, invasive plants and unmanaged tourism threaten the reservoir. **Sur Sarovar is in Agra**, not at the **Surha Tal/Jai Prakash Narayan sanctuary in Ballia**.\n","species":["greater spotted eagle","sarus crane","greylag goose","wallago attu"]},"1574":{"name":"Upper Ganga River","state":"Uttar Pradesh","sections":[{"heading":"Location And Designation","facts":["**Location:** Brijghat–Narora stretch of the Ganga · **Designation:** 8 November 2005 · **Registered Area:** 26,590 ha"]},{"heading":"Type","facts":["**Riverine Ramsar site**, not a lake; the designated stretch includes flowing water, deep pools, sandy banks and barrage-influenced habitats."]},{"heading":"Wildlife","facts":["**Ganges river dolphin [EN]**, **gharial [CR]**, freshwater turtles and fish depend on different parts of the river habitat mosaic."]},{"heading":"Mechanism","facts":["Barrages can create pools but also interrupt fish movement and change flow, sediment transport and connectivity. A riverine site requires adequate environmental flows, not just a protected shoreline."]},{"heading":"Uses And Pressures","facts":["Pilgrimage, bathing, fisheries and agriculture coexist; sewage, agrochemical runoff, fishing nets and reduced or altered flow affect wildlife."]},{"heading":"Distinction","facts":["**Ganges river dolphin—Ganga system**; **Indus river dolphin—Beas remnant population in India**. The two are distinct species under current taxonomy."]}],"markdown":"# Upper Ganga River\n\n**Location:** Brijghat–Narora stretch of the Ganga · **Designation:** 8 November 2005 · **Registered Area:** 26,590 ha\n\n- **Type:** **Riverine Ramsar site**, not a lake; the designated stretch includes flowing water, deep pools, sandy banks and barrage-influenced habitats.\n- **Wildlife:** **Ganges river dolphin [EN]**, **gharial [CR]**, freshwater turtles and fish depend on different parts of the river habitat mosaic.\n- **Mechanism:** Barrages can create pools but also interrupt fish movement and change flow, sediment transport and connectivity. A riverine site requires adequate environmental flows, not just a protected shoreline.\n- **Uses And Pressures:** Pilgrimage, bathing, fisheries and agriculture coexist; sewage, agrochemical runoff, fishing nets and reduced or altered flow affect wildlife.\n- **Distinction:** **Ganges river dolphin—Ganga system**; **Indus river dolphin—Beas remnant population in India**. The two are distinct species under current taxonomy.\n","species":["ganges river dolphin","gharial"]},"2437":{"name":"Asan Conservation Reserve","state":"Uttarakhand","sections":[{"heading":"Location And Designation","facts":["**Location:** Dehradun district, Asan–Yamuna confluence · **Designation:** 21 July 2020 · **Registered Area:** 444.4 ha"]},{"heading":"Origin","facts":["Reservoir and riverine wetland associated with the **Asan barrage, built in 1967**, near the **confluence of the Asan and Yamuna**."]},{"heading":"Habitat Formation","facts":["Sediment accumulation above the barrage created shallows and emergent vegetation used by waterbirds; sediment is not uniformly harmful in every context."]},{"heading":"Wildlife","facts":["Significant for **ruddy shelduck [LC]** and **red-crested pochard [LC]**; also supports **golden mahseer [EN]** and recorded threatened birds."]},{"heading":"Functions","facts":["Feeding, fish migration and spawning habitat, water regulation and hydropower-related water management."]},{"heading":"Distinction","facts":["A **Conservation Reserve** in the **Yamuna basin**, not a high-altitude glacial lake. Barrage operation, water quality and habitat connectivity are important to its ecology."]}],"markdown":"# Asan Conservation Reserve\n\n**Location:** Dehradun district, Asan–Yamuna confluence · **Designation:** 21 July 2020 · **Registered Area:** 444.4 ha\n\n- **Origin:** Reservoir and riverine wetland associated with the **Asan barrage, built in 1967**, near the **confluence of the Asan and Yamuna**.\n- **Habitat Formation:** Sediment accumulation above the barrage created shallows and emergent vegetation used by waterbirds; sediment is not uniformly harmful in every context.\n- **Wildlife:** Significant for **ruddy shelduck [LC]** and **red-crested pochard [LC]**; also supports **golden mahseer [EN]** and recorded threatened birds.\n- **Functions:** Feeding, fish migration and spawning habitat, water regulation and hydropower-related water management.\n- **Distinction:** A **Conservation Reserve** in the **Yamuna basin**, not a high-altitude glacial lake. Barrage operation, water quality and habitat connectivity are important to its ecology.\n","species":["ruddy shelduck","red-crested pochard","golden mahseer"]},"1208":{"name":"East Calcutta Wetlands","state":"West Bengal","sections":[{"heading":"Location And Designation","facts":["**Location:** Eastern Kolkata · **Designation:** 19 August 2002 · **Registered Area:** 12,500 ha"]},{"heading":"Type","facts":["Human-managed mosaic of **sewage-fed fishponds, canals, marshes and agricultural land**; official Ramsar name retains “East Calcutta”, while “East Kolkata Wetlands” is widely used."]},{"heading":"Treatment Mechanism","facts":["Shallow ponds allow sunlight-driven algal production; algae supply oxygen and support food chains, while microbes break down organic matter and particles settle. Nutrients are reused in fish and vegetable production."]},{"heading":"Services","facts":["Wastewater treatment, resource recovery, fisheries, agriculture and livelihoods operate together rather than as separate ecosystem functions."]},{"heading":"Limits","facts":["Industrial toxicants and heavy metals are not made harmless simply by routing them through ponds; contamination can accumulate in sediments and food chains."]},{"heading":"Pressures","facts":["Urban filling, land conversion, blockage of sewage channels and industrial effluent threaten the functioning wetland system. A Ramsar site can include working production landscapes."]}],"markdown":"# East Calcutta Wetlands\n\n**Location:** Eastern Kolkata · **Designation:** 19 August 2002 · **Registered Area:** 12,500 ha\n\n- **Type:** Human-managed mosaic of **sewage-fed fishponds, canals, marshes and agricultural land**; official Ramsar name retains “East Calcutta”, while “East Kolkata Wetlands” is widely used.\n- **Treatment Mechanism:** Shallow ponds allow sunlight-driven algal production; algae supply oxygen and support food chains, while microbes break down organic matter and particles settle. Nutrients are reused in fish and vegetable production.\n- **Services:** Wastewater treatment, resource recovery, fisheries, agriculture and livelihoods operate together rather than as separate ecosystem functions.\n- **Limits:** Industrial toxicants and heavy metals are not made harmless simply by routing them through ponds; contamination can accumulate in sediments and food chains.\n- **Pressures:** Urban filling, land conversion, blockage of sewage channels and industrial effluent threaten the functioning wetland system. A Ramsar site can include working production landscapes.\n","species":[]},"2370":{"name":"Sundarban Wetland","state":"West Bengal","sections":[{"heading":"Location And Designation","facts":["**Location:** Indian Sundarbans, Ganga–Brahmaputra–Meghna delta · **Designation:** 30 January 2019 · **Registered Area:** 423,000 ha"]},{"heading":"Type","facts":["Extensive **tidal mangrove wetland** of islands, estuarine rivers, creeks and mudflats along the Bay of Bengal; the wider Sundarbans extend into Bangladesh."]},{"heading":"Boundary","facts":["India’s largest Ramsar site in this inventory, **423,000 ha**. It is not identical in area to Sundarban National Park, the Tiger Reserve or Bangladesh’s separately designated wetlands."]},{"heading":"Wildlife","facts":["**Tiger [EN]**, **northern river terrapin [CR]**, **Irrawaddy dolphin [EN]** and **fishing cat [VU]** illustrate terrestrial, freshwater–estuarine and tidal habitat relationships."]},{"heading":"Functions","facts":["Mangroves reduce wave energy, stabilize sediment, store carbon and provide fish and shellfish nurseries; they do not make the coast immune to cyclones."]},{"heading":"Pressures","facts":["Sea-level rise, salinity change, erosion, upstream flow changes, pollution and resource pressure interact. The National Park is a UNESCO World Heritage property; Ramsar designation is a separate framework."]}],"markdown":"# Sundarban Wetland\n\n**Location:** Indian Sundarbans, Ganga–Brahmaputra–Meghna delta · **Designation:** 30 January 2019 · **Registered Area:** 423,000 ha\n\n- **Type:** Extensive **tidal mangrove wetland** of islands, estuarine rivers, creeks and mudflats along the Bay of Bengal; the wider Sundarbans extend into Bangladesh.\n- **Boundary:** India’s largest Ramsar site in this inventory, **423,000 ha**. It is not identical in area to Sundarban National Park, the Tiger Reserve or Bangladesh’s separately designated wetlands.\n- **Wildlife:** **Tiger [EN]**, **northern river terrapin [CR]**, **Irrawaddy dolphin [EN]** and **fishing cat [VU]** illustrate terrestrial, freshwater–estuarine and tidal habitat relationships.\n- **Functions:** Mangroves reduce wave energy, stabilize sediment, store carbon and provide fish and shellfish nurseries; they do not make the coast immune to cyclones.\n- **Pressures:** Sea-level rise, salinity change, erosion, upstream flow changes, pollution and resource pressure interact. The National Park is a UNESCO World Heritage property; Ramsar designation is a separate framework.\n","species":["tiger","northern river terrapin","irrawaddy dolphin","fishing cat"]}},"species":{"baer’s pochard":{"name":"Baer’s pochard","scientificName":"Aythya baeri","category":"CR","source":"https://www.iucnredlist.org/species/22680384/154436811","scope":"Global Species","notes":"Rare East Asian diving duck; males have a dark greenish head and conspicuous pale eye. Indian records are scattered winter/occasional occurrences, not proof of a large resident population. Breeding-wetland loss, hunting and disturbance are major threats; distinguish it from common and ferruginous pochards."},"bar-headed goose":{"name":"Bar-headed goose","scientificName":"Anser indicus","category":"LC","source":"https://www.iucnredlist.org/species/22679893/131908564","scope":"Global Species","notes":"Two dark head bars; migrates across Himalayan routes and uses high-altitude breeding lakes and lowland wintering wetlands. Physiological adaptations aid flight under low oxygen, but not every flight follows the maximum possible altitude. Breeds at Ladakh wetlands and winters at sites such as Pong, Nagi and Magadi Kere."},"black stork":{"name":"Black stork","scientificName":"Ciconia nigra","category":"LC","source":"https://www.iucnredlist.org/species/22697669/281840802","scope":"Global Species","notes":"Dark stork with a white belly and long reddish bill/legs; many Indian birds are winter visitors from northern breeding areas. Often uses relatively quiet wetlands and streams to take fish and small aquatic prey. Secure feeding/resting areas matter; recorded at Siliserh."},"black-bellied tern":{"name":"Black-bellied tern","scientificName":"Sterna acuticauda","category":"EN","source":"https://www.iucnredlist.org/species/22694711/207933556","scope":"Global Species","notes":"Slender river tern with a dark belly in breeding plumage and a deeply forked tail. Nests on riverine sandbars and feeds on aquatic prey. South Asian river regulation, sand extraction, disturbance and loss of safe nesting substrate threaten it; distinct from river tern."},"black-crowned night heron":{"name":"Black-crowned night heron","scientificName":"Nycticorax nycticorax","category":"LC","source":"https://www.iucnredlist.org/species/22697211/280905252","scope":"Global Species","notes":"Stocky heron with a dark crown/back, often feeding at dusk or night on fish and other small animals. Nests colonially in vegetation. Widely distributed, including India’s tank wetlands; daytime roost disturbance and loss of nesting vegetation can reduce habitat quality."},"black-headed ibis":{"name":"Black-headed ibis","scientificName":"Threskiornis melanocephalus","category":"LC","source":"https://www.iucnredlist.org/species/22697516/252063963","scope":"Global Species","notes":"White ibis with a bare dark head/neck and a long curved bill used for probing mud for invertebrates and other small food. Resident/local-moving in South and Southeast Asia, often nesting colonially. Wetland drainage, pollution and loss of nesting sites remain relevant local pressures."},"black-necked crane":{"name":"Black-necked crane","scientificName":"Grus nigricollis","category":"NT","source":"https://www.iucnredlist.org/species/22692162/180030167","scope":"Global Species","notes":"High-altitude crane of the Tibetan Plateau and Himalayan wetlands; black head/neck contrast with a pale body. Breeds in summer in Ladakh and winters at lower elevations in parts of the Himalaya. Disturbance, wetland alteration and dogs threaten breeding success; its range is not confined to Tsomoriri."},"bronze-winged jacana":{"name":"Bronze-winged jacana","scientificName":"Metopidius indicus","category":"LC","source":"https://www.iucnredlist.org/species/22693547/264996291","scope":"Global Species","notes":"Long toes distribute weight on floating vegetation, enabling it to walk on aquatic leaves; chestnut/bronze wings and a strong white eyebrow aid identification. Occurs in tropical Asian freshwater wetlands, including India. Breeding can involve female polyandry and male incubation; removal of floating vegetation destroys habitat."},"common crane":{"name":"Common crane","scientificName":"Grus grus","category":"LC","source":"https://www.iucnredlist.org/species/22692146/265333107","scope":"Global Species","notes":"Large grey crane with a red crown patch, white face/neck markings and drooping ornamental feathers. Eurasian breeding populations winter in Indian wetlands and agricultural landscapes, including Kachchh. Depends on safe roosts and feeding areas; disturbance and wetland drainage reduce local suitability."},"common pochard":{"name":"Common pochard","scientificName":"Aythya ferina","category":"VU","source":"https://www.iucnredlist.org/species/22680358/205288455","scope":"Global Species","notes":"Diving duck; male has a chestnut head, black breast and pale-grey body. Many Indian records are winter migrants from northern breeding grounds. Uses lakes and reservoirs with underwater food; hunting, loss/degradation of breeding wetlands and changes in water regimes contribute to decline."},"common teal":{"name":"Common teal","scientificName":"Anas crecca","category":"LC","source":"https://www.iucnredlist.org/species/22680321/181692388","scope":"Global Species","notes":"Small dabbling duck; breeding male has a chestnut head with a green eye patch. Many birds winter in India after breeding farther north. Uses shallow marshes, flooded fields and lake edges such as Sandi; loss of seasonally inundated feeding grounds matters even where a deep central pool survives."},"dalmatian pelican":{"name":"Dalmatian pelican","scientificName":"Pelecanus crispus","category":"NT","source":"https://www.iucnredlist.org/species/22697599/122838534","scope":"Global Species","notes":"Very large, pale pelican with a curly nape; feeds mainly on fish. Migrant/wintering birds use Indian wetlands such as Wadhvana and Khijadia. Disturbance at roosts, wetland loss and unsafe infrastructure affect populations; distinguish it from the more characteristically tree-nesting spot-billed pelican."},"demoiselle crane":{"name":"Demoiselle crane","scientificName":"Anthropoides virgo","category":"LC","source":"https://www.iucnredlist.org/species/22692081/131927771","scope":"Global Species","notes":"Relatively small crane with long white head plumes and dark neck feathers; breeds across Eurasian steppe and migrates to India. Large winter flocks use Khichan and nearby feeding areas. Power lines, persecution and loss of resting habitat can threaten local flocks despite global LC status."},"eastern imperial eagle":{"name":"Eastern imperial eagle","scientificName":"Aquila heliaca","category":"VU","source":"https://www.iucnredlist.org/species/22696048/203686356","scope":"Global Species","notes":"Large tree-nesting raptor of open woodland/steppe landscapes; some populations winter in India. Feeds on mammals, birds and carrion. Wetland-associated open landscapes provide foraging habitat; habitat conversion, poisoning and collisions/electrocution threaten it. Distinct from steppe and spotted eagles."},"egyptian vulture":{"name":"Egyptian vulture","scientificName":"Neophron percnopterus","category":"EN","source":"https://www.iucnredlist.org/species/22695180/205187871","scope":"Global Species","notes":"Relatively small white-and-black vulture with a bare yellow face; scavenges and is known for stone-tool use to open large eggs in some populations. Occurs across parts of Europe, Africa and Asia, including India. Poisoning, veterinary-drug exposure, electrocution and declining safe food supplies are threats."},"eurasian spoonbill":{"name":"Eurasian spoonbill","scientificName":"Platalea leucorodia","category":"LC","source":"https://www.iucnredlist.org/species/22697555/281857155","scope":"Global Species","notes":"White wader with a broad spoon-shaped bill swept side-to-side through shallow water to capture small aquatic prey. Uses inland and coastal wetlands; occurs in Indian colonies and seasonal congregations. Depends on suitable shallow feeding areas and secure nesting/roosting habitat, including Vedanthangal."},"eurasian wigeon":{"name":"Eurasian wigeon","scientificName":"Mareca penelope","category":"LC","source":"https://www.iucnredlist.org/species/22680157/281853446","scope":"Global Species","notes":"Winter migrant to India; male has a chestnut head with a cream forehead. Often grazes wet grass and feeds on aquatic vegetation, unlike ducks relying mainly on deep diving for food. Uses lakes and tank margins such as Vaduvur; needs both safe water and adjacent feeding habitat."},"ferruginous duck":{"name":"Ferruginous duck","scientificName":"Aythya nyroca","category":"NT","source":"https://www.iucnredlist.org/species/22680373/152620862","scope":"Global Species","notes":"Chestnut-coloured diving duck; male’s pale eye explains the older name “white-eyed pochard”. Uses vegetated freshwater wetlands, with wintering populations in India. It is neither Baer’s pochard nor the common pochard; wetland drainage, vegetation change and hunting affect its habitats."},"garganey":{"name":"Garganey","scientificName":"Spatula querquedula","category":"LC","source":"https://www.iucnredlist.org/species/22680313/154807983","scope":"Global Species","notes":"Small migratory dabbling duck; male shows a broad white eyebrow. Breeds largely in the temperate Palearctic and winters in tropical/subtropical wetlands, including India. Often feeds in shallow vegetated water; drainage, hunting and changes in flood duration affect stopovers and winter habitat."},"glossy ibis":{"name":"Glossy ibis","scientificName":"Plegadis falcinellus","category":"LC","source":"https://www.iucnredlist.org/species/22697422/281858334","scope":"Global Species","notes":"Dark chestnut/iridescent ibis with a slender downcurved probing bill. Uses marshes and flooded agricultural land; Indian populations include resident/local-moving birds and migrants. Concentrations at Ankasamudra and Pallikaranai reflect productive shallows; drainage and altered flood timing reduce habitat."},"greater adjutant":{"name":"Greater adjutant","scientificName":"Leptoptilos dubius","category":"NT","source":"https://www.iucnredlist.org/species/22697721/229597779","scope":"Global Species","notes":"Very large stork with a bare head/neck and a prominent hanging throat pouch; scavenges and also takes aquatic prey. Major remaining breeding concentrations are in India and Cambodia. Nest-tree loss, poisoning, waste-related hazards and wetland degradation matter; the old EN category is no longer the current global label."},"greater flamingo":{"name":"Greater flamingo","scientificName":"Phoenicopterus roseus","category":"LC","source":"https://www.iucnredlist.org/species/22697360/155527405","scope":"Global Species","notes":"Large pale-pink flamingo; feeds by filtering small aquatic organisms and other food with an inverted bill. Uses saline and brackish wetlands from the Mediterranean/Africa into Asia, including India. Water depth and salinity regulate feeding resources; global LC does not preclude severe local habitat loss."},"greater spotted eagle":{"name":"Greater spotted eagle","scientificName":"Clanga clanga","category":"VU","source":"https://www.iucnredlist.org/species/22696027/203868747","scope":"Global Species","notes":"Migratory raptor breeding largely farther north and wintering in parts of India; often hunts over wetland–grassland mosaics. Feeds on varied prey rather than fish alone. Wetland conversion, persecution and unsafe infrastructure affect migration/winter habitat; distinct from the more resident Indian spotted eagle."},"grey heron":{"name":"Grey heron","scientificName":"Ardea cinerea","category":"LC","source":"https://www.iucnredlist.org/species/22696993/154525233","scope":"Global Species","notes":"Large grey long-necked heron that waits or stalks in shallow water for fish and other prey; flies with the neck retracted. Resident and migrant populations occur across a wide range including India. Feeding margins and nesting trees matter; winter occurrence alone does not establish local breeding."},"grey-headed lapwing":{"name":"Grey-headed lapwing","scientificName":"Vanellus cinereus","category":"LC","source":"https://www.iucnredlist.org/species/22694010/265011262","scope":"Global Species","notes":"Grey-headed, long-legged wader with a yellow bill dark at the tip; winter visitor to much of India. Feeds on invertebrates in shallow wetlands, mud and wet fields, including Pallikaranai. Depends on accessible foraging margins; not every wetland bird is a swimmer or fish-eater."},"greylag goose":{"name":"Greylag goose","scientificName":"Anser anser","category":"LC","source":"https://www.iucnredlist.org/species/22679889/131907747","scope":"Global Species","notes":"Large grey goose with a stout pale/orange bill; an herbivorous grazer that also feeds on aquatic plants and crops. Migrant populations winter on Indian lakes and floodplains, including Saman and Sur Sarovar. Loss of safe roosts, disturbance and incompatible land use can affect local congregations."},"indian cormorant":{"name":"Indian cormorant","scientificName":"Phalacrocorax fuscicollis","category":"LC","source":"https://www.iucnredlist.org/species/22696779/132592646","scope":"Global Species","notes":"Fish-eating pursuit diver with a relatively slender bill and neck; uses rivers, tanks and lakes in South/Southeast Asia. Nests colonially in trees, including at Ankasamudra and Nanjarayan. Fishing-net entanglement, disturbance and loss of roost/nest trees can affect local use."},"indian skimmer":{"name":"Indian skimmer","scientificName":"Rynchops albicollis","category":"EN","source":"https://www.iucnredlist.org/species/22694268/178970109","scope":"Global Species","notes":"Longer lower mandible allows it to skim the water surface for fish while flying low. Nests on exposed river sandbars; India supports important remaining populations. Altered flows, flooding or loss of breeding islands, sand mining and disturbance threaten colonies; bill asymmetry is its key feeding adaptation."},"indian spotted eagle":{"name":"Indian spotted eagle","scientificName":"Clanga hastata","category":"NT","source":"https://www.iucnredlist.org/species/22729779/271159296","scope":"Global Species","notes":"Predominantly resident South Asian eagle of open woodland, fields and wetland-associated landscapes; eats small vertebrates and other prey. Tree nesting links it to surrounding terrestrial habitat. Its current NT assessment differs from older VU references and from the greater spotted eagle’s VU category."},"indian vulture":{"name":"Indian vulture","scientificName":"Gyps indicus","category":"CR","source":"https://www.iucnredlist.org/species/22729731/204672586","scope":"Global Species","notes":"Large scavenging vulture, also called long-billed vulture; typically breeds on cliffs or rock faces. Occurs mainly in the Indian subcontinent. Veterinary diclofenac in livestock carcasses caused catastrophic mortality; safe carcasses and control of toxic veterinary drugs are central conservation measures."},"lesser adjutant":{"name":"Lesser adjutant","scientificName":"Leptoptilos javanicus","category":"NT","source":"https://www.iucnredlist.org/species/22697713/232128569","scope":"Global Species","notes":"Large bare-headed stork lacking the greater adjutant’s conspicuous pendulous throat pouch; more closely associated with wetlands and agricultural foraging. Occurs in South/Southeast Asia, including Indian wetlands. Nest-tree removal, persecution and wetland change threaten local populations; former VU labels are outdated."},"lesser flamingo":{"name":"Lesser flamingo","scientificName":"Phoeniconaias minor","category":"NT","source":"https://www.iucnredlist.org/species/22697369/129912906","scope":"Global Species","notes":"Smaller, deeper-pink flamingo with a dark bill, specialized for filtering microscopic food, notably cyanobacteria, in suitable alkaline/saline waters. Indian sites include Kachchh/coastal wetlands and Thane Creek. Hydrological change, pollution and disturbance affect concentrated feeding and breeding habitats."},"lesser whistling duck":{"name":"Lesser whistling duck","scientificName":"Dendrocygna javanica","category":"LC","source":"https://www.iucnredlist.org/species/22679758/265006900","scope":"Global Species","notes":"Brown, relatively long-legged waterfowl with a characteristic whistling call; largely resident/local-moving in tropical Asian wetlands. Feeds on seeds, plant matter and small aquatic organisms. Uses shallow vegetated water such as Nanda Lake; local wetland loss and disturbance still matter despite LC status."},"little egret":{"name":"Little egret","scientificName":"Egretta garzetta","category":"LC","source":"https://www.iucnredlist.org/species/62774969/154819214","scope":"Global Species","notes":"Small white heron, typically with a black bill, black legs and yellow feet; actively hunts small aquatic prey in shallow water. Resident/local-moving and migrant birds occur in India. Uses fresh and brackish habitats; loss of feeding shallows and tree colonies affects local populations."},"marbled duck":{"name":"Marbled duck","scientificName":"Marmaronetta angustirostris","category":"NT","source":"https://www.iucnredlist.org/species/22680339/205917761","scope":"Global Species","notes":"Small, mottled pale-brown duck with a dark eye patch; uses shallow, densely vegetated wetlands in arid and semi-arid regions. Indian occurrence is limited compared with common wintering ducks. Loss of marshes, over-abstraction and drought affect the scarce suitable habitat; recorded at Nalsarovar."},"nilgiri laughingthrush":{"name":"Nilgiri laughingthrush","scientificName":"Montecincla cachinnans","category":"NT","source":"https://www.iucnredlist.org/species/103874076/249719877","scope":"Global Species","notes":"Western Ghats endemic montane forest bird, also called black-chinned laughingthrush in older sources; forages in dense understorey. Associated with Nilgiri sholas such as Longwood. Forest fragmentation, degradation and unsuitable land-use change affect habitat; other laughingthrush species have separate assessments."},"nilgiri sholakili":{"name":"Nilgiri sholakili","scientificName":"Sholicola major","category":"NT","source":"https://www.iucnredlist.org/species/22735416/249568548","scope":"Global Species","notes":"Small Western Ghats endemic insectivorous bird of cool montane shola understorey, formerly called Nilgiri blue robin. Uses forested ravines and moist ground rather than open lake water. Fragmentation and loss of montane forest threaten its restricted habitat; taxonomic names in older site sheets can differ."},"nilgiri woodpigeon":{"name":"Nilgiri woodpigeon","scientificName":"Columba elphinstonii","category":"LC","source":"https://www.iucnredlist.org/species/22690173/250437157","scope":"Global Species","notes":"Western Ghats endemic pigeon with a patterned neck; primarily fruit-eating, contributing to seed dispersal in forests. Uses montane and other suitable evergreen forest, including shola landscapes. Forest loss/fragmentation remain relevant despite the updated global LC category; endemic does not necessarily mean formally threatened."},"northern pintail":{"name":"Northern pintail","scientificName":"Anas acuta","category":"LC","source":"https://www.iucnredlist.org/species/22680301/153882797","scope":"Global Species","notes":"Slender dabbling duck; male has a long pointed tail and a white stripe up the neck. Breeds mainly in northern regions and winters widely in Indian shallow wetlands. Dabbling differs from the sustained underwater feeding of diving ducks; drainage, hunting and disturbance affect habitat use."},"northern shoveler":{"name":"Northern shoveler","scientificName":"Spatula clypeata","category":"LC","source":"https://www.iucnredlist.org/species/22680247/153875944","scope":"Global Species","notes":"Dabbling duck with a conspicuously broad, spoon-shaped bill; fine bill lamellae filter small food particles and invertebrates. Winter visitor to many Indian wetlands, including Magadi Kere. Depends on productive shallow water; pollution, habitat conversion and disturbance can reduce suitable feeding conditions."},"oriental darter":{"name":"Oriental darter","scientificName":"Anhinga melanogaster","category":"LC","source":"https://www.iucnredlist.org/species/22696712/218634665","scope":"Global Species","notes":"“Snakebird” with a long thin neck and pointed bill; swims low and spears fish underwater, often drying spread wings afterward. Occurs in tropical South/Southeast Asian wetlands, including Indian tank colonies. Needs fish-bearing water and secure nesting/perching vegetation; not a snake or a cormorant species."},"painted stork":{"name":"Painted stork","scientificName":"Mycteria leucocephala","category":"LC","source":"https://www.iucnredlist.org/species/22697658/228020407","scope":"Global Species","notes":"Large wading bird with pink tertial feathers and a long yellowish downcurved bill. Probes/tactile-feeds for fish in shallow water and nests colonially in trees. Important in South Asian tank wetlands; protection of nesting trees and feeding grounds remains necessary even after its global category improved from NT."},"pallas’s fish eagle":{"name":"Pallas’s fish eagle","scientificName":"Haliaeetus leucoryphus","category":"EN","source":"https://www.iucnredlist.org/species/22695130/199521572","scope":"Global Species","notes":"Large fish-eating eagle associated with large rivers, lakes and wetlands across parts of Asia; also takes other prey. Nests in large trees. Indian wetland records include Sukhna and several northern sanctuaries; tree loss, disturbance, contamination and degradation of fish-bearing habitats threaten it."},"pheasant-tailed jacana":{"name":"Pheasant-tailed jacana","scientificName":"Hydrophasianus chirurgus","category":"LC","source":"https://www.iucnredlist.org/species/22693543/264999616","scope":"Global Species","notes":"Long-toed floating-vegetation bird; breeding adults develop an elongated tail. Female polyandry and substantial male parental care distinguish its breeding system. Uses South/Southeast Asian wetlands, including India; habitat depends on suitable aquatic plants and seasonal water, not merely an open pool."},"red-crested pochard":{"name":"Red-crested pochard","scientificName":"Netta rufina","category":"LC","source":"https://www.iucnredlist.org/species/22680348/280995672","scope":"Global Species","notes":"Diving duck; male has a rounded orange-red head and red bill. Feeds extensively on aquatic plant material and uses deeper/open water as well as vegetated margins. Important winter congregations occur at Nakti, Asan and Wadhvana; water-quality change and wetland conversion affect suitable habitat."},"river tern":{"name":"River tern","scientificName":"Sterna aurantia","category":"VU","source":"https://www.iucnredlist.org/species/22694537/180171504","scope":"Global Species","notes":"River/lake tern with a yellow bill and grey-white body; catches fish by plunge-diving and nests on exposed sand or gravel islands. Occurs in South Asia, including reservoirs and rivers. Flood timing, sand mining, disturbance and loss of nesting islands affect breeding success."},"ruddy shelduck":{"name":"Ruddy shelduck","scientificName":"Tadorna ferruginea","category":"LC","source":"https://www.iucnredlist.org/species/22680003/281866558","scope":"Global Species","notes":"Orange-rufous waterfowl with a pale head, often called Brahminy duck. Many Indian wintering birds breed farther north or at high elevations; feeds on plant matter and small aquatic animals. Uses river margins and reservoirs such as Asan; sensitive to loss of resting/feeding habitat and disturbance."},"saker falcon":{"name":"Saker falcon","scientificName":"Falco cherrug","category":"EN","source":"https://www.iucnredlist.org/species/22696495/204182473","scope":"Global Species","notes":"Large falcon of open Eurasian landscapes, with winter records in India; hunts birds and mammals. Not restricted to wetlands, but uses surrounding open habitat. Trapping, electrocution, prey/habitat change and other human pressures threaten populations; record at a site does not imply local nesting."},"sarus crane":{"name":"Sarus crane","scientificName":"Antigone antigone","category":"VU","source":"https://www.iucnredlist.org/species/22692064/225108915","scope":"Global Species","notes":"Large, predominantly resident crane of South Asian wetlands and agricultural mosaics; bare red head/upper neck and long legs. Pairs nest on wet ground or shallow-water vegetation. Drainage, power-line collisions and loss of breeding wetlands matter; seasonal local movements do not make it a long-distance winter migrant."},"siberian crane":{"name":"Siberian crane","scientificName":"Leucogeranus leucogeranus","category":"CR","source":"https://www.iucnredlist.org/species/22692053/134180990","scope":"Global Species","notes":"White crane with black flight feathers and reddish bare face; strongly dependent on wetlands for feeding. Historically wintered at Keoladeo, but is not a regular current visitor there. Remaining populations rely on a small number of migration and wintering areas; hydrological change and habitat loss are major threats."},"sociable lapwing":{"name":"Sociable lapwing","scientificName":"Vanellus gregarius","category":"CR","source":"https://www.iucnredlist.org/species/22694053/155545788","scope":"Global Species","notes":"Migratory steppe-breeding lapwing that winters in parts of southwest/south Asia, including India; often feeds on insects in open short vegetation and agricultural land. Uses wetland-associated open ground, not just lake water. Hunting along migration routes and loss of suitable habitat are major threats."},"spot-billed pelican":{"name":"Spot-billed pelican","scientificName":"Pelecanus philippensis","category":"NT","source":"https://www.iucnredlist.org/species/22697604/117970266","scope":"Global Species","notes":"Large fish-eating waterbird with a capacious throat pouch and spotted bill; breeds colonially in trees. Occurs across parts of South/Southeast Asia, including Indian tank sanctuaries and Kolleru. Feeding wetlands and nesting trees may be spatially separate; disturbance, tree loss and degraded fisheries threaten colonies."},"steppe eagle":{"name":"Steppe eagle","scientificName":"Aquila nipalensis","category":"EN","source":"https://www.iucnredlist.org/species/22696038/205452572","scope":"Global Species","notes":"Long-distance migrant from Eurasian steppe breeding areas; winters in India and elsewhere, taking small animals and carrion. Often associated with open country and wetland margins rather than obligate fishing. Electrocution, poisoning and habitat change are major threats along its migratory range."},"swamp francolin":{"name":"Swamp francolin","scientificName":"Ortygornis gularis","category":"NT","source":"https://www.iucnredlist.org/species/22678733/250119497","scope":"Global Species","notes":"Terrestrial gamebird of tall, wet grasslands and floodplain edges in the northern Indian subcontinent. It is not a diving waterbird. Habitat drainage, grassland conversion and burning/harvesting at unsuitable times can affect breeding; wetland margins such as those around Bakhira are relevant."},"white-bellied heron":{"name":"White-bellied heron","scientificName":"Ardea insignis","category":"CR","source":"https://www.iucnredlist.org/species/22697021/134201407","scope":"Global Species","notes":"Very large heron associated with relatively undisturbed clear rivers and adjoining pools in the eastern Himalayan region. Mainly fish-eating; small remaining range includes northeastern India and nearby countries. River alteration, disturbance and habitat loss are major threats; Glaw’s wider Kamlang landscape is relevant."},"white-rumped vulture":{"name":"White-rumped vulture","scientificName":"Gyps bengalensis","category":"CR","source":"https://www.iucnredlist.org/species/22695194/204618615","scope":"Global Species","notes":"Scavenging vulture identified by its pale rump and underwing contrast; breeds mainly in trees. Survives in South Asian landscapes, including wetland surroundings. Veterinary diclofenac poisoning drove severe declines; nesting trees and safe food are necessary along with formal protected-area status."},"asiatic black bear":{"name":"Asiatic black bear","scientificName":"Ursus thibetanus","category":"VU","source":"https://www.iucnredlist.org/species/22824/166528664","scope":"Global Species","notes":"Asian forest bear, often with a pale chest crescent; omnivorous, using fruits, nuts, insects and other food. Indian Himalayan populations include the Himalayan form traditionally called U. t. laniger. Species-level VU is not a separate verified subspecies category; habitat loss, conflict and illegal trade are threats."},"blackbuck":{"name":"Blackbuck","scientificName":"Antilope cervicapra","category":"LC","source":"https://www.iucnredlist.org/species/1681/50181949","scope":"Global Species","notes":"Antelope of open grassland and scrub in the Indian subcontinent; adult males usually have dark upperparts and spiralling horns. A grazer, not a deer or wetland obligate. Grassland conversion, fencing and hunting affect local populations; associated with Point Calimere’s adjoining terrestrial habitat."},"clouded leopard":{"name":"Clouded leopard","scientificName":"Neofelis nebulosa","category":"VU","source":"https://www.iucnredlist.org/species/14519/198843258","scope":"Global Species","notes":"Forest felid of mainland South/Southeast Asia with large cloud-like markings, long canines and strong climbing ability. Occurs in northeastern India, including the broader Kamlang landscape. Forest loss, hunting and fragmentation threaten it; it is a distinct genus, not a colour form of Panthera pardus."},"dugong":{"name":"Dugong","scientificName":"Dugong dugon","category":"VU","source":"https://www.iucnredlist.org/species/6909/160756767","scope":"Global Species","notes":"Marine herbivorous mammal of order Sirenia; grazes seagrasses in shallow coastal waters, unlike toothed dolphins hunting animal prey. Indian range includes Gulf of Mannar/Palk Bay, Gulf of Kachchh and Andaman–Nicobar waters. Habitat loss, nets, vessel strikes and slow reproduction increase vulnerability."},"eld’s deer/sangai":{"name":"Eld’s deer/Sangai","scientificName":"Rucervus eldii","category":"EN","source":"https://www.iucnredlist.org/species/4265/22166803","scope":"Global Species","notes":"Eld’s deer is the species-level assessment unit; Sangai is the Manipur form, traditionally R. e. eldii, associated with Keibul Lamjao’s floating meadows. Broadly splayed feet aid movement on soft ground. Altered phumdi hydrology, small isolated populations and habitat degradation threaten the Manipur population."},"eurasian otter":{"name":"Eurasian otter","scientificName":"Lutra lutra","category":"NT","source":"https://www.iucnredlist.org/species/12419/218069689","scope":"Global Species","notes":"Semi-aquatic carnivore with a very broad Eurasian range, including parts of India; forages on fish and other aquatic prey, commonly as a solitary animal. Requires suitable bank refuges and clean prey-bearing water. Pollution, habitat fragmentation and accidental capture threaten local populations; recorded in the Kashmir wetland landscape."},"fishing cat":{"name":"Fishing cat","scientificName":"Prionailurus viverrinus","category":"VU","source":"https://www.iucnredlist.org/species/18150/268618387","scope":"Global Species","notes":"Strongly wetland-associated Asian cat that swims and hunts fish as well as other prey; occurs in Indian marshes, floodplains and mangroves. Loss and fragmentation of wetlands, persecution and depletion of prey affect it. A fish-rich lake such as Surha Tal can provide feeding habitat."},"ganges river dolphin":{"name":"Ganges river dolphin","scientificName":"Platanista gangetica","category":"EN","source":"https://www.iucnredlist.org/species/41756/50383346","scope":"Global Species","notes":"Freshwater cetacean of the Ganga–Brahmaputra–Meghna and connected South Asian river systems. Very limited vision and echolocation aid hunting in turbid water; it must breathe air. Dams/barrages fragment habitat, while net entanglement, reduced flow and pollution threaten it. Distinct from Platanista minor of the Indus system."},"hog deer":{"name":"Hog deer","scientificName":"Axis porcinus","category":"EN","source":"https://www.iucnredlist.org/species/41784/22157664","scope":"Global Species","notes":"Small deer adapted to dense riverine grassland; it often runs head-low through cover rather than bounding conspicuously above it. Occurs in South Asian floodplains including India. Conversion of alluvial grasslands, hunting and disruption of floodplain refuges threaten it; relevant to Beas and Haiderpur landscapes."},"indian giant squirrel":{"name":"Indian giant squirrel","scientificName":"Ratufa indica","category":"LC","source":"https://www.iucnredlist.org/species/19378/22262028","scope":"Global Species","notes":"Large, arboreal squirrel endemic to India; moves through forest canopies and eats fruits, seeds and other plant/animal foods. Long tail aids balance. Forest fragmentation threatens local connectivity; associated with forest surrounding Tawa rather than dependent on the reservoir’s open water."},"indian pangolin":{"name":"Indian pangolin","scientificName":"Manis crassicaudata","category":"EN","source":"https://www.iucnredlist.org/species/12761/123583998","scope":"Global Species","notes":"Scale-covered mammal of the Indian subcontinent; toothless, using a long sticky tongue to eat ants and termites. Rolls into a defensive ball and uses burrows; not a reptile. Poaching for illegal trade and habitat degradation threaten it; records at Nangal relate mainly to the surrounding terrestrial landscape."},"indus river dolphin":{"name":"Indus river dolphin","scientificName":"Platanista minor","category":"EN","source":"https://www.iucnredlist.org/species/41757/243168232","scope":"Global Species","notes":"Freshwater dolphin of the Indus system, with India’s surviving known population in the Beas. Limited vision, echolocation and adaptation to turbid rivers distinguish it from lagoon-dwelling Irrawaddy dolphins. Barrage fragmentation and fishing-net mortality are major threats; older records call it a subspecies of P. gangetica."},"irrawaddy dolphin":{"name":"Irrawaddy dolphin","scientificName":"Orcaella brevirostris","category":"EN","source":"https://www.iucnredlist.org/species/15419/123790805","scope":"Global Species","notes":"Blunt-headed dolphin without a prominent beak; occurs in coastal waters, estuaries and some rivers of South/Southeast Asia. Chilika’s population uses a brackish lagoon, not a purely freshwater river. Bycatch, disturbance, habitat degradation and changing water regimes threaten populations; some river subpopulations have separate, more severe assessments."},"leopard":{"name":"Leopard","scientificName":"Panthera pardus","category":"VU","source":"https://www.iucnredlist.org/species/15954/286153337","scope":"Global Species","notes":"Spotted, highly adaptable large cat with a wide African/Asian range and broad Indian occurrence; often climbs and can carry prey into trees. Uses forest edges and many modified landscapes. Habitat fragmentation, persecution and illegal trade threaten it; presence around a wetland does not make it an aquatic specialist."},"phayre’s leaf monkey":{"name":"Phayre’s leaf monkey","scientificName":"Trachypithecus phayrei","category":"EN","source":"https://www.iucnredlist.org/species/175862145/175862149","scope":"Global Species","notes":"Tailed colobine monkey with pale eye rings; a forest canopy leaf-eater with specialized foregut fermentation. Occurs in parts of northeastern India and adjoining regions under current taxonomic scope. Habitat loss and hunting threaten it; distinct from the tailless, brachiating western hoolock gibbon."},"red panda":{"name":"Red panda","scientificName":"Ailurus fulgens","category":"EN","source":"https://www.iucnredlist.org/species/714/110023718","scope":"Global Species","notes":"Arboreal eastern Himalayan mammal in its own family, Ailuridae; a carnivoran by ancestry but bamboo-dominated in diet. Uses cool temperate forest with suitable understorey and tree cover, including Sikkim. Fragmentation, hunting and disturbance threaten it; it is neither a bear species nor confined to one sacred lake."},"smooth-coated otter":{"name":"Smooth-coated otter","scientificName":"Lutrogale perspicillata","category":"VU","source":"https://www.iucnredlist.org/species/12427/164579961","scope":"Global Species","notes":"Semi-aquatic mustelid of South/Southeast Asian rivers, lakes and wetlands; social groups often forage together, mainly for fish. Webbed feet aid swimming. Habitat alteration, pollution, nets and illegal trade threaten it; distinct from the Eurasian otter, even where both use river landscapes."},"snow leopard":{"name":"Snow leopard","scientificName":"Panthera uncia","category":"VU","source":"https://www.iucnredlist.org/species/22732/50664030","scope":"Global Species","notes":"High-mountain cat of Central/South Asia with thick fur, broad paws and a long balancing tail; hunts mountain ungulates. Indian range is Himalayan/trans-Himalayan. Prey loss, retaliatory killing and infrastructure pressure threaten it; a wider mountain-landscape record does not imply residence at a lowland lake."},"swamp deer":{"name":"Swamp deer","scientificName":"Rucervus duvaucelii","category":"VU","source":"https://www.iucnredlist.org/species/4257/22167675","scope":"Global Species","notes":"Large multi-tined deer, or barasingha; northern populations use swampy grasslands and floodplain refuges. Species-level VU includes populations with different habitat associations, so not all barasingha are equally swamp-dependent. Habitat loss, fragmentation and altered flooding matter; Haiderpur provides seasonal refuge in the northern range."},"tiger":{"name":"Tiger","scientificName":"Panthera tigris","category":"EN","source":"https://www.iucnredlist.org/species/15955/214862019","scope":"Global Species","notes":"Striped large cat and obligate carnivore; habitat ranges from forests and grasslands to the tidal Sundarbans mangroves. It is not restricted to mangroves or wetlands. Prey depletion, poaching and habitat fragmentation are major threats; site records must distinguish the entire reserve landscape from the immediate lake shore."},"western hoolock gibbon":{"name":"Western hoolock gibbon","scientificName":"Hoolock hoolock","category":"EN","source":"https://www.iucnredlist.org/species/39876/17968083","scope":"Global Species","notes":"Tailless ape of northeastern India and neighbouring countries; specialized arm-swinging brachiation in forest canopy, with a largely fruit-based diet. White brows aid identification. Forest fragmentation interrupts canopy travel and dispersal; not a tailed monkey, and not all primates share this locomotor specialization."},"ganges softshell turtle":{"name":"Ganges softshell turtle","scientificName":"Nilssonia gangetica","category":"EN","source":"https://www.iucnredlist.org/species/39618/2930943","scope":"Global Species","notes":"Aquatic softshell with a flattened leathery shell and snorkel-like nose; inhabits large river systems and connected wetlands in northern South Asia. Takes animal prey and carrion. Harvesting, fishing mortality and river degradation threaten it; distinct from hard-shelled spotted pond and roofed turtles."},"gharial":{"name":"Gharial","scientificName":"Gavialis gangeticus","category":"CR","source":"https://www.iucnredlist.org/species/8966/149227430","scope":"Global Species","notes":"Extremely long, narrow snout specialized for catching fish; mature males develop a bulbous “ghara”. River sandbanks are critical for nesting/basking. Surviving populations are highly fragmented in the subcontinent; dams, sand mining and nets threaten them. Beas reintroduction differs from uninterrupted wild persistence."},"hawksbill turtle":{"name":"Hawksbill turtle","scientificName":"Eretmochelys imbricata","category":"CR","source":"https://www.iucnredlist.org/species/8005/12881238","scope":"Global Species","notes":"Marine turtle with a narrow pointed beak and overlapping shell scutes; many populations feed heavily on reef sponges. Occurs in tropical seas including Indian reef habitats. Illegal tortoiseshell trade, bycatch and reef loss threaten it; differs from a seagrass-grazing dugong and a plankton-filtering whale shark."},"indian flapshell turtle":{"name":"Indian flapshell turtle","scientificName":"Lissemys punctata","category":"VU","source":"https://www.iucnredlist.org/species/123802477/3008930","scope":"Global Species","notes":"Freshwater softshell turtle with protective flaps covering the hindlimb region; uses ponds, marshes and slow water and can survive seasonal drying by burying in mud. Broad Indian-subcontinent range. Harvesting, trade, habitat loss and water pollution threaten it; not a terrestrial tortoise."},"mugger crocodile":{"name":"Mugger crocodile","scientificName":"Crocodylus palustris","category":"VU","source":"https://www.iucnredlist.org/species/5667/3046723","scope":"Global Species","notes":"Broad-snouted crocodilian of freshwater rivers, marshes, lakes and reservoirs in the Indian subcontinent and adjoining areas; takes varied animal prey. Uses banks for nesting and basking. Habitat change, nets and conflict threaten it; distinguish from the long-snouted fish-specialist gharial and coastal-tolerant saltwater crocodile."},"northern river terrapin":{"name":"Northern river terrapin","scientificName":"Batagur baska","category":"CR","source":"https://www.iucnredlist.org/species/97358453/2788691","scope":"Global Species","notes":"Large river/estuarine turtle of South Asia, now severely reduced; relevant to the Sundarbans. Uses brackish and freshwater environments and requires safe nesting habitat. Egg/adult harvesting, fishing gear and degradation of tidal-river habitat threaten it; distinct from the three-striped roofed turtle."},"olive ridley turtle":{"name":"Olive ridley turtle","scientificName":"Lepidochelys olivacea","category":"VU","source":"https://www.iucnredlist.org/species/11534/3292503","scope":"Global Species","notes":"Marine turtle with an olive-coloured carapace; some populations nest synchronously in mass arrivals called arribadas. Odisha’s Gahirmatha and Rushikulya coast are major Indian nesting landscapes. Trawl/bycatch mortality, beach disturbance and lighting threaten turtles; the species also nests individually outside mass-nesting beaches."},"saltwater crocodile":{"name":"Saltwater crocodile","scientificName":"Crocodylus porosus","category":"LC","source":"https://www.iucnredlist.org/species/5668/268788998","scope":"Global Species","notes":"Large crocodilian able to occupy estuaries, tidal rivers and coastal waters and to move through seawater; associated with Bhitarkanika. Salt tolerance does not make it a marine mammal or fish. Loss of nesting/estuarine habitat and human conflict affect local conservation despite global LC status."},"spotted pond turtle":{"name":"Spotted pond turtle","scientificName":"Geoclemys hamiltonii","category":"EN","source":"https://www.iucnredlist.org/species/9029/152050337","scope":"Global Species","notes":"Freshwater hard-shelled turtle, also called black pond turtle, with pale/yellowish spotting on a dark body. Uses slow water, marshes and ponds in northern South Asia. Predominantly takes animal food; illegal collection and habitat loss threaten it. The two common names denote one species, not two records."},"three-striped roofed turtle":{"name":"Three-striped roofed turtle","scientificName":"Batagur dhongoka","category":"CR","source":"https://www.iucnredlist.org/species/10953/152042542","scope":"Global Species","notes":"South Asian river turtle with longitudinal markings; females grow substantially larger than males. Uses medium/large rivers and nests on sandbanks. Indian records include the Rudrasagar wetland landscape. Harvesting, nets and nesting-bank disturbance threaten it; older Kachuga names refer to changed taxonomy."},"deolali minnow":{"name":"Deolali minnow","scientificName":"Parapsilorhynchus prateri","category":"CR","source":"https://www.iucnredlist.org/species/172471/6898894","scope":"Global Species","notes":"Small freshwater fish with a highly restricted Western Ghats/Deccan regional distribution; associated with the Nandur Madhameshwar landscape. Restricted ranges increase vulnerability to localized habitat damage. Pollution, water abstraction and alteration of stream habitats are important concerns; a minnow is not a mahseer despite both being freshwater fishes."},"golden mahseer":{"name":"Golden mahseer","scientificName":"Tor putitora","category":"EN","source":"https://www.iucnredlist.org/species/126319882/126322226","scope":"Global Species","notes":"Large cyprinid fish of Himalayan foothill rivers and connected waters; a strong swimmer whose life cycle uses flowing river habitats and migrations. Indian sites include Asan and Beas. Dams, loss of passage, destructive fishing and river degradation threaten it; distinct from Tor tor and Tor remadevii."},"hump-backed mahseer":{"name":"Hump-backed mahseer","scientificName":"Tor remadevii","category":"CR","source":"https://www.iucnredlist.org/species/56096394/56717605","scope":"Global Species","notes":"Large mahseer endemic to the Cauvery basin, with a pronounced adult back profile; associated with Ranganathittu’s river landscape. River alteration and introduced fish can affect native populations. The Himalayan golden mahseer has a different range and conservation category."},"magur":{"name":"Magur","scientificName":"Clarias magur","category":"EN","source":"https://www.iucnredlist.org/species/168255/6470089","scope":"Global Species","notes":"Native South Asian air-breathing catfish of swamps and slow freshwater habitats; an accessory breathing system helps tolerate low-oxygen conditions. Recorded at Ansupa. Wetland loss, harvesting and ecological pressures threaten it; ability to breathe air does not make it immune to pollution or habitat destruction."},"tor mahseer":{"name":"Tor mahseer","scientificName":"Tor tor","category":"DD","source":"https://www.iucnredlist.org/species/166534/126321898","scope":"Global Species","notes":"South Asian mahseer recorded from central Indian river systems including the Tawa landscape. Taxonomic/assessment uncertainty and insufficient information underlie DD; it is not evidence that populations are secure. Habitat connectivity, water quality and sustainable fishery management matter; distinguish its assessment from golden and hump-backed mahseers."},"wallago attu":{"name":"Wallago attu","scientificName":"Wallago attu","category":"VU","source":"https://www.iucnredlist.org/species/166468/174784999","scope":"Global Species","notes":"Large predatory freshwater catfish of South/Southeast Asian rivers, lakes and floodplains; fishes and other animals form its diet. Floodplain wetlands can provide breeding/feeding habitat. Overharvesting and altered river–wetland connections threaten it; it is not a marine shark despite the common label “shark catfish”."},"whale shark":{"name":"Whale shark","scientificName":"Rhincodon typus","category":"EN","source":"https://www.iucnredlist.org/species/19488/126673248","scope":"Global Species","notes":"The largest living fish, a cartilaginous shark with gills; despite its name it is neither a whale nor an air-breathing mammal. Filter-feeds on plankton and small organisms in tropical/subtropical seas. Fishing/bycatch, vessel strikes and loss of suitable feeding conditions threaten it, including in Indian waters."},"babul":{"name":"Babul","scientificName":"Vachellia nilotica","category":"LC","source":"https://www.iucnredlist.org/species/158379/187765963","scope":"Global Species","notes":"Thorny leguminous tree, formerly Acacia nilotica, occurring in tropical/subtropical landscapes. Flooded stands in Indian irrigation tanks provide secure colony nesting structure for waterbirds. The global wild-species category does not assess each planted tree; cutting, altered inundation and replacement by unsuitable invasive vegetation affect nesting habitat."},"tillai":{"name":"Tillai","scientificName":"Excoecaria agallocha","category":"LC","source":"https://www.iucnredlist.org/species/178842/7623953","scope":"Global Species","notes":"Indo-West Pacific mangrove, also called blinding tree; its latex can irritate eyes and skin. Occurs at Pichavaram and other Indian coasts. Its cultural association does not imply safe consumption. Tidal habitat loss and altered estuarine hydrology affect local populations; a mangrove tree, not a seagrass."},"wight’s cinnamon":{"name":"Wight’s cinnamon","scientificName":"Cinnamomum wightii","category":"EN","source":"https://www.iucnredlist.org/species/50126581/50131315","scope":"Global Species","notes":"Evergreen tree endemic to the Western Ghats, associated with montane evergreen/shola forests. Its occurrence at Longwood helps illustrate threatened plant diversity, not just bird conservation. Loss and fragmentation of suitable forest affect it; the status is species-specific and cannot be transferred to every cultivated cinnamon."}}};
(function(){
 const d=window.ATLAS_RAMSAR_NOTES,groups=[window.WORLD_MAP_DATA.entities,...['rivers','mountains','peaks','passes','glaciers','protectedAreas'].map(k=>window.GEOGRAPHIC_FEATURES[k]||[])];
 const plain=s=>s.replace(/\*\*/g,'');
 for(const e of groups.flat()){
  const id=e.officialFields?.['Ramsar Site Number'];const site=d.sites[id];if(!site)continue;
  e.ramsarSiteNumber=id;e.state=site.state;e.locationContext=site.state;e.subtitle=site.state;
  e.studySections=site.sections;e.speciesNotes=site.species.map(key=>d.species[key]);e.notesMarkdown=site.markdown;
  e.studyFacts=site.sections.flatMap((section,i)=>section.facts.map((text,j)=>({id:`rsis-${id}-fact-${i}-${j}`,text,source:`https://rsis.ramsar.org/ris/${id}`})));
  e.description=plain(site.sections[1].facts.join(' '));e.keyFacts=site.sections.slice(1).flatMap(s=>s.facts.map(plain));e.upscNotes='';
  e.officialFields['Administrative Region']=site.state;e.notesUpdated=d.checked;
  e.referenceLinks=[{title:'Official Ramsar Site Record',url:`https://rsis.ramsar.org/ris/${id}`}];
 }
})();
